assets/shaders/bloom_blur.frag:
#version 300 es
precision highp float;
// Separable 9-tap Gaussian blur; uDir = texel step along x or y.
in vec2 vUv;
uniform sampler2D uScene;
uniform vec2 uDir;
out vec4 fragColor;
void main() {
    float w[5] = float[5](0.227027, 0.1945946, 0.1216216, 0.054054, 0.016216);
    vec3 c = texture(uScene, vUv).rgb * w[0];
    for (int i = 1; i < 5; i++) {
        c += texture(uScene, vUv + uDir * float(i)).rgb * w[i];
        c += texture(uScene, vUv - uDir * float(i)).rgb * w[i];
    }
    fragColor = vec4(c, 1.0);
}

assets/shaders/bloom_bright.frag:
#version 300 es
precision highp float;
// Bloom bright pass (High quality): soft threshold 0.8..1 on the tonemapped scene, written at half resolution.
in vec2 vUv;
uniform sampler2D uScene;
out vec4 fragColor;
void main() {
    vec3 c = texture(uScene, vUv).rgb;
    float l = max(c.r, max(c.g, c.b));
    // soft knee from 0.8 so lens cores, glints and the hottest caustics glow without a hard threshold edge
    float k = smoothstep(0.8, 1.0, l);
    k *= k;
    fragColor = vec4(c * k, 1.0);
}

assets/shaders/bubble.frag:
#version 300 es
#include "common.glsl"
#include "lighting.glsl"
// Bubble algae cells (research 09 A6): "glossy dark-green spheres, mirror-like highlights". A thin, very smooth cell
// wall over dark green sap: GGX highlights from both fixtures, a rim that picks up the water's colour, and the sap a
// shade lighter toward the top where the light comes through. Variant (vColor.x) runs from bottle green to olive.

in vec3 vWorld;
in vec3 vNormal;
in vec2 vUv;
in vec4 vColor;

out vec4 fragColor;

void main() {
    vec3 N = normalize(vNormal);
    vec3 V = normalize(uCamPos.xyz - vWorld);
    if (dot(N, V) < 0.0) N = -N;
    float v = vColor.x;
    // bottle green to olive, light enough to read as green (not black) through the water from the room
    vec3 sap = mix(vec3(0.030, 0.150, 0.055), vec3(0.075, 0.150, 0.025), v);
    sap *= 0.8 + 0.5 * clamp(vColor.z * 0.5 + 0.5, 0.0, 1.0);
    vec3 col = shadeLit(sap, N, V, vWorld, 0.08, 1.0, 0.04, 0.3, 1.6);
    // the cell wall: mirror-like lobes and a fresnel rim of the lit water around it
    if (uQuality >= 0.5) col += wetCoat(N, V, vWorld, 0.05, 1.2);
    float rim = pow(1.0 - max(dot(N, V), 0.0), 4.0);
    col += rim * (uFog.rgb * 2.5 + uAmbientB.rgb) * (0.3 + 0.7 * lightIntensity());
    col = applyWater(col, vWorld);
    fragColor = vec4(tonemap(col), 1.0);
}

assets/shaders/bubble.vert:
#version 300 es
#include "common.glsl"
// Bubble algae (BubbleAlgaeDraw; research 09 A6): one unit sphere instanced on the rock. Each instance sits on its rock
// spot, flattened a little against the rock and sunk a third into it; iPhaseVar.x is its growth rank, so the cells
// up to uCount show and the next one swells in as the cover rises.

layout(location = 0) in vec3 aPos;
layout(location = 1) in vec3 aNormal;
layout(location = 2) in vec2 aUv;
layout(location = 3) in vec4 aColor;
layout(location = 4) in vec4 iPosScale;   // rock spot (world cm), radius (cm)
layout(location = 5) in vec4 iQuat;       // local +Y -> rock normal
layout(location = 6) in vec2 iPhaseVar;   // growth rank, colour variant 0..1

uniform float uCount;      // fractional count of cells showing (AlgaeVisuals.bubbleCount)

out vec3 vWorld;
out vec3 vNormal;
out vec2 vUv;
out vec4 vColor;

const float FLAT = 0.85;   // a turgid cell leaning on the rock is a little squat

void main() {
    float grow = clamp(uCount - iPhaseVar.x, 0.0, 1.0);
    float r = iPosScale.w * mix(0.35, 1.0, grow) * step(0.001, grow);
    vec3 lp = vec3(aPos.x, aPos.y * FLAT + 0.6, aPos.z) * r;
    vec3 p = iPosScale.xyz + qrot(iQuat, lp);
    vNormal = qrot(iQuat, normalize(vec3(aNormal.x, aNormal.y / FLAT, aNormal.z)));
    vWorld = p;
    vUv = aUv;
    vColor = vec4(iPhaseVar.y, grow, aPos.y, 1.0);
    gl_Position = uViewProj * vec4(p, 1.0);
}

assets/shaders/common.glsl:
// Shared by every ReefLive shader (ARCHITECTURE §8.4). Included right after #version.
precision highp float;
precision highp int;

// std140 `Frame` UBO, binding 0. Keep in sync with FrameUniforms.kt.
layout(std140) uniform Frame {
    mat4 uView;
    mat4 uProj;
    mat4 uViewProj;
    vec4 uCamPos;        // xyz eye (cm), w time (s)
    vec4 uLightPos[2];   // xyz AI Prime position (cm), w cos(half cone)
    vec4 uLightColor[2]; // rgb linear colour x intensity, w intensity
    vec4 uAmbientB;      // rgb ambient (keyColor x 0.18), w blue fraction
    vec4 uFog;           // rgb fog colour, w fog density (1/cm)
    vec4 uParams;        // x water level, y caustic strength, z caustic scale, w quality (0 low, 1 medium, 2 high)
    vec4 uParams2;       // x night (0/1), y algae bloom, z flow strength, w sand top (cm)
    vec4 uAbsorb;        // rgb Beer-Lambert absorption (1/cm), w scattering (1/cm)
    vec4 uTank;          // xyz interior size (cm), w dino film lifted into the water (0 day .. 1 night; AlgaeCover.dinoLift)
    vec4 uSurfaceDims;   // xy heightfield size, z 1 when heights are present, w unused
    // Algae cover 0..1 per surface (AlgaeCover, research 09 A6); packed by AlgaeVisuals.kt.
    vec4 uAlgaeGlass;    // x green film, y diatoms, z cyano, w dinos
    vec4 uAlgaeSand;     // x diatoms, y cyano, z dinos, w hair
    vec4 uAlgaeTop;      // rock tops: x hair, y cyano, z dinos, w bubble
    vec4 uAlgaeShade;    // shaded rock: x coralline, y cyano, z dinos, w bubble
    // Realism effects by quality tier (FrameUniforms.setEffects / setCasters).
    vec4 uFx;            // x contact-shadow caster count, y light-shaft strength, z caustic dispersion (0/1), w surface ripple
    vec4 uCasters[12];   // fish casting soft contact shadows: xyz mid-body (cm), w body length (cm)
    // Real-time shadow map (ShadowMap.kt): one orthographic depth pass looking down from the fixtures.
    mat4 uShadowMat;     // world -> shadow clip (orthographic, w = 1)
    vec4 uShadow;        // x on (0/1), y texel size (cm), z strength 0..1, w depth bias (cm)
};

#define uTime uCamPos.w
#define uWaterLevel uParams.x
#define uCausticStrength uParams.y
#define uCausticScale uParams.z
#define uQuality uParams.w
#define uNight uParams2.x
#define uAlgaeBloom uParams2.y
#define uFlowStrength uParams2.z
#define uBlueFraction uAmbientB.w
#define uCasterCount uFx.x
#define uShaftStrength uFx.y
#define uCausticDispersion uFx.z
#define uRipple uFx.w
#define uDinoLift uTank.w

const float PI = 3.14159265;

// Water-surface heightfield (cm above the mean level), x across the tank length, y across the depth.
uniform sampler2D uSurface;

float surfaceHeight(vec2 xz) {
    if (uSurfaceDims.z < 0.5) return 0.0;
    return textureLod(uSurface, clamp(xz / uTank.xz, 0.0, 1.0), 0.0).r;
}

vec2 surfaceSlope(vec2 xz) {
    if (uSurfaceDims.z < 0.5) return vec2(0.0);
    vec2 e = vec2(1.3, 0.0);
    return vec2(surfaceHeight(xz + e.xy) - surfaceHeight(xz - e.xy), surfaceHeight(xz + e.yx) - surfaceHeight(xz - e.yx)) / (2.0 * e.x);
}

// Render-only swell and chop on top of the simulated heightfield: the pumps and the return keep an open-top reef's
// surface rolling (Tee's tank video 2026-10-20). Five travelling waves (wavelength 41..4.6 cm, ~22-30 cm/s), bigger
// with more flow, scaled by quality (uRipple). x: height (cm), yz: slope (dh/dx, dh/dz). Shared by the water surface
// (geometry + normals) and everything lit through it (caustics, flicker), so a choppier surface throws a busier,
// brighter shimmer.
// x, z direction, wavenumber k (rad/cm), amplitude (cm); angular speed in SWELL_W (rad/s)
const vec4 SWELL[5] = vec4[5](vec4(0.94, 0.34, 0.153, 0.26), vec4(-0.6, 0.8, 0.29, 0.13), vec4(0.8, -0.6, 0.52, 0.07),
                              vec4(0.31, 0.95, 0.85, 0.04), vec4(-0.97, -0.24, 1.37, 0.022));
const float SWELL_W[5] = float[5](3.4, 6.6, 12.5, 22.0, 37.0);

// [waves]: how many of the five to sum (lighting takes the three longest; the short chop blurs out with depth).
vec3 swell(vec2 q, int waves) {
    float amp = uRipple * (0.55 + 0.55 * uFlowStrength);
    vec3 r = vec3(0.0);
    for (int i = 0; i < 5; i++) {
        if (i >= waves) break;
        vec4 w = SWELL[i];
        float ph = dot(q, w.xy) * w.z + uTime * SWELL_W[i];
        r += w.w * vec3(sin(ph), w.z * cos(ph) * w.xy);
    }
    return r * amp;
}

vec3 toLinear(vec3 srgb) { return pow(max(srgb, vec3(0.0)), vec3(2.2)); }

// Rotate v by unit quaternion q (xyzw).
vec3 qrot(vec4 q, vec3 v) { return v + 2.0 * cross(q.xyz, cross(q.xyz, v) + q.w * v); }

float hash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

float hash13(vec3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}

// Smooth 3D value noise in 0..1.
float vnoise(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    vec3 u = f * f * (3.0 - 2.0 * f);
    float a = mix(mix(hash13(i), hash13(i + vec3(1.0, 0.0, 0.0)), u.x),
                  mix(hash13(i + vec3(0.0, 1.0, 0.0)), hash13(i + vec3(1.0, 1.0, 0.0)), u.x), u.y);
    float b = mix(mix(hash13(i + vec3(0.0, 0.0, 1.0)), hash13(i + vec3(1.0, 0.0, 1.0)), u.x),
                  mix(hash13(i + vec3(0.0, 1.0, 1.0)), hash13(i + vec3(1.0, 1.0, 1.0)), u.x), u.y);
    return mix(a, b, u.z);
}

// Three-octave value noise, mean ~0.5, sd ~0.12.
float fbm3(vec3 p) {
    return vnoise(p) * 0.5 + vnoise(p * 2.03 + 17.1) * 0.3 + vnoise(p * 4.11 + 41.7) * 0.2;
}

// Patchy algae mask: about `cover` of the surface area lies inside a patch (fbm3 value n is remapped to
// ~uniform with a logistic approximation of its CDF, then thresholded at 1 - cover with soft edges).
float algaePatch(float n, float cover) {
    float c = clamp(cover, 0.0, 1.0);
    if (c < 0.001) return 0.0;
    float u = 1.0 / (1.0 + exp(-14.5 * (n - 0.5)));
    float t = 1.0 - c;
    return max(smoothstep(t - 0.04, t + 0.04, u), smoothstep(0.85, 1.0, c));
}

// Opacity inside a patch: thin film at low cover, dense mat at bloom levels.
// Green star polyp mat margin (GspMatDraw, gsp_mat.frag, polyp.vert): the mat reaches [r] cm along the rock, with a
// lobed edge and thin stolon runners reaching ahead of it ([op] = position in the rock's own frame).
float gspEdge(vec3 op, float r) {
    float lobes = (vnoise(op * 0.21) - 0.5) * 4.0;              // value noise sits near 0.5: about -1..1
    // runners: the 0.5 level lines of a finer noise (2-3 mm wide), only where a broad mask lets one grow
    float line = 1.0 - smoothstep(0.03, 0.09, abs(vnoise(op * 0.6 + vec3(7.0, 3.0, 1.0)) - 0.5));
    float run = line * smoothstep(0.52, 0.62, vnoise(op * 0.13 + vec3(2.0, 9.0, 4.0)));
    return r + min(r * 0.15, 1.4) * lobes + min(r * 0.35, 2.4) * run;
}

float algaeDensity(float cover) { return mix(0.4, 0.75, smoothstep(0.0, 0.5, cover)); }

// Length of the segment a->b that lies inside the water volume (box 0..tank, below the surface).
float waterPath(vec3 a, vec3 b) {
    vec3 d = b - a;
    vec3 lo = vec3(0.0);
    vec3 hi = vec3(uTank.x, uWaterLevel, uTank.z);
    vec3 inv = 1.0 / mix(d, vec3(1e-5), vec3(lessThan(abs(d), vec3(1e-5))));
    vec3 t0 = (lo - a) * inv;
    vec3 t1 = (hi - a) * inv;
    vec3 tmin = min(t0, t1);
    vec3 tmax = max(t0, t1);
    float tn = max(max(tmin.x, tmin.y), max(tmin.z, 0.0));
    float tf = min(min(tmax.x, tmax.y), min(tmax.z, 1.0));
    return max(tf - tn, 0.0) * length(d);
}

// Branching-tree sway (Kenya tree, extras.swayMode = 1; measured from Tee's clip, research/video/coral_kenya.md [H]):
// a slow whole-crown lean (period ~7 s) plus a quicker branch-tip sway (~2 s) whose phase lags with distance from the
// base, a little cross-flow wander, and a brief local ripple round a passing fish (wake.xyz world cm, wake.w 0..1).
// The stalk and trunk bases (r < ~25 % of the height from uBase) stay put. static.vert (body) and polyp.vert (sprigs,
// evaluated at the instance base) call it with the same arguments, so the sprigs ride their branch.
vec3 treeSway(vec3 p, vec3 base, float height, float phase, vec3 dir, float amp, vec4 wake) {
    float r = clamp(length(p - base) / max(height, 1.0), 0.0, 1.2);
    float wgt = pow(smoothstep(0.2, 1.0, r), 1.5);
    float sp = dot(p.xz, vec2(0.23, 0.17));          // neighbouring branches move together, distant ones drift apart
    float lean = sin(uTime * 0.9 + phase);
    float tip = sin(uTime * 3.14 + phase * 1.7 + sp - 1.6 * wgt);
    vec3 side = vec3(-dir.z, 0.0, dir.x);
    vec3 off = dir * (amp * wgt * (0.65 * lean + 0.35 * tip))
             + side * (amp * wgt * 0.2 * sin(uTime * 2.3 + sp * 1.3 + phase));
    off.y -= 0.1 * amp * wgt * (0.5 + 0.5 * lean);
    if (wake.w > 0.0) {
        vec3 q = p - wake.xyz;
        float dq = length(q);
        float fall = exp(-dq * dq / 30.0);           // ~5.5 cm radius
        off += (q / max(dq, 0.5)) * (wake.w * fall * wgt * 0.7 * (0.55 + 0.45 * sin(uTime * 7.0 - dq * 1.1)));
    }
    return off;
}

assets/shaders/composite.frag:
#version 300 es
precision highp float;
// Final composite: resolved scene + bloom (High), and the follow-mode lens (PostFx): everything outside the
// followed fish's focus circle blends toward a half-resolution blur (cheap depth-of-field look), with a soft
// vignette and a little chromatic aberration that grows toward the corners. uLens.x fades the whole lens.
in vec2 vUv;
uniform sampler2D uScene;
uniform sampler2D uBloom;
uniform sampler2D uDof;
uniform float uBloomStrength;
uniform vec4 uLens;   // x amount 0..1, y vignette strength, z chromatic aberration (uv at the corners), w aspect (w/h)
uniform vec3 uFocus;  // xy focus centre (uv), z sharp radius (v units)
out vec4 fragColor;

void main() {
    vec3 c;
    float amt = uLens.x;
    if (amt > 0.001) {
        vec2 fromC = vUv - 0.5;
        float edge = dot(fromC, fromC);                 // 0 at the centre, 0.5 in the corners
        vec2 ca = fromC * (uLens.z * amt * edge * 4.0);
        vec3 sharp = vec3(texture(uScene, vUv - ca).r, texture(uScene, vUv).g, texture(uScene, vUv + ca).b);
        vec3 soft = vec3(texture(uDof, vUv - ca * 1.5).r, texture(uDof, vUv).g, texture(uDof, vUv + ca * 1.5).b);
        vec2 d = (vUv - uFocus.xy) * vec2(uLens.w, 1.0);
        float k = smoothstep(uFocus.z, uFocus.z * 2.2 + 0.06, length(d)) * amt;
        c = mix(sharp, soft, k);
        float vig = 1.0 - uLens.y * amt * smoothstep(0.45, 1.0, length(fromC) * 1.414);
        c *= vig;
    } else {
        c = texture(uScene, vUv).rgb;
    }
    // screen blend: highlights bloom into a soft halo instead of clipping to flat white
    if (uBloomStrength > 0.0) c = 1.0 - (1.0 - c) * (1.0 - min(texture(uBloom, vUv).rgb * uBloomStrength, vec3(1.0)));
    fragColor = vec4(min(c, vec3(1.0)), 1.0);
}

assets/shaders/fish.frag:
#version 300 es
// A fish never darkens itself with its own contact shadow (lighting.glsl shadeLit).
#define NO_CONTACT_SHADOW 1
#include "common.glsl"
#include "lighting.glsl"
// Fish skin (ARCHITECTURE §8.4 items 5-6). Define FIN for the translucent two-sided fin sheet variant.

in vec3 vWorld;
in vec3 vNormal;
in vec2 vUv;
in vec4 vColor;

uniform sampler2D uAlbedo;
uniform sampler2D uIridLut;
uniform vec4 uBaseColor;     // linear RGBA factor
uniform float uHasTexture;
uniform float uRoughness;
uniform float uIridStrength;
uniform float uDesat;
uniform float uTone;         // own colour change, -1 pale .. +1 dark and mottled (lawnmower blenny, research 51)
uniform float uIchSpots;     // 0..1 white spot coverage (ich)
uniform vec4 uSkin;          // disease skin signs 0..1 (SIMULATION §3.5): x velvet gold dust, y fin rot, z HLLE pits, w mucus film
uniform float uEyeCloud;
uniform float uPart;         // 0 body, 1 fin, 2 eye, 3 leg/antenna
uniform float uDead;
uniform float uFade;         // microfauna: 0 full contrast .. 1 lost in the water (MicroCritterVisuals)
uniform float uBlueDeepen;   // blue tang colour change 0..1 (core Organism.blueDeepen): deeper blue, black marks fade
uniform vec4 uChroma;        // bobtail squid (core SquidRig): x chromatophore expansion, y passing-cloud strength, z light-organ glow, w 1 + cloud phase (0 = off)
// Life stages (LifeStageVisuals.kt, additive): a second body texture painted on the same UV layout, mixed in by
// uStageMix while a fish grows from one stage's pattern into the next (or changes sex). 0 = unchanged.
uniform sampler2D uAlbedoStage;
uniform float uStageMix;

out vec4 fragColor;

// Procedural ich: sparse round white dots in texture space (size ~1-2 texels of a 140-cell grid).
float ichMask(vec2 uv) {
    vec2 g = uv * 140.0;
    vec2 cell = floor(g);
    float h = hash12(cell);
    float on = step(0.92 - uIchSpots * 0.3, h);
    vec2 c = vec2(hash12(cell + 7.1), hash12(cell + 3.7)) * 0.5 + 0.25;
    float r = mix(0.18, 0.34, hash12(cell + 1.3));
    float d = length(fract(g) - c);
    return on * (1.0 - smoothstep(r * 0.6, r, d));
}

// Smooth 2D value noise in texture space (disease skin signs: fin-rot edge, mucus sheets).
float vnoise2(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash12(i), hash12(i + vec2(1.0, 0.0)), f.x), mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), f.x), f.y);
}

void main() {
    vec4 tex = uHasTexture > 0.5 ? texture(uAlbedo, vUv) : vec4(1.0);
    if (uStageMix > 0.001 && uHasTexture > 0.5) tex = mix(tex, texture(uAlbedoStage, vUv), clamp(uStageMix, 0.0, 1.0));
    vec3 albedo = toLinear(tex.rgb) * uBaseColor.rgb;
    float alpha = tex.a * uBaseColor.a;

    vec3 V = normalize(uCamPos.xyz - vWorld);
    vec3 N = normalize(vNormal);
#ifdef FIN
    if (!gl_FrontFacing) N = -N;
#endif
    if (dot(N, V) < 0.0) N = -N; // two-sided safety for thin parts

    // symptoms
    if (uIchSpots > 0.001 && uPart < 1.5) albedo = mix(albedo, vec3(0.92), ichMask(vUv) * min(uIchSpots * 3.0, 1.0));
    // Disease skin signs, each skipped at 0 (one uniform test): research 01 §4.3, 18 §5.4.
    // Each sign is drawn at a scale that reads at a normal viewing distance (a fish ~150-300 px long) and keeps a mean
    // that stays visible once its detail is smaller than a pixel (fwidth fade), so it neither vanishes nor sparkles.
    float velvetDust = 0.0;
    if (uSkin.x > 0.001 && uPart < 1.5) {
        // velvet (Amyloodinium): the fish looks dusted with fine gold-yellow powder, densest on the upper body, and its
        // own colours go dull under it. Round specks in a ~110-cell grid, more of them as the infection grows.
        float v = clamp(uSkin.x, 0.0, 1.0);
        vec2 g = vUv * vec2(110.0, 62.0);
        vec2 cell = floor(g);
        float cover = 0.3 + 0.45 * v;
        float on = step(1.0 - cover, hash12(cell + 1.7));
        float d = length(fract(g) - (vec2(hash12(cell + 6.1), hash12(cell + 2.9)) * 0.5 + 0.25));
        float speck = on * (1.0 - smoothstep(0.16, 0.3, d));
        // sub-pixel specks fade to their mean coverage (a gold veil) instead of shimmering
        speck = mix(speck, cover * 0.2, smoothstep(0.35, 0.9, max(fwidth(g.x), fwidth(g.y))));
        float lumA = dot(albedo, vec3(0.2126, 0.7152, 0.0722));
        // a dull, dusty film: colour drains toward a pale khaki, then the gold specks sit on top
        albedo = mix(albedo, vec3(lumA) * 0.55 + vec3(0.52, 0.46, 0.3) * 0.45, v * 0.38);
        albedo = mix(albedo, vec3(0.98, 0.82, 0.38), clamp(speck * (0.55 + 0.45 * v), 0.0, 1.0));
        velvetDust = v * (0.35 + speck);
    }
    if (uSkin.z > 0.001 && uPart < 0.5 && uChroma.w < 0.5) {
        // HLLE: pale eroded skin on the head and along the lateral line (site mask from fish.vert in vColor.r), pocked
        // with dark-centred pits that run together into lesions as the erosion advances
        float z = clamp(uSkin.z, 0.0, 1.0);
        float site = clamp(vColor.r, 0.0, 1.0);
        float erode = site * smoothstep(0.62 - 0.45 * z, 0.9 - 0.3 * z, vnoise2(vUv * vec2(26.0, 14.0) + 3.3));
        vec2 g = vUv * vec2(36.0, 20.0);
        vec2 cell = floor(g);
        float on = step(1.0 - (0.35 + 0.55 * z) * site, hash12(cell + 2.7));
        float d = length(fract(g) - (vec2(hash12(cell + 5.1), hash12(cell + 9.3)) * 0.4 + 0.3));
        float r = mix(0.24, 0.42, hash12(cell + 3.3)) * (0.8 + 0.3 * z);
        float pit = on * (1.0 - smoothstep(r * 0.5, r, d));
        float rim = on * smoothstep(r * 0.5, r, d) * (1.0 - smoothstep(r, r * 1.4, d));
        // pits smaller than a pixel melt into their mean darkening
        float far = smoothstep(0.35, 0.9, max(fwidth(g.x), fwidth(g.y)));
        pit = mix(pit, on * 0.35 * r, far); rim = mix(rim, on * 0.3 * r, far);
        vec3 raw = vec3(0.74, 0.7, 0.62);   // exposed, pigment-less tissue
        albedo = mix(albedo, raw, clamp(erode * (0.45 + 0.4 * z) + rim * 0.7, 0.0, 0.9));
        albedo = mix(albedo, vec3(0.16, 0.12, 0.1), pit * (0.6 + 0.3 * z));
    }
    float mucusSheet = 0.0;
    if (uSkin.w > 0.001 && uPart < 1.5) {
        // Brooklynella: thick greyish-white mucus that sloughs off in sheets and strands; the skin under it greys out
        float m = clamp(uSkin.w, 0.0, 1.0);
        float blot = vnoise2(vUv * vec2(7.0, 4.0) + 1.3) * 0.65 + vnoise2(vUv * vec2(24.0, 9.0) + 7.7) * 0.35;
        // strands peeling back along the body (stretched noise), faded once finer than a pixel
        float strand = vnoise2(vUv * vec2(5.0, 40.0) + 2.1);
        strand = mix(strand, 0.5, smoothstep(0.4, 1.0, fwidth(vUv.y * 40.0)));
        mucusSheet = clamp(smoothstep(0.62 - 0.35 * m, 0.85 - 0.2 * m, blot) + 0.35 * smoothstep(0.6, 0.85, strand) * m, 0.0, 1.0);
        float lumM = dot(albedo, vec3(0.2126, 0.7152, 0.0722));
        albedo = mix(albedo, vec3(lumM) * 0.7 + vec3(0.25), m * 0.35);
        albedo = mix(albedo, vec3(0.86, 0.88, 0.87), mucusSheet * (0.35 + 0.4 * m));
    }
    float lum = dot(albedo, vec3(0.2126, 0.7152, 0.0722));
    // negative = more saturated (a displaying male fairy wrasse)
    albedo = max(mix(albedo, vec3(lum), clamp(uDesat, -0.5, 1.0)), 0.0);
    if (abs(uTone) > 0.01 && (uPart < 1.5)) {
        // melanophores spread in soft blotches over the back first: dark goes on mottled, pale washes the blotches out
        vec2 gb = vUv * vec2(9.0, 5.0);
        vec2 cb = floor(gb);
        float blot = 1.0 - smoothstep(0.15, 0.5, length(fract(gb) - (vec2(hash12(cb + 4.2), hash12(cb + 8.6)) * 0.5 + 0.25)));
        float k = clamp(uTone, -1.0, 1.0);
        if (k > 0.0) albedo *= 1.0 - k * (0.35 + 0.4 * blot);
        else albedo = mix(albedo, vec3(lum) * 0.5 + vec3(0.55, 0.52, 0.45) * 0.5, -k * 0.6);
    }
    if (uBlueDeepen > 0.001 && uPart < 1.5) {
        // blue tang in a display or under acute social stress (research 06 §4.1.3, §5.4; S:ADW-tang): the blue skin
        // deepens and saturates and the black marks fade toward navy. Blue = blue well above red and green; black = very dark.
        float kb = clamp(uBlueDeepen, 0.0, 1.0);
        float blueSkin = smoothstep(0.03, 0.15, albedo.b - max(albedo.r, albedo.g));
        albedo = mix(albedo, albedo * vec3(0.35, 0.6, 1.3), kb * blueSkin);
        float black = 1.0 - smoothstep(0.05, 0.16, max(albedo.r, max(albedo.g, albedo.b)));
        albedo = mix(albedo, vec3(0.04, 0.09, 0.3), kb * black * 0.65);
    }
#ifndef FIN
    // the mouth lining (fish.vert writes it to vColor.g for a model with a jaw): dark flesh, seen in shadow
    if (uPart < 0.5) albedo = mix(albedo, vec3(0.09, 0.035, 0.04), 0.9 * clamp(vColor.g, 0.0, 1.0));
#endif
    if (uPart > 1.5 && uPart < 2.5) albedo = mix(albedo, vec3(0.62, 0.64, 0.66), uEyeCloud * 0.85);

    // Squid skin: procedural chromatophores over the texture that expand (dark) and retract (pale) within a fraction
    // of a second, dark "passing clouds" running along the body, and the ventral light-organ glow (body only).
    float sqGlow = 0.0;
    if (uChroma.w > 0.5 && (uPart < 0.5 || uPart > 2.5)) {
        float dorsal = uPart < 0.5 ? vColor.r : 0.7;
        float cloud = uChroma.y * smoothstep(0.3, 1.0, sin(2.0 * PI * (vColor.a * 2.5 - (uChroma.w - 1.0))));
        float ex = clamp(uChroma.x + 0.5 * cloud, 0.0, 1.0);
        vec2 g = vUv * vec2(70.0, 200.0);
        vec2 cell = floor(g);
        vec2 cc = vec2(hash12(cell + 2.3), hash12(cell + 5.9)) * 0.6 + 0.2;
        float on = step(1.0 - (0.25 + 0.6 * dorsal), hash12(cell));
        float r = mix(0.08, 0.46, ex) * mix(0.6, 1.0, hash12(cell + 9.1));
        float dt = on * (1.0 - smoothstep(r * 0.65, r, length(fract(g) - cc)));
        // far away the cells are sub-pixel: fade to their mean coverage instead of shimmering
        dt = mix(dt, on * 2.6 * r * r, smoothstep(0.35, 0.9, max(fwidth(g.x), fwidth(g.y))));
        vec3 pig = mix(vec3(0.16, 0.05, 0.015), vec3(0.45, 0.2, 0.05), hash12(cell + 4.4));
        albedo = mix(albedo, pig, clamp(dt, 0.0, 1.0) * 0.9);
        albedo *= 1.0 - 0.25 * ex * dorsal;
        albedo = mix(albedo, albedo * 1.15 + 0.03, (1.0 - ex) * 0.3);
        if (uPart < 0.5) sqGlow = uChroma.z * (1.0 - smoothstep(0.1, 0.45, dorsal));
    }

    // scale / shell micro-relief: offset rows of rounded scales in texture space (body only, Medium+), faded out
    // once a scale is smaller than a pixel so it never sparkles
    if (uQuality >= 0.5 && uChroma.w < 0.5) {   // squid skin (uChroma) is scaleless
        vec2 g = vUv * vec2(70.0, 38.0);
        g.x += 0.5 * mod(floor(g.y), 2.0);
        vec2 f = fract(g) - vec2(0.5, 0.35);
        // soft dome per scale: a wide falloff keeps the edge slopes gentle, so up close the scale rows read as relief
        // in the diffuse light instead of a bright net of specular glints along every scale edge
        float scale = 1.0 - smoothstep(0.05, 0.4, dot(f, f));
        float vis = (1.0 - smoothstep(0.12, 0.35, length(fwidth(g)))) * step(uPart, 0.5);
        N = bumpH(N, vWorld, scale * vis * 0.003);
    }
    // view-angle terms (rim, fresnel, iridescence, clear coat) use the smooth body normal: on the scale relief they
    // light up every scale edge as a white grid when the camera is close
    vec3 Ng = normalize(vNormal);
#ifdef FIN
    if (!gl_FrontFacing) Ng = -Ng;
#endif
    if (dot(Ng, V) < 0.0) Ng = -Ng;
    float ndv = max(dot(Ng, V), 0.0);
    float specScale = mix(1.0, 0.25, uNight) * (1.0 - 0.7 * uDead);
#ifdef FIN
    vec3 col = shadeLit(albedo, N, V, vWorld, max(uRoughness, 0.4), 1.0, 0.03, 0.5, specScale * 0.5);
    // back-lit fins glow a little (thin membrane)
    // (each fixture with its own direction; none inside a shadow)
    vec3 Lb0, Lb1;
    vec3 rad0 = fixtureAt(0, Lb0), rad1 = fixtureAt(1, Lb1);
    float bl0 = clamp(dot(V, -Lb0), 0.0, 1.0), bl1 = clamp(dot(V, -Lb1), 0.0, 1.0);
    col += albedo * (rad0 * (bl0 * bl0 * bl0) + rad1 * (bl1 * bl1 * bl1))
        * 0.35 * gShadow;
    alpha *= 0.75 + 0.25 * ndv;
    if (uIchSpots > 0.001) col = mix(col, vec3(0.8) * lightIntensity(), ichMask(vUv * 0.5) * uIchSpots * 0.6);
    if (uSkin.y > 0.001) {
        // bacterial fin rot: the membrane is eaten back from the edge in ragged notches (hinge vColor.b: 0 base .. 1
        // edge) with a whitish necrotic margin; a severe case loses about half the fin
        // (the fine octave fades out once it is finer than a pixel, and the cut is antialiased over one pixel of the
        // hinge coordinate: a hard step on the ragged edge read as a hatch / moiré up close and as crawling far off)
        vec2 gf = vUv * vec2(120.0, 45.0);
        float fine = mix(vnoise2(gf), 0.5, smoothstep(0.3, 0.8, max(fwidth(gf.x), fwidth(gf.y))));
        float rag = 0.7 * vnoise2(vUv * vec2(30.0, 11.0) + 4.1) + 0.3 * fine;
        float edge = 1.0 - uSkin.y * (0.18 + 0.4 * rag);
        float h = clamp(vColor.b, 0.0, 1.0);
        float aa = max(fwidth(h - edge), 1e-4);
        alpha *= 1.0 - smoothstep(edge - aa, edge + aa, h);
        col = mix(col, vec3(0.75, 0.72, 0.66) * lightIntensity(), uSkin.y * 0.7 * smoothstep(edge - 0.12 - aa, edge, h));
    }
    if (alpha < 0.03) discard;
#else
    vec3 col = shadeLit(albedo, N, V, vWorld, uRoughness, 1.0, 0.04, 0.15, specScale);
    // thin-film iridescence (LUT ramp by view angle) added to the specular response
    vec3 irid = toLinear(texture(uIridLut, vec2(ndv, 0.5)).rgb) * uIridStrength * (1.0 - clamp(uDesat, 0.0, 1.0));
    vec3 Lk;
    vec3 rad = fixtureAt(0, Lk) + fixtureAt(1, Lk);
    float shade = gShadow;
    col += irid * rad * (0.35 + 0.65 * pow(1.0 - ndv, 2.0)) * shade;
    // wet skin / shell: a tight clear-coat highlight over the body's own roughness
    col += wetCoat(Ng, V, vWorld, 0.14, 0.35 * specScale) * shade;
    // Fish were nearly invisible against the rock and the blue water. A soft camera-side fill lets the body
    // pattern read in the shade, and a stronger rim (light colour plus a little of the fish's own colour)
    // separates the silhouette from the background. Both follow the light, so night stays dark.
    vec3 lightSum = (uLightColor[0].rgb + uLightColor[1].rgb) * 0.5;
    col += albedo * 0.16 * (0.15 + lightIntensity());
    // up close the silhouette needs no help and an unattenuated rim reads as a pale outline: ease it in with distance
    float rim = pow(1.0 - ndv, 2.2) * mix(0.45, 1.0, smoothstep(15.0, 60.0, distance(uCamPos.xyz, vWorld)));
    // the rim is brightest on the top edge (light from the fixtures above) and picks up the water colour below
    float top = clamp(Ng.y * 0.5 + 0.5, 0.0, 1.0);
    col += rim * (0.40 * lightSum * (0.6 + 0.8 * top) + 0.30 * albedo * lightIntensity() + uFog.rgb * 0.6 * (1.0 - top));
    // inside the open mouth is in its own shadow: no sheen or rim from the lights
    col *= 1.0 - 0.8 * clamp(vColor.g, 0.0, 1.0);
    alpha = 1.0;
    // counter-illumination: a faint blue-green glow from the ventral light organ, strongest seen from below
    col += vec3(0.35, 0.62, 0.95) * sqGlow * 0.06 * (0.3 + 0.7 * smoothstep(0.0, -0.7, N.y));
#endif
    if (uSkin.w > 0.001 && uPart < 1.5) {
        // Brooklynella: the mucus is a translucent milky film over the lit skin, thickest in the sloughing sheets and
        // where it is seen at a glancing angle; it scatters light, so it stays visible in the shade
        float m = clamp(uSkin.w, 0.0, 1.0);
        float film = m * (0.18 + 0.35 * mucusSheet + 0.25 * pow(1.0 - ndv, 2.0));
        col = mix(col, vec3(0.8, 0.83, 0.83) * (0.3 + 0.7 * lightIntensity()), clamp(film, 0.0, 0.7));
    }
    // velvet's dusty sheen: the gold dust catches the light, most toward the silhouette
    if (velvetDust > 0.001) col += vec3(0.55, 0.42, 0.12) * velvetDust * (0.12 + 0.35 * pow(1.0 - ndv, 1.5)) * lightIntensity();
    col = applyWater(col, vWorld);
    // distant microfauna sink into the water colour, so specks melt away instead of popping out
    col = mix(col, uFog.rgb, uFade * 0.85);
    fragColor = vec4(tonemap(col), alpha);
}

assets/shaders/fish.vert:
#version 300 es
#include "common.glsl"
// Spline skinning on the GPU (ARCHITECTURE §8.4 item 4, SIMULATION §4.8). Models are unit length, facing
// +X, snout at x = +0.5; COLOR_0.a = spine coordinate u (0 snout .. 1 tail), COLOR_0.g = gill mask,
// COLOR_0.b = fin hinge (0 base .. 1 tip).

layout(location = 0) in vec3 aPos;
layout(location = 1) in vec3 aNormal;
layout(location = 2) in vec2 aUv;
layout(location = 3) in vec4 aColor;

uniform vec4 uSpine[16];   // xyz world cm, head -> tail
uniform vec4 uFrame[16];   // quaternion: model X(forward)/Y(up)/Z(side) -> world
uniform float uScale;      // body length (cm)
uniform vec4 uSwim;        // x phase (cycles), y amp (BL), z waveLen, w appendage phase
uniform vec4 uFin;         // x pectoral (0 folded..1 spread), y clamp, z gill, w gill rate (Hz)
uniform vec4 uShape;       // x thin, y part (0 body, 1 fin, 2 eye, 3 leg/antenna), z eye yaw, w fin kind (0 median, 1 pectoral, 2 caudal, 3 pelvic)
uniform vec2 uBodyEnv;     // body-wave envelope: x exponent (stiff front half = high), y head amplitude share (0..1)
uniform vec4 uMotion;      // x pectoral stroke phase (cycles), y stroke sweep (0 = legacy flutter), z C-start bend (+ = toward +Z), w mode (0 fish, 1 brittle-star arm rowing, 2 shrimp, 3 crab legs, 4 bobtail squid, 5 hermit crab, 7 flame scallop / maxima clam, 8 snail, 9 urchin, 10 sea cucumber)
uniform float uPick;       // shrimp: picking / feeding (mouth) 0..1; fish with a jaw: mouth opening 0..1
uniform float uFold;       // first dorsal folded flat 0..1 (firefish flick, OrganismPose.finFold)
uniform vec4 uJaw;         // fish jaw (GLB extras.jaw): xy hinge (model space), z widest gape (rad), w 1 = has a jaw
uniform vec3 uEyePivot;    // eye centre in model space (extras.pivot)
uniform float uRigid;      // 1: no skinning (sessile / cm-unit models); uModel places them
uniform mat4 uModel;
// Sickness (core OrganismPose, SIMULATION §3.5 / §10): x heat gasping 0..1 (operculum flared and pumping, mouth working
// against it), y heat-death spasms 0..1 (short irregular body-bend jerks). 0 = healthy, skipped.
uniform vec2 uSick;
uniform vec3 uStageShape;   // life stage (LifeStageVisuals.kt, additive): x body depth − 1, y body width − 1; 0 = as built
// Limb pose from the sim (SIMULATION §19, core LimbRig), uLimb[]: shrimp (mode 2) send 15 entries (core ShrimpLimbs), uLimb[0] = (x stride
// phase (cycles), y stepping 0..1, z rock / claw-display signal, w antenna grooming), read by the per-class shrimp
// limb path below. Crawlers (uLimbOn): mode 1 brittle star arms, mode 3 Sally Lightfoot legs + chelae, mode 5 hermit crab.
// The disc / carapace is placed rigidly at the organism (spine station 0); each limb vertex (part 3, COLOR_0.r = t
// along the limb, COLOR_0.b = limb index / 9) is posed about its pivot from the sim's per-limb data.
uniform float uLimbOn;     // 1: the model has extras.limbPivots and the pose carries limbs
uniform vec4 uLimb[40];    // per-limb pose (layout per animal: core BrittleArms (40) / CrabLegs (19) / ShrimpLimbs (15) / HermitLegs (15))
uniform vec4 uLimbPivot[10]; // model-space limb root xyz, w = rest limb length (model units)

// Sea cucumber mouth centre in model space at the oral ring's spine station (tools/blender/sea_cucumber.py)
const vec3 CUKE_MOUTH = vec3(0.006, 0.0137, 0.0);

// Anti-clipping limits (the renderer also caps the spine bend per segment, FishRig.limitBend).
const float MAX_WAVE_AMP = 0.12;   // lateral swim wave at the tail, body lengths
// Heat-death spasm (uSick.y) peak bend, and the most bend a fish body takes with a C-start on top (uMotion.z units:
// the tail swings ~0.55 × bend × 0.38 body lengths sideways, so 0.6 → ~0.13 BL, 0.9 → ~0.19 BL)
const float SPASM_BEND = 0.6;
const float MAX_FISH_BEND = 0.9;

out vec3 vWorld;
out vec3 vNormal;
out vec2 vUv;
out vec4 vColor;

vec3 catmull(vec3 p0, vec3 p1, vec3 p2, vec3 p3, float t) {
    float t2 = t * t, t3 = t2 * t;
    return 0.5 * ((2.0 * p1) + (-p0 + p2) * t + (2.0 * p0 - 5.0 * p1 + 4.0 * p2 - p3) * t2 + (-p0 + 3.0 * p1 - 3.0 * p2 + p3) * t3);
}

void sampleSpine(float u, out vec3 pos, out vec4 q) {
    float f = clamp(u, 0.0, 1.0) * 15.0;
    int i = int(min(floor(f), 14.0));
    float t = f - float(i);
    vec3 p0 = uSpine[max(i - 1, 0)].xyz;
    vec3 p1 = uSpine[i].xyz;
    vec3 p2 = uSpine[i + 1].xyz;
    vec3 p3 = uSpine[min(i + 2, 15)].xyz;
    // extrapolate the end tangents so the head/tail are not pinched
    if (i == 0) p0 = 2.0 * p1 - p2;
    if (i == 14) p3 = 2.0 * p2 - p1;
    pos = catmull(p0, p1, p2, p3, t);
    vec4 qa = uFrame[i];
    vec4 qb = uFrame[i + 1];
    if (dot(qa, qb) < 0.0) qb = -qb;
    q = normalize(mix(qa, qb, t));
}

vec3 rotAxis(vec3 v, vec3 a, float ang) {
    float c = cos(ang), s = sin(ang);
    return v * c + cross(a, v) * s + a * dot(a, v) * (1.0 - c);
}

// Brittle star arms (mode 1, core BrittleArms; SIMULATION §19.2, §19.7). The sim marches each arm out from the disc in
// STAR_N equal steps fitted to the rock, sand, glass and animals under it and sends, per arm k (uLimb[8k .. 8k + 7]),
// each step's direction psi_j (rad from the arm's rest direction, + = toward the model's left, -Z) and the height y_j
// of its end above the disc's ground plane (model units). Heights 1..8 ride in the x slots as 0.5 + 0.5 y (x is lerped
// as a phase in [0, 1) by the renderer); the plain slots n = 0.. hold psi_1..15, then y_9..15, then the arm's length.
const int STAR_N = 15;

float starSlot(int k, int n) {
    vec4 e = uLimb[8 * k + n / 3];
    int c = n - 3 * (n / 3);
    return c == 0 ? e.y : (c == 1 ? e.z : e.w);
}

float starPsi(int k, int j) { return starSlot(k, j - 1); }

float starY(int k, int j) {
    if (j <= 0) return 0.0;
    if (j <= 8) return 2.0 * uLimb[8 * k + j - 1].x - 1.0;
    return starSlot(k, j + 6);
}

// Nodes j - 1 .. j + 2 of arm k's centreline relative to its root node 0 (the sim's BrittleArms.nodes), in one pass:
// each step runs a step length, of which the height change takes its share (never less than 0.3 of the run, as a
// steep climb keeps). The curve's end tangents are extrapolated (a node outside 0..STAR_N mirrors its neighbour).
void starNodes(int k, int j, float a0, float seg, out vec3 p0, out vec3 p1, out vec3 p2, out vec3 p3) {
    vec3 p = vec3(0.0);
    float yPrev = 0.0;
    p0 = p; p1 = p; p2 = p; p3 = p;
    for (int i = 1; i <= STAR_N; i++) {
        if (i > j + 2) break;
        float psi = a0 + starPsi(k, i);
        float y = starY(k, i);
        float dy = y - yPrev;
        float hz = sqrt(max(seg * seg - dy * dy, 0.09 * seg * seg));
        p += vec3(cos(psi) * hz, dy, -sin(psi) * hz);
        yPrev = y;
        if (i == j - 1) p0 = p;
        if (i == j) p1 = p;
        if (i == j + 1) p2 = p;
        if (i == j + 2) p3 = p;
    }
    if (j == 0) p0 = 2.0 * p1 - p2;
    if (j + 2 > STAR_N) p3 = 2.0 * p2 - p1;
}

// Poses one brittle star arm vertex: the rest arm is straight from the pivot along a0 = atan(-P.z, P.x); the drawn
// centreline is the Catmull-Rom curve through the sim's nodes (end tangents extrapolated), the cross-section rides on
// its frame. Vertices past the arm's current length (autotomy, regrowth) collapse onto the stump.
void starArm(int k, inout vec3 local, inout vec3 n) {
    vec4 P = uLimbPivot[k];
    float a0 = atan(-P.z, P.x);
    vec3 d0 = vec3(cos(a0), 0.0, -sin(a0));
    vec3 l0 = vec3(-sin(a0), 0.0, -cos(a0));
    vec3 off = local - P.xyz;
    float along = dot(off, d0);
    float lat = dot(off, l0);
    float up = off.y;
    float lenK = clamp(starSlot(k, 22), 0.1, 1.0);
    float s = clamp(aColor.r, 0.0, 1.0);
    float keep = 1.0 - step(lenK + 0.001, s);
    s = min(s, lenK);
    float ax = along - s * P.w;
    float seg = P.w / float(STAR_N);
    float sN = s * float(STAR_N);
    int j = int(min(floor(sN), float(STAR_N - 1)));
    float t = sN - float(j);
    vec3 p0, p1, p2, p3;
    starNodes(k, j, a0, seg, p0, p1, p2, p3);
    vec3 c = P.xyz + catmull(p0, p1, p2, p3, t);
    float t2 = t * t;
    vec3 T = normalize(0.5 * ((-p0 + p2) + 2.0 * (2.0 * p0 - 5.0 * p1 + 4.0 * p2 - p3) * t + 3.0 * (-p0 + 3.0 * p1 - 3.0 * p2 + p3) * t2) + d0 * 1e-4);
    vec3 L = normalize(vec3(T.z, 0.0, -T.x) + l0 * 1e-4);
    vec3 U = cross(T, L);
    local = c + (T * ax + L * lat + U * up) * keep;
    n = T * dot(n, d0) + L * dot(n, l0) + U * n.y;
}

// Poses one Sally Lightfoot limb vertex about its pivot. Legs (k 0..7; uLimb = phase, signed extension stroke, foot
// lift, tuck): swing in the first half of the step cycle (foot lifted), stance in the second (foot planted while the
// leg flexes or extends along its length); tuck draws the legs in and down. Chelae (8, 9; uLimb = pick phase,
// stroke, reach): dip to the rock and come back to the mouth, alternating. Seated on a surface (core CrawlerSeat,
// uLimb[18].w = 1) the legs are planted instead: uLimb[10 + k] rotates the rest leg about its coxa onto the foothold
// (axis x angle), shortens it by the flex and raises the knee, A.w folds a leg that has nowhere clear to stand, and
// uLimb[18].y / .z cap the left / right chela's dip at the surface. A porcelain crab's feather fans ride the chela
// entries (COLOR_0.g = 1).
void crabLimb(int k, inout vec3 local, inout vec3 n) {
    vec4 P = uLimbPivot[k];
    vec4 A = uLimb[k];
    vec3 off = local - P.xyz;
    bool planted = uLimb[18].w > 0.5;
    if (k < 8 && planted) {
        vec4 IK = uLimb[10 + k];
        float ang = length(IK.yzw);
        if (ang > 1e-5) {
            vec3 ax = IK.yzw / ang;
            off = rotAxis(off, ax, ang);
            n = rotAxis(n, ax, ang);
        }
        float t = clamp(aColor.r, 0.0, 1.0);
        float flex = (IK.x - 0.3) / 0.5;
        off *= 1.0 - flex * t;
        float r = 1.0 - flex;
        off.y += 0.35 * sqrt(max(1.0 - r * r, 0.0)) * P.w * sin(PI * t);
        // no clear foothold: folded against the carapace rim
        off *= 1.0 - 0.6 * A.w * t;
        off.y += 0.1 * A.w * t * P.w;
    } else if (k < 8) {
        vec3 d = normalize(vec3(P.x, 0.0, P.z) + vec3(0.0001, 0.0, 0.0));
        float ph = A.x;
        float swing = 1.0 - step(0.5, ph);
        float q = ph * 2.0;
        float p = (ph - 0.5) * 2.0;
        float e = swing > 0.5 ? -cos(PI * q) : 1.0 - 2.0 * p;
        float t = clamp(aColor.r, 0.0, 1.0);
        float radial = dot(off, d);
        // extension / flexion along the leg (distal segments move most), drawn in by the tuck
        off += d * radial * (0.2 * A.y * e * t - 0.3 * A.w * t);
        vec3 ax = vec3(-d.z, 0.0, d.x);
        float lift = A.z * swing * sin(PI * q) - 0.12 * A.w;
        off = rotAxis(off, ax, lift);
        n = rotAxis(n, ax, lift);
        // small fore-aft swing of the whole leg
        float yaw = 0.08 * A.y * sin(2.0 * PI * ph);
        off = rotAxis(off, vec3(0.0, 1.0, 0.0), yaw);
        n = rotAxis(n, vec3(0.0, 1.0, 0.0), yaw);
    } else if (aColor.g > 0.5) {
        // porcelain crab feather fan (COLOR_0.g = 1) on this chela's entry: A.x sweep phase, A.w fanning 0..1. Drawn
        // open at the top of its sweep; it swings down and back to the mouth, folding, and stays folded when not fanning.
        vec3 root = vec3(P.x, P.y, 0.35 * P.z);
        vec3 o2 = local - root;
        float t = clamp(aColor.r, 0.0, 1.0);
        float sweep = max(0.5 - 0.5 * cos(2.0 * PI * A.x), 1.0 - A.w);
        float ang = -1.9 * sweep;
        o2 = rotAxis(o2, vec3(0.0, 0.0, 1.0), ang);
        n = rotAxis(n, vec3(0.0, 0.0, 1.0), ang);
        o2 *= 1.0 - 0.55 * sweep * t;
        local = root + o2;
        return;
    } else {
        float w = 0.5 - 0.5 * cos(2.0 * PI * A.x);   // 0 at the mouth .. 1 at the rock
        float down = A.y * 0.5 * w + 0.15 * (A.z - 0.5);
        if (planted) down = min(down, k == 8 ? uLimb[18].y : uLimb[18].z);
        off.x += 0.12 * (A.z - 0.5) - 0.07 * A.y * (1.0 - w);
        off = rotAxis(off, vec3(0.0, 0.0, 1.0), -down);
        n = rotAxis(n, vec3(0.0, 0.0, 1.0), -down);
    }
    local = P.xyz + off;
}

// Hermit crab (mode 5, core HermitLegs). Walking legs (k 0..3; uLimb = step phase, fore-aft stroke, foot lift,
// withdrawal): forward walking in diagonal pairs, the foot swung forward lifted for the first 40 % of the cycle and
// pushed back planted for the rest. Chelae (4 left, 5 right; pick phase, pick, walking support, withdrawal): dip to
// the substrate and come back to the mouth, alternating; uLimb[14].x raises both in a threat posture. 6 = shell: rolls
// and bobs about its ground point with the stride. 7 = shield and eyestalks (COLOR_0.g = 1: the stalks scan out of step). 8 antennae sweep, 9 antennules
// flick. uLimb.w pulls every part but the shell toward uLimbPivot[7], just inside the aperture (the larger left
// chela stays at the opening). Seated on a surface (core CrawlerSeat), uLimb[10..13] plant the walking legs on their
// footholds, cap the chelae's dip at the surface and 6.w / 8.z / 9.z bend the eyestalks and feelers away from rock.
void hermitLimb(int k, inout vec3 local, inout vec3 n) {
    vec4 P = uLimbPivot[k];
    vec4 A = uLimb[k];
    vec3 off = local - P.xyz;
    float t = clamp(aColor.r, 0.0, 1.0);
    float side = local.z >= 0.0 ? 1.0 : -1.0;
    bool planted = uLimb[14].w > 0.5;
    if (k < 4 && planted) {
        // planted on the surface by the sim (core CrawlerSeat): rotate the rest leg about the hip onto its foothold
        // (axis x angle), shorten it toward the hip by the flex and raise the knee by as much as the leg folds
        vec4 IK = uLimb[10 + k];
        float ang = length(IK.yzw);
        if (ang > 1e-5) {
            vec3 ax = IK.yzw / ang;
            off = rotAxis(off, ax, ang);
            n = rotAxis(n, ax, ang);
        }
        float flex = (IK.x - 0.3) / 0.5;
        off *= 1.0 - flex * t;
        float r = 1.0 - flex;
        off.y += 0.35 * sqrt(max(1.0 - r * r, 0.0)) * P.w * sin(PI * t);
    } else if (k < 4) {
        float ph = A.x;
        float sw = 1.0 - step(0.4, ph);
        float q = ph / 0.4;
        float e = sw > 0.5 ? -cos(PI * q) : 1.0 - 2.0 * (ph - 0.4) / 0.6;
        float yaw = A.y * e * (P.z >= 0.0 ? 1.0 : -1.0);
        off = rotAxis(off, vec3(0.0, 1.0, 0.0), yaw);
        n = rotAxis(n, vec3(0.0, 1.0, 0.0), yaw);
        off.y += A.z * sw * sin(PI * q) * smoothstep(0.25, 1.0, t) * 0.22 * P.w;
    } else if (k < 6) {
        float w = 0.5 - 0.5 * cos(2.0 * PI * A.x);   // 0 at the mouth .. 1 at the substrate
        float sd = k == 4 ? -1.0 : 1.0;
        float down = A.y * (0.55 * w - 0.15) + 0.1 * A.z;
        // never below the surface under the claw (the sim's limit, uLimb[14].y left / .z right)
        if (planted) down = min(down, k == 4 ? uLimb[14].y : uLimb[14].z);
        // threat posture (uLimb[14].x, core HermitLegs.threatS): both chelae swing up and out toward a rival
        float threat = clamp(uLimb[14].x, 0.0, 1.0);
        down = mix(down, -0.9, threat);
        off.z += side * 0.12 * P.w * threat * t;
        off = rotAxis(off, vec3(0.0, 0.0, 1.0), -down);
        n = rotAxis(n, vec3(0.0, 0.0, 1.0), -down);
        off.x -= 0.25 * P.w * A.y * (1.0 - w) * t;
        off.z -= sd * 0.1 * P.w * A.y * (1.0 - w) * t;
    } else if (k == 6) {
        float roll = A.y * sin(2.0 * PI * A.x);
        off = rotAxis(off, vec3(1.0, 0.0, 0.0), roll);
        n = rotAxis(n, vec3(1.0, 0.0, 0.0), roll);
        off = rotAxis(off, vec3(0.0, 0.0, 1.0), A.z);
        n = rotAxis(n, vec3(0.0, 0.0, 1.0), A.z);
    } else if (k == 7) {
        off.y += A.z * 0.02 * P.w;
        float em = step(0.5, aColor.g);
        float a = A.y * 0.3 * sin(2.0 * PI * A.x + side * 1.7) * em;
        off.z += t * a * P.w;
        off.x -= t * abs(a) * 0.3 * P.w;
        // eyestalks lean back and down, away from rock just ahead or overhead (uLimb[6].w, core CrawlerSeat)
        float eb = uLimb[6].w * em;
        off.x -= t * eb * 0.5 * P.w;
        off.y -= t * eb * 0.25 * P.w;
    } else if (k == 8) {
        float ph = 2.0 * PI * A.x + side * 1.3;
        float h2 = t * t;
        off.y += h2 * A.y * 0.18 * P.w * sin(ph - t * 3.0);
        off.z += h2 * A.y * 0.14 * P.w * cos(0.7 * ph - t * 2.5) * side;
        off.x += h2 * A.y * 0.08 * P.w * sin(0.5 * ph);
        // bent up and back from the rock they would reach into (A.z, core CrawlerSeat)
        if (A.z > 0.0) {
            off = rotAxis(off, vec3(0.0, 0.0, 1.0), A.z * 1.1);
            off = rotAxis(off, vec3(0.0, 1.0, 0.0), -side * A.z * 0.6);
        }
    } else {
        float f = pow(max(sin(2.0 * PI * A.x + side * 0.9), 0.0), 8.0);
        off.y -= t * t * A.y * f * 0.3 * P.w;
        if (A.z > 0.0) {
            off = rotAxis(off, vec3(0.0, 0.0, 1.0), A.z * 1.1);
            off = rotAxis(off, vec3(0.0, 1.0, 0.0), -side * A.z * 0.6);
        }
    }
    vec3 v = P.xyz + off;
    if (k != 6) {
        vec3 c = uLimbPivot[7].xyz;
        float s = k == 4 ? 0.6 : (k == 5 ? 0.45 : (k < 4 ? 0.25 : 0.2));
        v = mix(v, c + (v - c) * s, A.w);
    }
    local = v;
}

// Bobtail squid (mode 4, core SquidRig): uLimb[0] fins (x wave phase, y stroke, z mantle contraction, w wrap),
// uLimb[1] arms (x wave phase, y spread, z dorsal-pair raise, w tentacle strike). The ear fins (part 1, B = hinge)
// beat in a wave running along the fin and wrap against the mantle in a jet; the mantle behind the collar narrows as
// it contracts; the arms (part 3, COLOR_0.r = class / 8, g = index / 8, b = hinge) flare or bundle into a cone, the
// dorsal pair rises in alarm or to aim, and the two tentacles shoot forward and are drawn back.
void squidPose(float part, float hinge, inout vec3 local) {
    vec4 Fn = uLimb[0];
    vec4 Ar = uLimb[1];
    if (part < 0.5) {
        local.yz *= 1.0 - 0.14 * Fn.z * smoothstep(0.36, 0.5, aColor.a);
    } else if (part < 1.5) {
        float side = local.z >= 0.0 ? 1.0 : -1.0;
        local.y += 0.07 * Fn.y * hinge * sin(2.0 * PI * Fn.x + local.x * 18.0) * (1.0 - Fn.w);
        local.z -= side * hinge * 0.1 * Fn.w;
        local.y -= hinge * 0.03 * Fn.w;
    } else {
        float k = floor(aColor.g * 8.0 + 0.5);
        float h = hinge;
        float rl = length(local.yz);
        vec2 rd = rl > 1e-4 ? local.yz / rl : vec2(0.0);
        if (aColor.r < 0.19) {
            float dors = step(k, 1.5);
            local.yz += rd * h * (Ar.y - 0.3) * 0.14;
            local.y += dors * Ar.z * h * 0.14;
            local.x -= dors * Ar.z * h * 0.04;
            local.y += 0.012 * h * h * sin(2.0 * PI * Ar.x + k * 0.8 - h * 3.0);
            local.z += 0.01 * h * h * cos(2.0 * PI * Ar.x + k * 1.1 - h * 2.5);
        } else {
            local.x += Ar.w * 0.55 * h;
            local.yz *= 1.0 - 0.6 * Ar.w * h;
            local.y += 0.008 * h * sin(2.0 * PI * Ar.x + k * 2.0) * (1.0 - Ar.w);
        }
    }
}

// Flame scallop and maxima clam (motion mode 7, core ClamRig): uLimb[0] = (tentacle wave phase, gape 0..1, extension 0..1, swim
// trail 0..1), uLimb[1].y = writhe. COLOR_0: r valve side (1 upper), g class (0 shell, 0.5 mantle, 1 tentacle),
// b t along a tentacle, a phase seed. The valves turn about the hinge line (x -0.5, y 0, along Z); the mantle lip and
// tentacles ride their valve, the tentacles retract toward the beak, writhe, and stream back (+X) while it swims.
void clamPose(inout vec3 local, inout vec3 n) {
    float side = aColor.r > 0.5 ? 1.0 : -1.0;
    float cls = aColor.g;
    float t = aColor.b;
    float gape = clamp(uLimb[0].y, 0.0, 1.0);
    float ext = clamp(uLimb[0].z, 0.0, 1.0);
    float trail = clamp(uLimb[0].w, 0.0, 1.0);
    if (cls > 0.3 && cls < 0.45) {
        // maxima clam's draped mantle (class 0.4): drawn in toward the midline and down into the shell as it closes;
        // t = 0 at the midline .. 1 at the hanging edge
        float k = 1.0 - ext;
        local.y *= mix(1.0, 0.12, k);
        local.x -= k * (0.07 + 0.05 * t);
    } else if (cls > 0.25) {
        vec2 d = local.xz - vec2(-0.43, 0.0);
        vec2 dir = d / max(length(d), 1e-4);
        // the mantle lip swells out past the margin as it opens to feed
        float push = cls < 0.75 ? 0.025 * ext : 0.0;
        if (cls > 0.75) {
            // tentacles: draw back toward the beak, writhe (slow wave, own phase), stream back while swimming
            push = -0.3 * t * (1.0 - ext);
            float ph = 2.0 * PI * (uLimb[0].x + aColor.a) - 3.0 * t;
            float w = (0.35 + 0.65 * uLimb[1].y) * t * ext;
            local.xz += vec2(-dir.y, dir.x) * (0.05 * w * sin(ph));
            local.y += side * 0.03 * w * cos(ph * 0.7);
            local.x += trail * t * 0.18;
            local.z *= 1.0 - 0.45 * trail * t;
        }
        local.xz += dir * push;
    }
    // valve angle: up to ~32 deg between the valves [E: photographs]; the lips open 70 % as far as their shell
    float ang = side * gape * 0.28 * (cls > 0.25 ? 0.7 : 1.0);
    vec2 r = local.xy - vec2(-0.5, 0.0);
    float c = cos(ang), s = sin(ang);
    local.xy = vec2(-0.5, 0.0) + vec2(c * r.x - s * r.y, s * r.x + c * r.y);
    n.xy = vec2(c * n.x - s * n.y, s * n.x + c * n.y);
}

// Snails (motion mode 8, core SnailRig: trochus, fighting conch). The shell is rigid at the organism; COLOR_0.r = class
// (0 shell, 0.25 foot, 0.4 operculum, 0.5 head / snout, 0.75 tentacle, 1 eye), b = t along an appendage, a = phase seed.
// uLimb[0] = (pedal-wave phase, body out 0..1, rasp 0..1, righting reach 0..1), uLimb[1] = (tentacle wave phase,
// aperture xyz), uLimb[2] = (leap phase, vault 0..1, eyestalks out 0..1, -), uLimb[3] = (-, operculum tip xyz).
// Withdrawn parts gather at the aperture; the conch's shell vaults forward over its operculum tip, tail up.
void snailPose(inout vec3 local, inout vec3 n) {
    float cls = aColor.r;
    float t = aColor.b;
    float seed = aColor.a;
    vec4 A = uLimb[0];
    vec4 B = uLimb[1];
    vec4 Lp = uLimb[2];
    vec4 T = uLimb[3];
    vec3 ap = B.yzw;
    bool foot = cls > 0.2 && cls < 0.45;
    if (cls > 0.1) {
        if (cls > 0.6) {
            // tentacles and eyestalks wave slowly, each on its own phase, the tips most
            float ph = 2.0 * PI * (B.x + seed) - 2.5 * t;
            local.y += 0.025 * t * t * sin(ph);
            local.z += 0.02 * t * t * cos(ph * 0.8);
        } else if (cls > 0.45) {
            // snout: the radula's rasping strokes (~1.5 Hz), the tip working side to side and down
            float r = A.z * t;
            local.z += 0.02 * r * sin(2.0 * PI * (1.5 * uTime + seed));
            local.y -= 0.012 * r * (0.5 + 0.5 * sin(2.0 * PI * 3.0 * uTime));
        } else if (cls < 0.3) {
            // sole: a faint ripple of the pedal waves along the rim
            local.y += 0.006 * sin(2.0 * PI * (A.x * 3.0 + local.x * 3.0));
        }
        if (foot && T.y * T.y + T.z * T.z > 0.0) {
            // conch: the foot reaches forward and down to plant the operculum before each vault
            float ph = Lp.x;
            float fr = smoothstep(0.0, 0.4, ph) * (1.0 - smoothstep(0.55, 0.85, ph));
            local.x += 0.1 * t * fr;
            local.y -= 0.02 * t * fr;
        }
        // righting: foot and head swing over the side about the body axis to grip, stretching out
        float reach = clamp(A.w, 0.0, 1.0);
        if (reach > 0.001) {
            vec3 r = local - ap;
            float ang = reach * 1.9;
            float c = cos(ang), s = sin(ang);
            r = vec3(r.x * (1.0 + 0.25 * reach), c * r.y - s * r.z, s * r.y + c * r.z);
            local = ap + r * (1.0 + 0.3 * reach);
            n = vec3(n.x, c * n.y - s * n.z, s * n.y + c * n.z);
        }
        // in or out of the shell (the conch pulls its eyes in first)
        float e = cls > 0.6 ? min(A.y, Lp.z) : A.y;
        local = ap + (local - ap) * mix(0.1, 1.0, clamp(e, 0.0, 1.0));
    }
    // conch vault: all but the foot swings forward over the operculum tip, nose down and tail up
    float v = clamp(Lp.y, 0.0, 1.0);
    if (v > 0.001 && !foot) {
        vec3 piv = T.yzw;
        vec3 r = local - piv;
        float ang = -0.45 * v;
        float c = cos(ang), s = sin(ang);
        local = piv + vec3(c * r.x - s * r.y, s * r.x + c * r.y, r.z) + vec3(0.0, 0.06 * v, 0.0);
        n = vec3(c * n.x - s * n.y, s * n.x + c * n.y, n.z);
    }
}

// Tuxedo urchin (motion mode 9, core UrchinRig). COLOR_0.r = class (0 test, 0.25 spine, 0.5 tube foot, 0.75 debris,
// 1 teeth), b = t along a spine / foot (debris: piece index / 7), a = phase seed. uLimb[0] = (tube-foot wave phase,
// feet reaching 0..1, cover 0..1, bristle 0..1), uLimb[1] = (spine sway phase, test centre xyz), uLimb[2] = (-, poke
// direction xyz). Spines sway and point toward a poke; tube feet wave or draw in; debris pieces past the cover shrink
// away into the test.
void urchinPose(inout vec3 local, inout vec3 n) {
    float cls = aColor.r;
    float t = aColor.b;
    float seed = aColor.a;
    vec4 A = uLimb[0];
    vec4 B = uLimb[1];
    vec3 cen = B.yzw;
    if (cls > 0.15 && cls < 0.35) {
        vec3 rn = normalize(local - cen);
        float sw = 0.004 * sin(2.0 * PI * (B.x + seed));
        vec3 dir = uLimb[2].yzw;
        vec3 toward = vec3(0.0);
        if (A.w > 0.001 && dot(dir, dir) > 1e-4) {
            vec3 d = normalize(dir);
            toward = A.w * (d - rn * dot(d, rn)) * 0.03 * max(dot(d, rn) + 0.3, 0.0);
        }
        local += t * (vec3(sw, 0.0, -sw) + toward);
    } else if (cls > 0.4 && cls < 0.6) {
        float ph = 2.0 * PI * (A.x + seed) - 2.0 * t;
        local += t * vec3(0.012 * sin(ph), 0.01 * cos(ph), 0.012 * cos(ph * 0.7));
        local = cen + (local - cen) * mix(1.0 - 0.35 * t, 1.0, clamp(A.y, 0.0, 1.0));
    } else if (cls > 0.65 && cls < 0.85) {
        float shown = clamp(A.z * 7.0 - t * 7.0, 0.0, 1.0);
        local = cen + (local - cen) * shown;
    }
}

void main() {
    vec3 local = aPos;
    vec3 n = aNormal;
    float part = uShape.y;
    float hinge = aColor.b;
    float time = uTime;

    if (uRigid > 0.5) {
        vec4 w = uModel * vec4(local, 1.0);
        vWorld = w.xyz;
        vNormal = normalize(mat3(uModel) * n);
        vUv = aUv;
        vColor = vec4(aColor.r, 0.0, aColor.ba);
        gl_Position = uViewProj * w;
        return;
    }

    float mode = uMotion.w;
    if (uLimbOn > 0.5) {
        // limb-rigged crawler: rigid body at the organism, limbs posed from the sim (no spline skinning)
        if (mode > 4.5) {
            // hermit: every part (shell, shield, eyes, limbs) carries its limb index
            hermitLimb(int(floor(aColor.b * 9.0 + 0.5)), local, n);
        } else if (part > 2.5) {
            int k = int(floor(aColor.b * 9.0 + 0.5));
            if (mode < 1.5) starArm(k, local, n); else crabLimb(k, local, n);
        } else if (part > 1.5) {
            vec3 r = local - uEyePivot;
            float c = cos(uShape.z), s = sin(uShape.z);
            local = uEyePivot + vec3(c * r.x + s * r.z, r.y, -s * r.x + c * r.z);
            n = vec3(c * n.x + s * n.z, n.y, -s * n.x + c * n.z);
        }
        vec3 wl = uSpine[0].xyz + qrot(uFrame[0], local * uScale);
        vWorld = wl;
        vNormal = normalize(qrot(uFrame[0], n));
        vUv = aUv;
        vColor = vec4(aColor.r, 0.0, aColor.ba);
        gl_Position = uViewProj * vec4(wl, 1.0);
        return;
    }
    if (mode > 6.5 && mode < 7.5) {
        // flame scallop: a rigid shell at the organism, valves and fringe posed from the sim (no spine)
        clamPose(local, n);
        vec3 wl = uSpine[0].xyz + qrot(uFrame[0], local * uScale);
        vWorld = wl;
        vNormal = normalize(qrot(uFrame[0], n));
        vUv = aUv;
        vColor = vec4(aColor.r, 0.0, aColor.ba);
        gl_Position = uViewProj * vec4(wl, 1.0);
        return;
    }

    if (mode > 7.5 && mode < 9.5) {
        // snails and the urchin: a rigid body at the organism, soft parts posed from the sim (no spine)
        if (mode < 8.5) snailPose(local, n); else urchinPose(local, n);
        vec3 wl = uSpine[0].xyz + qrot(uFrame[0], local * uScale);
        vWorld = wl;
        vNormal = normalize(qrot(uFrame[0], n));
        vUv = aUv;
        vColor = vec4(aColor.r, 0.0, aColor.ba);
        gl_Position = uViewProj * vec4(wl, 1.0);
        return;
    }

    float u = aColor.a;
    float mouthDark = 0.0;
    if (mode > 0.5 && mode < 1.5 && part > 2.5) {
        // Brittle star arm rowing (Astley 2012): the arm pointing forward (+X) leads and barely moves; the arm pairs
        // either side make mirrored power strokes in the disc plane, the trailing pair drags. Rotate about the disc.
        float phi = atan(local.z, local.x);
        float r = length(local.xz);
        float side = abs(phi);
        float w = smoothstep(0.3, 1.2, side) * (1.0 - 0.6 * smoothstep(2.0, 2.8, side));
        float d = sign(phi) * w * uMotion.y * sin(2.0 * PI * uMotion.x - 2.5 * r) * smoothstep(0.02, 0.2, r);
        float c = cos(d), s = sin(d);
        local = vec3(c * local.x - s * local.z, local.y + 0.02 * w * uMotion.y * r * cos(2.0 * PI * uMotion.x), s * local.x + c * local.z);
        n = vec3(c * n.x - s * n.z, n.y, s * n.x + c * n.z);
    }
    // Offset of this vertex from its spine station along the body axis (fins/eyes carry the u of their base).
    local.x -= (0.5 - u);

    if (mode > 3.5 && (part < 1.5 || part > 2.5)) {
        squidPose(part, hinge, local);
    } else if (part < 0.5) {
        // body: wrasse thinness and gill flare (opercular mask in G)
        local.yz *= 1.0 - 0.25 * uShape.x;
        // gasping (heat stage 2, research 08: opercular rate 2.5-3x, mouth open): the gill covers stand flared and
        // pump wider, and the mouth works out of phase with them (buccal pump: mouth opens as the opercula close)
        float gph = time * uFin.w * 2.0 * PI;
        float flare = (0.03 * uFin.z + 0.04 * uSick.x) * aColor.g * (0.5 + 0.5 * sin(gph)) + 0.012 * uSick.x * aColor.g;
        local.z += sign(local.z) * flare;
        // opening jaw (models built with a mouth, uJaw.w = 1; uPick = the sim's mouth, 0 shut .. 1 wide): the lower jaw
        // (COLOR_0.b = 1) turns down about the hinge under the eye, the mouth lining's inner folds (0.5) half as far, and
        // the lining (COLOR_0.r) shades dark (vColor.g, read by fish.frag)
        if (uJaw.w > 0.5 && mode < 0.5) {
            float gape = max(clamp(uPick, 0.0, 1.0), uSick.x * (0.3 + 0.3 * sin(gph + PI)));
            float a = -gape * uJaw.z * aColor.b;
            vec2 r = aPos.xy - uJaw.xy;
            float c = cos(a), sn = sin(a);
            local.xy += vec2(c * r.x - sn * r.y, sn * r.x + c * r.y) - r;
            n.xy = vec2(c * n.x - sn * n.y, sn * n.x + c * n.y);
            mouthDark = aColor.r;
        }
    } else if (part < 1.5) {
        // fins: clamp folds toward the body (hinge-weighted, up to ~60 deg) and flutter
        // the first dorsal (uShape.w = 4) also folds down on its own: a firefish lays its tall flag back along the body
        float fold = uFold * step(3.5, uShape.w);
        float clampA = max(uFin.y, fold) * hinge;
        local.x -= clampA * (0.06 + 0.12 * fold);
        local.y *= 1.0 - mix(0.45, 0.8, fold) * clampA * step(abs(local.z), abs(local.y));
        local.z *= 1.0 - 0.45 * clampA * step(abs(local.y), abs(local.z));
        float flutter = 0.006 * sin(time * 9.0 + u * 6.0) * hinge * (1.0 - 0.7 * uFin.y);
        if (uShape.w > 0.5 && uShape.w < 1.5) {
            // pectorals: fan open and row
            float spread = mix(0.25, 1.0, uFin.x);
            local.z *= mix(0.35, 1.0, spread);
            if (uMotion.y > 0.001) {
                // labriform rowing from the sim's stroke phase (core MotionProfile): fore-aft sweep with a
                // feathering lift, amplitude set by speed (Drucker & Jensen 1996)
                float ph = 2.0 * PI * uMotion.x - u * 1.5;
                local.x += 0.09 * uMotion.y * hinge * sin(ph) * spread;
                local.y += 0.03 * uMotion.y * hinge * cos(ph) * spread;
            } else {
                local.x += 0.04 * hinge * sin(time * 7.0 + u * 3.0) * spread;
            }
            local.z += sign(local.z) * flutter;
        } else {
            local.z += flutter;
        }
    } else if (part < 2.5) {
        // eyes swivel about their pivot (model space)
        vec3 pv = uEyePivot;
        pv.x -= (0.5 - u);
        vec3 r = local - pv;
        float c = cos(uShape.z), s = sin(uShape.z);
        r = vec3(c * r.x + s * r.z, r.y, -s * r.x + c * r.z);
        local = pv + r;
        n = vec3(c * n.x + s * n.z, n.y, -s * n.x + c * n.z);
    } else if (mode > 1.5 && mode < 2.5 && aColor.r > 0.06) {
        vec4 S = uLimb[0];   // ShrimpLimbs: stride phase, stepping, rock / claw signal, grooming
        // Shrimp limbs (research 17). COLOR_0.r = limb class / 8, .g = pair / 8, .b = hinge (0 base .. 1 tip).
        float cls = floor(aColor.r * 8.0 + 0.5);
        float pr = floor(aColor.g * 8.0 + 0.5);
        float side = local.z >= 0.0 ? 1.0 : -1.0;
        float h = hinge;
        if (cls < 1.5) {
            // walking legs: alternating gait, neighbours and opposite legs half a stride apart; the foot swings
            // forward lifted and pushes back planted. Idle legs shift their footing now and then.
            // On a surface the sim plants each foot instead (uLimb[1..6] = swing lift, foot offset; uLimb[11].y =
            // planted): the leg bends from its rest tip onto the foothold and the knee arches as it lifts or folds.
            float pl = uLimb[11].y;
            float ph = 2.0 * PI * (S.x + 0.5 * mod(pr + (side > 0.0 ? 1.0 : 0.0), 2.0));
            local.x += h * ((1.0 - pl) * 0.05 * S.y * sin(ph) + 0.004 * sin(time * 0.7 + pr * 1.7 + side));
            local.y += h * (1.0 - pl) * 0.03 * S.y * max(cos(ph), 0.0);
            if (pr > 1.5) {
                vec4 W = uLimb[1 + int(pr - 2.0) * 2 + (side > 0.0 ? 1 : 0)];
                local += W.yzw * h;
                local.y += sin(PI * h) * (0.125 * W.x + 0.6 * max(W.z, 0.0));   // W.x = lift × 0.4
            }
        } else if (cls < 2.5) {
            // picking legs (P1-P2): alternate left/right strokes to the mouth while feeding or cleaning; the
            // front pair rocks rapidly back and forth as the skunk cleaner's signal; P1 combs the antenna in grooming
            // While cleaning or picking at rock the sim drives each claw tip (uLimb[7..10] = grip, tip offset,
            // uLimb[11].x = weight): out to the skin, a tug, and back to the mouth.
            float pk = uLimb[11].x;
            vec4 C = uLimb[7 + int(min(pr, 1.0)) * 2 + (side > 0.0 ? 1 : 0)];
            local += C.yzw * h;
            local.y += sin(PI * h) * 0.03 * pk;
            float k = 0.5 + 0.5 * sin(2.0 * PI * 2.2 * time + (side > 0.0 ? 0.0 : PI) + pr * 1.3);
            float pick = max(uPick, 0.0) * (1.0 - pk);
            local.x -= h * 0.06 * pick * k;
            local.y += h * 0.035 * pick * k;
            local.z -= side * h * 0.03 * pick * k;
            float rw = pr < 0.5 ? 1.0 : 0.35;
            float rock = sin(2.0 * PI * 3.0 * time);
            local.x += h * 0.05 * S.z * rw * rock;
            local.y += h * 0.025 * S.z * rw * abs(rock);
            local.x += h * 0.03 * S.w * (pr < 0.5 ? 1.0 : 0.0) * sin(2.0 * PI * 1.4 * time + side);
            local.y += h * 0.02 * S.w * (pr < 0.5 ? 1.0 : 0.0);
            local.x += h * 0.012 * S.y * sin(2.0 * PI * S.x + pr * PI);
        } else if (cls < 3.5) {
            // banded cheliped: held raised; it swings up and out toward an intruder (display), draws in to feed
            // The sim drives each claw tip while it probes crevices or strikes (uLimb[13] left, [14] right).
            local += uLimb[side > 0.0 ? 14 : 13].yzw * h;
            float dsp = S.z;
            local.z += side * h * 0.12 * dsp;
            local.y += h * (0.07 * dsp + 0.008 * sin(time * 0.9 + side));
            local.x -= h * 0.05 * max(uPick - 0.3, 0.0) * (0.5 + 0.5 * sin(2.0 * PI * 1.2 * time + side * 1.5));
            local.y -= h * 0.012 * S.y * sin(2.0 * PI * S.x);
        } else if (cls < 4.5) {
            // long antennae: slow whip-like sweeps that travel to the tip, faster when the appendage phase runs
            // (advertising, cleaning); lash with the skunk cleaner's leg rock; grooming draws one down to the mouth
            float h2 = h * h;
            float ph = uSwim.w + pr * 2.1 + side * 1.3;
            // lifted clear of rock just ahead, draped along a client's flank while cleaning (uLimb[11].z left, .w right)
            local.y += h2 * 0.25 * (side > 0.0 ? uLimb[11].w : uLimb[11].z);
            local.y += h2 * (0.06 * sin(ph - h * 3.0) + 0.1 * S.z * sin(2.0 * PI * 3.0 * time - h * 6.0 + side));
            local.z += h2 * 0.07 * cos(0.7 * ph - h * 2.5);
            float g = S.w * step(0.0, side);
            local.y -= g * h * 0.25;
            local.x -= g * h * 0.3 * (0.6 + 0.4 * sin(2.0 * PI * 0.8 * time));
            local.z -= g * side * h * 0.2;
        } else if (cls < 5.5) {
            // antennule flagella: sniffing flicks, a quick down-stroke about once a second (lobster analogue
            // 0.5-2 Hz, research 17) out of step between whips, over a small sway
            float f = pow(max(sin(2.0 * PI * 1.1 * time + pr * 2.0 + side * 0.9), 0.0), 12.0);
            local.y -= h * 0.05 * f;
            local.z += h * 0.02 * sin(uSwim.w * 0.8 + pr + side);
            local.y -= S.w * (1.0 - step(0.0, side)) * h * 0.08;
        } else if (cls < 6.5) {
            // pleopods: metachronal beat, the hindmost pair leads and the wave runs forward (uMotion: phase, amp)
            float ph = 2.0 * PI * (uMotion.x + 0.2 * pr);
            local.x += h * 0.035 * uMotion.y * sin(ph);
            local.y += h * 0.01 * uMotion.y * cos(ph);
        } else {
            // third maxillipeds: a slow idle flutter, quick picking strokes when feeding or grooming
            float a = 0.004 + 0.02 * max(uPick, S.w);
            local.y += h * a * sin(2.0 * PI * 4.0 * time + (side > 0.0 ? 0.0 : PI));
            local.x -= h * 0.6 * a * cos(2.0 * PI * 4.0 * time + (side > 0.0 ? 0.0 : PI));
        }
    } else if (mode > 9.5 && mode < 10.5) {
        // sea cucumber oral tentacles (R = t along, G = feeding order): folded in over the mouth when not feeding
        // (uPick = out); feeding, one at a time presses down on the sand, then bends back into the mouth to be wiped
        float t = aColor.r;
        float c = fract(uSwim.w - aColor.g);
        float dip = smoothstep(0.0, 0.05, c) * (1.0 - smoothstep(0.05, 0.1, c));
        float eat = smoothstep(0.05, 0.09, c) * (1.0 - smoothstep(0.11, 0.15, c));
        local.y -= uPick * t * 0.012 * dip;
        local = mix(local, CUKE_MOUTH, uPick * t * 0.85 * eat + (1.0 - uPick) * t * 0.8);
    } else if (mode < 0.5 || mode > 1.5) {
        // legs / antennae: sweep with the appendage phase along the hinge (B) coordinate
        float sweep = sin(uSwim.w * 2.0 * PI + hinge * 4.0 + u * 5.0);
        local.y += 0.04 * hinge * sweep;
        local.z += 0.03 * hinge * cos(uSwim.w * 2.0 * PI + hinge * 3.0);
    }

    // Fins carry the u of their base, so a fin that trails back (pectorals, pelvics, long dorsal/anal rays) was
    // skinned rigidly to its base station and cut into the body on sharp bends and big tail beats. Re-station
    // fin vertices at the spine coordinate they actually lie over, so they follow the same bend and wave as
    // the body beneath them (the caudal fin keeps its overhang past u = 1).
    float uw = u;
    if (part > 0.5 && part < 1.5) {
        uw = clamp(u - local.x, 0.0, 1.0);
        local.x += uw - u;
    }

    // Sea cucumber (mode 10, core SeaCucumberBrain): uFin.x = contraction (0 relaxed .. 1 balled up: shorter and fatter,
    // the body drawn toward the head along the spine), uMotion.xy = crawl wave (phase, amplitude): a swelling that runs
    // head to tail as the body creeps forward on its tube feet.
    if (mode > 9.5 && mode < 10.5) {
        float k = uFin.x;
        uw = u * (1.0 - 0.35 * k);
        if (part < 0.5) local.yz *= 1.0 + 0.3 * k + 0.07 * uMotion.y * sin(2.0 * PI * (3.0 * u - uMotion.x));
    }

    // Life-stage proportions (a juvenile engineer goby is stubbier than the eel-like adult): scale depth and width
    // about the body axis before the wave and skinning; normals take the inverse scale.
    if (abs(uStageShape.x) + abs(uStageShape.y) > 0.0001) {
        vec2 k = vec2(1.0) + uStageShape.xy;
        local.y *= k.x; local.z *= k.y;
        n = normalize(vec3(n.x, n.y / k.x, n.z / k.y));
    }

    // Lateral body wave: z += A(u) sin(2 pi (u waveLen - phase)), A(u) = amp (h + (1 - h) u^k), h and k per body type (uBodyEnv). The amplitude is
    // capped and faded while the body is strongly curved (head vs tail heading) so the wave cannot fold the tail
    // back into the body on a tight turn.
    vec3 fwdHead = qrot(uFrame[0], vec3(1.0, 0.0, 0.0));
    vec3 fwdTail = qrot(uFrame[15], vec3(1.0, 0.0, 0.0));
    float bendFade = mix(0.35, 1.0, smoothstep(-0.2, 0.85, dot(fwdHead, fwdTail)));
    float amp = min(uSwim.y, MAX_WAVE_AMP) * bendFade;
    float A = amp * (uBodyEnv.y + (1.0 - uBodyEnv.y) * pow(uw, uBodyEnv.x));
    float arg = 2.0 * PI * (uw * uSwim.z - uSwim.x);
    local.z += A * sin(arg);
    // slope dz/du tilts the normal (cheap analytic correction instead of a finite difference)
    float dzdu = amp * (1.0 - uBodyEnv.y) * uBodyEnv.x * pow(uw, uBodyEnv.x - 1.0) * sin(arg) + A * cos(arg) * 2.0 * PI * uSwim.z;
    // Escape C-start (Domenici & Blake 1997): head and tail curl to the same side, the middle the other way.
    // Shrimp (mode 2) flex the abdomen ventrally instead (caridoid tail-flip).
    float bend = uMotion.z;
    if (uSick.y > 0.001 && mode < 0.5) {
        // heat-death spasms (research 08 §2 stage 5): ~3 slots a second, most of them a sharp jerk of random side and
        // size that snaps out and relaxes, the rest still; seeded per fish by its length so neighbours are not in step.
        // Driven by the render clock (wall time), so the jerks keep their pace at any sim speed, and each one starts
        // and ends at zero, so the body never jumps between slots.
        float ts = time * 3.1 + uScale * 7.31;
        float k = floor(ts);
        float on = step(0.3, hash12(vec2(k, 7.3)));
        float side = hash12(vec2(k, 1.9)) * 2.0 - 1.0;
        bend += clamp(uSick.y, 0.0, 1.0) * on * side * SPASM_BEND * sin(PI * min(fract(ts) * 2.5, 1.0));
        // one smooth C-curve at most: a spasm on top of a C-start bend must not shear the body into kinks
        bend = clamp(bend, -MAX_FISH_BEND, MAX_FISH_BEND);
    }
    if (mode > 1.5 && mode < 3.5) {
        float ab = max(uw - 0.4, 0.0);
        local.y -= 0.9 * max(bend, 0.0) * ab * ab;
        local.x -= 0.4 * max(bend, 0.0) * ab * ab;
    }
    if (mode > 1.5 && mode < 2.5) {
        // shrimp seated on its legs (core ShrimpLimbs, uLimb[12] = drop, pitch, roll): the body settles onto the
        // footholds under it
        vec4 St = uLimb[12];
        local.y -= St.y + St.z * (local.x + 0.5 - uw + 0.1) + St.w * local.z;
    } else if (mode < 0.5 && abs(bend) > 0.001) {
        float e = uw - 0.35;
        local.z += bend * 0.55 * (e * e - 0.04);
        dzdu += bend * 0.55 * 2.0 * e;
    }
    // u runs snout → tail (u = 0.5 - x), so dz/dx = -dz/du and the surface normal tilts by +dz/du
    n = normalize(vec3(n.x + dzdu * n.z, n.y, n.z));

    vec3 sp;
    vec4 q;
    sampleSpine(uw, sp, q);
    vec3 world = sp + qrot(q, local * uScale);
    vWorld = world;
    vNormal = normalize(qrot(q, n));
    vUv = aUv;
    vColor = aColor;
    vColor.g = mouthDark;
    // fish body: HLLE site mask for fish.frag (uSkin.z) in R: the head forward of the gill cover and a band along the
    // lateral line, which arcs over the upper flank (model space: unit length, y up, spine at y = 0)
    if (mode < 0.5 && part < 0.5) {
        // (wide enough to read at a normal viewing distance: the whole face above the mouth, a band ~8 % of the
        // length deep along the line)
        float head = (1.0 - smoothstep(0.24, 0.34, u)) * smoothstep(-0.08, 0.0, aPos.y);
        float line = (1.0 - smoothstep(0.025, 0.05, abs(aPos.y - 0.035 - 0.03 * sin(PI * u)))) * smoothstep(0.2, 0.32, u) * (1.0 - smoothstep(0.72, 0.86, u));
        vColor.r = max(head, line);
    }
    gl_Position = uViewProj * vec4(world, 1.0);
}

assets/shaders/fullscreen.vert:
#version 300 es
precision highp float;
// Fullscreen triangle from gl_VertexID (no vertex buffer).
out vec2 vUv;
void main() {
    vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
    vUv = p;
    gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}

assets/shaders/generic.frag:
#version 300 es
#include "common.glsl"
#include "lighting.glsl"
// Equipment, rim, back glass, emitters (ARCHITECTURE §8.4 item 7 back glass: dark, low-roughness
// reflection of the two key lights). Blended materials (hose, feed ring) output straight alpha.

in vec3 vWorld;
in vec3 vNormal;
in vec2 vUv;
in vec4 vColor;

uniform sampler2D uAlbedo;
uniform vec4 uBaseColor;
uniform float uHasTexture;
uniform float uRoughness;
uniform vec3 uEmissive;       // linear, already scaled (emitters follow the light colour)
uniform float uAlphaCutoff;   // > 0: alpha test
uniform float uLedDies;       // 1: an AI Prime lens (multi-colour LED cluster under the optic), set by TankRenderer

out vec4 fragColor;

void main() {
    vec4 tex = uHasTexture > 0.5 ? texture(uAlbedo, vUv) : vec4(1.0);
    vec3 albedo = toLinear(tex.rgb) * uBaseColor.rgb;
    float alpha = tex.a * uBaseColor.a;
    if (uAlphaCutoff > 0.0 && alpha < uAlphaCutoff) discard;
    vec3 N = normalize(vNormal);
    vec3 V = normalize(uCamPos.xyz - vWorld);
    if (dot(N, V) < 0.0) N = -N;
    // moulded-plastic / anodised micro texture on equipment below the water (High), fades with distance
    if (uQuality >= 1.5) {
        float fp = length(fwidth(vWorld));
        N = bumpH(N, vWorld, (vnoise(vWorld * 4.0) - 0.5) * 0.02 * (1.0 - smoothstep(0.08, 0.3, fp)));
    }
    vec3 col = shadeLit(albedo, N, V, vWorld, uRoughness, 1.0, 0.04, 0.0, 1.0);
    if (uLedDies > 0.5) {
        // AI Prime HD: the lens mesh is the LED cluster itself (16 dies, ~1.2 cm pitch). Each die keeps its channel
        // colour (white, blue, royal, red, green, violet, UV), scaled by the live intensity; at night only the moon
        // (blue) dies glow faintly. Saturated cores with a whiter hot centre, so they read as coloured LEDs.
        int li = distance(vWorld.xz, uLightPos[0].xz) < distance(vWorld.xz, uLightPos[1].xz) ? 0 : 1;
        vec2 d = vWorld.xz - uLightPos[li].xz;
        float h = hash12(floor(d / 1.18 + 0.5) + float(li) * 7.0);
        vec3 dc = h < 0.25 ? vec3(1.0, 0.92, 0.85) : h < 0.5 ? vec3(0.1, 0.45, 1.0) : h < 0.75 ? vec3(0.12, 0.16, 1.0)
            : h < 0.81 ? vec3(1.0, 0.12, 0.06) : h < 0.87 ? vec3(0.15, 1.0, 0.25) : h < 0.94 ? vec3(0.5, 0.12, 1.0) : vec3(0.3, 0.06, 0.75);
        float on = uNight > 0.5 ? (h >= 0.25 && h < 0.75 ? 0.06 : 0.0) : 1.0;
        float level = uLightColor[li].w;
        col = albedo * 0.02 + dc * on * (0.12 + 1.6 * level);
    } else {
        col += uEmissive;
    }
    // things above the water (fixtures, rim) are not in the water column; applyWater handles that
    col = applyWater(col, vWorld);
    fragColor = vec4(tonemap(col), alpha);
}

assets/shaders/glass.frag:
#version 300 es
#include "common.glsl"
#include "lighting.glsl"
// Front/side glass (ARCHITECTURE §8.4 item 7): Schlick Fresnel (F0 0.04 glass, SIMULATION §9.7) reflecting
// the room environment (equirect room_env.png) and the fixture glow; premultiplied output (rendered last).
// Algae on the inner face (research 09 A6): green film haze and diatom dust, densest diatoms, cyano and dinos
// along the sand line; drawn behind the reflection and only below the water line. On the front pane the film is
// spatial: uGlassMask (GlassMask, 128 x 64 over the wetted pane, 1 = untouched, 0 = scraped bare) thins every group
// where the Flipper has been dragged and along the trails grazing snails and stars wear into the film (SIMULATION
// §11.1), and the cleared stripes and trails fill in again as the mask regrows.

in vec3 vWorld;
in vec3 vNormal;
in vec2 vUv;
in vec4 vColor;

uniform sampler2D uEnv;
uniform sampler2D uGlassMask;   // R: film density on the front pane (white 1x1 while the pane is untouched)
uniform vec4 uBaseColor;

out vec4 fragColor;

vec2 equirect(vec3 d) {
    return vec2(atan(d.z, d.x) / (2.0 * PI) + 0.5, acos(clamp(d.y, -1.0, 1.0)) / PI);
}

void main() {
    vec3 N = normalize(vNormal);
    vec3 V = normalize(uCamPos.xyz - vWorld);
    if (dot(N, V) < 0.0) N = -N;
    float ndv = max(dot(N, V), 0.0);
    float F = fresnelSchlick(ndv, 0.04);
    // float-glass waviness: a very slight low-frequency wobble in the reflected room and fixture highlights
    vec3 Nr = uQuality >= 0.5 ? normalize(N + (vec3(vnoise(vWorld * 0.07), 0.0, vnoise(vWorld * 0.07 + 9.0)) - 0.5) * 0.012) : N;
    vec3 R = reflect(-V, Nr);
    vec3 env = toLinear(texture(uEnv, equirect(R)).rgb) * 0.36;   // the room is exposed down (research 11 §10)
    // A pane seen from inside the tank (the side, back and bottom panes looked at through the water while the
    // camera is out front) mirrors the lit water by total internal reflection, not the room: without this the
    // grazing side panes picked up the pale room walls at Fresnel ~1 and read as beige/pink panels.
    vec3 Ng = normalize(vNormal);
    vec3 Nout = Ng * (dot(Ng, vWorld - uTank.xyz * 0.5) < 0.0 ? -1.0 : 1.0);
    bool fromInside = dot(Nout, uCamPos.xyz - vWorld) < 0.0;
    if (fromInside) env = uFog.rgb * 1.2 + uAmbientB.rgb * 0.5;
    // highlights of the two fixtures in the pane, divided by the blend alpha below so they reach the eye at their
    // Fresnel weight once (they were scaled by F twice: in the colour and again by the alpha ~ F)
    vec3 glint = vec3(0.0);
    for (int i = 0; i < 2; i++) {
        vec3 L = normalize(uLightPos[i].xyz - vWorld);
        glint += uLightColor[i].rgb * pow(max(dot(R, L), 0.0), 400.0) * 3.0;
    }
    vec3 tint = vec3(0.878, 0.973, 0.941) * 0.05 * (0.2 + lightIntensity());
    float a = clamp(F * (fromInside ? 0.35 : 0.6) + 0.02, 0.0, 1.0);
    // edge darkening where the glass is seen nearly edge-on (thickness)
    a += (1.0 - ndv) * (1.0 - ndv) * 0.08;
    vec3 col = tonemap(env * F + tint + glint * (F / max(a, 0.02)));
    if (dot(uAlgaeGlass, vec4(1.0)) > 0.001) {
        a = clamp(a, 0.0, 1.0);
        float y = vWorld.y;
        float wet = 1.0 - smoothstep(uWaterLevel - 1.0, uWaterLevel + 0.5, y);
        float nearSand = 1.0 - smoothstep(uParams2.w, uParams2.w + 18.0, y);
        float sandLine = 1.0 - smoothstep(uParams2.w, uParams2.w + 6.0, y);
        float n1 = fbm3(vWorld * 0.12);
        float n2 = fbm3(vWorld * 0.21 + vec3(13.0, 3.0, 29.0));
        // u along the tank, v from the sand line to the water line (core GlassMask layout)
        vec2 muv = vec2(vWorld.x / uTank.x, (y - uParams2.w) / max(uWaterLevel - uParams2.w, 1.0));
        float scraped = texture(uGlassMask, clamp(muv, 0.0, 1.0)).r;
        bool frontPane = abs(Ng.z) > 0.9 && abs(vWorld.z - uTank.z) < 1.0;
        float keep = frontPane ? clamp(scraped, 0.0, 1.0) : 1.0;
        float film = uAlgaeGlass.x * keep;
        float dia = uAlgaeGlass.y * mix(0.45, 1.0, nearSand) * keep;
        float fm = algaePatch(n1, film) * algaeDensity(film) * 0.7 + film * 0.3;
        float dm = algaePatch(n2, dia) * algaeDensity(dia) * 0.6 + dia * 0.2;
        float cm = algaePatch(1.0 - n1, uAlgaeGlass.z * sandLine * keep) * 0.8;
        float km = algaePatch(n2, uAlgaeGlass.w * sandLine * keep) * 0.6 * (1.0 - 0.8 * uDinoLift);   // lifts at night
        vec3 alb = vec3(0.10, 0.26, 0.035);                                // green film
        alb = mix(alb, vec3(0.26, 0.13, 0.03), dm / max(fm + dm, 1e-3));    // diatom brown
        float m = clamp(fm + dm, 0.0, 1.0);
        alb = mix(alb, vec3(0.16, 0.012, 0.016), cm);                     // cyano red
        alb = mix(alb, vec3(0.24, 0.16, 0.06), km);                       // dino khaki
        m = clamp(max(m, max(cm, km)), 0.0, 0.75) * wet;
        // lit from inside the tank: the film faces the water, translucent (wrapped Lambert)
        vec3 Nin = -Nout;
        vec3 ac = tonemap(applyWater(shadeLit(alb, Nin, V, vWorld, 0.8, 1.0, 0.04, 0.8, 0.2), vWorld));
        // straight-alpha "over": reflection layer (col, a) in front of the algae layer (ac, m)
        float outA = a + m * (1.0 - a);
        col = (col * a + ac * m * (1.0 - a)) / max(outA, 1e-4);
        a = outA;
    }
    fragColor = vec4(col, a);
}

assets/shaders/gsp_mat.frag:
#version 300 es
#include "common.glsl"
#include "lighting.glsl"
// Green star polyp stolon mat (GspMatDraw): drawn on a copy of the rock's own triangles, so it lies exactly on the
// rock you see. vUv.x = distance along the rock from where the colony was placed (cm, slower through shade), the
// mat covers everything inside gspEdge (common.glsl: lobed margin and thin runners ahead of it). Purple stolon
// tissue with closed-calyx pits; the newest growth at the margin is thin and paler (research 41_green_star_polyps.md).

in vec3 vWorld;
in vec3 vNormal;
in vec2 vUv;
in vec4 vColor;
in vec3 vObj;

uniform float uMatRadius;   // cm along the rock
uniform float uBleach;
uniform float uBrown;
uniform float uTissue;      // living tissue 0..1: a dying mat goes patchy

out vec4 fragColor;

const vec3 STOLON = vec3(0.105, 0.052, 0.150);       // #5A3F6B-ish purple, linear
const vec3 STOLON_DARK = vec3(0.050, 0.022, 0.060);
const vec3 MARGIN = vec3(0.30, 0.20, 0.34);          // fresh lavender runner tissue
const vec3 CALYX_RIM = vec3(0.10, 0.20, 0.05);       // green of a closed polyp's rim

void main() {
    vec3 op = vObj;
    float edge = gspEdge(op, uMatRadius);
    float e = edge - vUv.x;                    // cm inside the margin
    // a dying mat recedes in patches
    float patchy = vnoise(op * 0.35 + vec3(3.0, 11.0, 5.0));
    if (e < 0.0 || patchy > uTissue + 0.15) discard;
    vec3 N = normalize(vNormal);
    vec3 V = normalize(uCamPos.xyz - vWorld);
    float n1 = fbm3(op * 0.9);
    vec3 albedo = mix(STOLON_DARK, STOLON, 0.55 + 0.45 * n1);
    // closed calyces: small dark pits with a green rim, spaced like the polyps (~2-4 mm)
    float pit = vnoise(op * 3.3 + vec3(1.7, 4.1, 2.3));
    float hole = smoothstep(0.66, 0.78, pit);
    float rim = smoothstep(0.56, 0.66, pit) * (1.0 - hole);
    albedo = mix(albedo, CALYX_RIM, rim * 0.45);
    albedo *= 1.0 - 0.6 * hole;
    // the margin: thin, paler new stolon a few mm wide
    float margin = 1.0 - smoothstep(0.0, 0.7, e);
    albedo = mix(albedo, MARGIN * (0.8 + 0.4 * n1), margin * 0.7);
    albedo = mix(albedo, vec3(0.75, 0.7, 0.72), clamp(uBleach, 0.0, 1.0) * 0.8);
    albedo = mix(albedo, vec3(0.195, 0.102, 0.042), clamp(uBrown, 0.0, 1.0) * 0.4);
    // cavity from the rock's own COLOR_0.r (rock_surface.py / DryRockMesh) keeps the mat's crevices dark
    float ao = 1.0 - 0.5 * clamp(vColor.r, 0.0, 1.0);
    N = normalize(N + 0.25 * (vec3(vnoise(op * 2.1), vnoise(op * 2.1 + 9.0), vnoise(op * 2.1 + 17.0)) - 0.5));
    // a soft, slightly glossy tissue skin
    vec3 col = shadeLit(albedo, N, V, vWorld, 0.55, ao, 0.03, 0.4, 0.6);
    col = applyWater(col, vWorld);
    fragColor = vec4(tonemap(col), 1.0);
}

assets/shaders/lighting.glsl:
// Fragment-side lighting shared by the opaque shaders (ARCHITECTURE §8.4, SIMULATION §9.7 optics).
uniform sampler2D uCaustic;
// Shadow depth map (ShadowMap.kt, unit 14), compared in hardware (bilinear PCF per tap).
uniform highp sampler2DShadow uShadowMap;

// neutral-warm sky / bounce: a blue hemisphere filled every shadow with cyan (research 11 §0)
const vec3 HEMI_TOP = vec3(0.026, 0.033, 0.056);
const vec3 HEMI_BOTTOM = vec3(0.004, 0.005, 0.007);
const vec3 NIGHT_FLOOR = vec3(0.0025, 0.0045, 0.0095);

// Radiance from AI Prime i at p (point light, cosine cone pointing down), attenuated through the water
// column above p (Beer-Lambert). L returns the unit direction toward the fixture.
vec3 fixtureLight(int i, vec3 p, out vec3 L) {
    vec3 d = uLightPos[i].xyz - p;
    float dist = max(length(d), 1.0);
    L = d / dist;
    float c = uLightPos[i].w;
    float cone = smoothstep(c - 0.2, c + 0.25, L.y) * max(L.y, 0.0);
    float fall = 4500.0 / (dist * dist + 1500.0);
    float depth = max(uWaterLevel - p.y, 0.0) / max(L.y, 0.25);
    vec3 T = exp(-(uAbsorb.rgb + uAbsorb.w) * depth);
    return uLightColor[i].rgb * (cone * fall) * T;
}

float lightIntensity() { return max(uLightColor[0].w, uLightColor[1].w); }

vec3 hemiAmbient(vec3 n) {
    float h = n.y * 0.5 + 0.5;
    return uAmbientB.rgb + mix(HEMI_BOTTOM, HEMI_TOP, h) * (0.6 + 2.0 * lightIntensity()) + NIGHT_FLOOR;
}

// GGX specular term (D * G / (4 NdotV NdotL)), Schlick-GGX geometry; [H] is normalize(V + L).
float ggxSpecH(vec3 N, vec3 V, vec3 L, vec3 H, float rough) {
    float a = max(rough * rough, 0.02);
    float a2 = a * a;
    float ndh = max(dot(N, H), 0.0);
    float dd = ndh * ndh * (a2 - 1.0) + 1.0;
    float D = a2 / (PI * dd * dd);
    float ndl = max(dot(N, L), 1e-3);
    float ndv = max(dot(N, V), 1e-3);
    float k = a * 0.5;
    float G = (ndl / (ndl * (1.0 - k) + k)) * (ndv / (ndv * (1.0 - k) + k));
    return D * G / (4.0 * ndv * ndl);
}
float ggxSpec(vec3 N, vec3 V, vec3 L, float rough) { return ggxSpecH(N, V, L, normalize(V + L), rough); }

// Schlick's (1 - cos)^5, as two squarings and a multiply.
float fresnelSchlick(float cosT, float f0) {
    float m = 1.0 - clamp(cosT, 0.0, 1.0);
    float m2 = m * m;
    return f0 + (1.0 - f0) * (m2 * m2 * m);
}

// Hue of the live fixture light, normalised so its brightest channel is 1 (follows the AI Prime schedule).
vec3 lightTint() {
    vec3 s = uLightColor[0].rgb + uLightColor[1].rgb;
    return s / max(max(s.r, max(s.g, s.b)), 1e-3);
}

// Caustics on everything under water (sand, rock, corals, fish, glass), tinted by the live light: the busy, rippled
// surface focuses the lamps into a bright, wriggling net of lines (Tee's tank video 2026-10-20). Two drifting reads of
// the shared tile, refracted by the surface slope and warped by the chop (cheap ALU, faster with more flow), are added
// and squared: bright lines with brighter knots where the two nets cross. Deeper surfaces see a softer net (mip bias).
// High takes the second read's three channels apart (dispersion: thin colour fringes on the bright lines; the tile's G
// and B are itself shifted either way, so no extra reads). Faces that look sideways still catch part of the pattern.
// [slope]: surfaceSlope(p.xz), shared with surfaceFlicker.
vec3 causticColor(vec3 p, vec3 n, vec2 slope) {
    if (uCausticStrength <= 0.0 || p.y > uWaterLevel) return vec3(0.0);
    float depth = max(uWaterLevel - p.y, 0.0);
    vec2 refr = slope * depth * 0.6;
    // walls see the pattern projected down their face: shift by height along the normal so it varies (stretched)
    // vertically instead of smearing into stripes
    vec2 uv = (p.xz + refr + n.xz * (p.y * 0.55)) * uCausticScale;
    float t = uTime;
    float busy = 0.6 + 0.6 * uFlowStrength;
    // Medium / Low (the cheaper presets slow devices step down to): no per-read mip bias, which some GPUs pay for with a
    // derivative per read, so the net is a little crisper; Low also skips the chop warp and the second drifting read
    if (uQuality >= 0.5) uv += vec2(sin(uv.y * 9.0 + t * 1.9), cos(uv.x * 8.0 - t * 1.6)) * (0.02 * busy);
    vec2 uvA = uv + t * vec2(0.031, 0.019) * busy;
    vec2 uvB = uv * 1.37 - t * vec2(0.024, -0.033) * busy;
    float a;
    vec3 b;
    if (uQuality >= 1.5) {
        float blur = 1.0 + depth * 0.02;
        a = texture(uCaustic, uvA, blur).r;
        if (uCausticDispersion > 0.5) {
            // the tile's G and B are itself, read at uv + and - the fringe shift (tools/blender/textures.py caustic_rgb),
            // so one read gives all three colours of a fringe
            vec3 net = texture(uCaustic, uvB, blur).rgb;
            b = net.grb;
        } else {
            b = vec3(texture(uCaustic, uvB, blur).r);
        }
    } else {
        a = texture(uCaustic, uvA).r;
        b = vec3(uQuality >= 0.5 ? texture(uCaustic, uvB).r : a);
    }
    vec3 sum = a + b;
    // where the passing waves are steepest the surface focuses harder: the net brightens in travelling bands
    float chop = clamp(length(slope) * 5.0, 0.0, 1.5);
    // linear + squared: the squared term makes crisp bright lines up close, the linear term keeps the shimmer's energy
    // when the lines shrink below a pixel (far sand, small phone screens), where squaring a mip-blurred read fades out
    vec3 c = min(sum * 8.0 + sum * sum * 10.0, vec3(4.0)) * (0.7 + 0.5 * chop);
    // Medium/High: side faces keep ~20% of the shimmer (light arrives steeply but not only from straight above; the
    // photos show next to none on rock faces)
    float side = uQuality >= 0.5 ? 0.22 : 0.2;
    float facing = clamp(n.y * (1.0 - side) + side, 0.0, 1.0);
    return c * lightTint() * (facing * lightIntensity() * exp(-0.010 * depth));
}

// Soft contact shadows under the nearest fish (uCasters): a blob below each body that widens and fades with height.
// Static receivers only (fish.frag defines NO_CONTACT_SHADOW so a fish does not shadow itself).
float contactShadow(vec3 p) {
    float occ = 0.0;
    int n = int(uCasterCount + 0.5);
    for (int i = 0; i < 12; i++) {
        if (i >= n) break;
        vec4 c = uCasters[i];
        float h = c.y - p.y;
        if (h < -0.5 || h > 32.0) continue;
        vec2 d = p.xz - c.xz;
        float r = max(c.w * 0.3, 0.8) + max(h, 0.0) * 0.12;
        float d2 = dot(d, d) / (r * r);
        if (d2 > 4.0) continue;
        float blob = exp(-d2 * 1.4);
        float fade = smoothstep(-0.5, 0.6, h) * (1.0 - smoothstep(3.0, 32.0, h));
        occ = max(occ, blob * fade);
    }
    return 1.0 - 0.6 * occ;
}

// Shadow from the fixtures (uShadowMap): 1 lit .. 0 fully shadowed (scaled by uShadow.z). Normal offset and a world
// bias toward the light avoid acne; High takes 8 rotated taps (~1.6 cm penumbra), Medium 4, Low has no map.
float shadowAt(vec3 p, vec3 n) {
    if (uShadow.x < 0.5) return 1.0;
    vec3 q = p + n * (0.25 + 0.5 * (1.0 - abs(n.y))) + vec3(0.0, uShadow.w, 0.0);
    vec3 c = (uShadowMat * vec4(q, 1.0)).xyz * 0.5 + 0.5;
    if (c.x <= 0.0 || c.x >= 1.0 || c.y <= 0.0 || c.y >= 1.0 || c.z >= 1.0) return 1.0;
    // the kernel is in cm (uShadow.y = cm per texel along u), rotated per pixel (interleaved gradient noise)
    float ang = 6.2831 * fract(52.9829 * fract(dot(gl_FragCoord.xy, vec2(0.06711, 0.00584))));
    vec2 cs = vec2(cos(ang), sin(ang));
    mat2 rot = mat2(cs.x, cs.y, -cs.y, cs.x);
    vec2 texel = vec2(1.0) / vec2(textureSize(uShadowMap, 0));
    float lit;
    if (uQuality >= 1.5) {
        vec2 k = texel * (0.8 / max(uShadow.y, 1e-3));
        lit = 0.0;
        lit += textureLod(uShadowMap, vec3(c.xy + rot * vec2(-0.94, -0.40) * k, c.z), 0.0);
        lit += textureLod(uShadowMap, vec3(c.xy + rot * vec2(0.95, -0.77) * k, c.z), 0.0);
        lit += textureLod(uShadowMap, vec3(c.xy + rot * vec2(-0.09, -0.93) * k, c.z), 0.0);
        lit += textureLod(uShadowMap, vec3(c.xy + rot * vec2(0.34, 0.29) * k, c.z), 0.0);
        lit += textureLod(uShadowMap, vec3(c.xy + rot * vec2(-0.82, 0.54) * k, c.z), 0.0);
        lit += textureLod(uShadowMap, vec3(c.xy + rot * vec2(0.54, 0.89) * k, c.z), 0.0);
        lit += textureLod(uShadowMap, vec3(c.xy + rot * vec2(0.97, 0.23) * k, c.z), 0.0);
        lit += textureLod(uShadowMap, vec3(c.xy + rot * vec2(-0.32, 0.12) * k, c.z), 0.0);
        lit *= 0.125;
    } else {
        vec2 k = texel * (0.6 / max(uShadow.y, 1e-3));
        lit = 0.25 * (textureLod(uShadowMap, vec3(c.xy + rot * vec2(-0.7, -0.7) * k, c.z), 0.0)
                    + textureLod(uShadowMap, vec3(c.xy + rot * vec2(0.7, -0.7) * k, c.z), 0.0)
                    + textureLod(uShadowMap, vec3(c.xy + rot * vec2(-0.7, 0.7) * k, c.z), 0.0)
                    + textureLod(uShadowMap, vec3(c.xy + rot * vec2(0.7, 0.7) * k, c.z), 0.0));
    }
    return mix(1.0, lit, uShadow.z);
}

// Slow light flicker of the direct beam as the rippled surface focuses and spreads it (a heavily blurred, scrolling
// read of the caustic tile, ~1 around its mean). Medium and High.
float surfaceFlicker(vec3 p, vec2 slope) {
    if (uQuality < 0.5 || p.y > uWaterLevel) return 1.0;
    vec2 uv = (p.xz + slope * (uWaterLevel - p.y) * 0.6) * uCausticScale * 0.45;
    float f = texture(uCaustic, uv + uTime * vec2(0.017, -0.012), 3.5).r;
    return 0.85 + 0.15 * clamp(f * 28.0, 0.0, 2.2);
}

// Bump from a scalar height h (cm) via screen-space derivatives (surface gradient, no tangents). Callers keep it in
// uniform control flow (derivatives).
vec3 bumpH(vec3 N, vec3 p, float h) {
    vec3 sx = dFdx(p), sy = dFdy(p);
    vec3 r1 = cross(sy, N), r2 = cross(N, sx);
    float det = dot(sx, r1);
    vec3 g = sign(det) * (dFdx(h) * r1 + dFdy(h) * r2);
    vec3 r = abs(det) * N - g;
    float l = dot(r, r);
    return l > 1e-20 ? r * inversesqrt(l) : N;   // degenerate (edge-on / sub-pixel) triangles: no NaN speckles
}

// What the two fixtures deliver at the pixel (radiance through the water, unit direction to the lamp), worked out once by
// shadeLit: the extra lobes added after it (wet coat, back-light, glints, iridescence) read them back instead of
// repeating the distance, cone and Beer-Lambert maths. They belong to the last shadeLit call, at its point.
vec3 gRad0, gRad1, gL0, gL1;
vec3 fixtureAt(int i, out vec3 L) {
    if (i == 0) { L = gL0; return gRad0; }
    L = gL1;
    return gRad1;
}

// Wet clear-coat lobe (mucus / water film): a tight GGX highlight from both fixtures on top of the base response.
// Follows a shadeLit call at the same point.
vec3 wetCoat(vec3 N, vec3 V, vec3 p, float rough, float strength) {
    vec3 s = vec3(0.0);
    for (int i = 0; i < 2; i++) {
        vec3 L;
        vec3 rad = fixtureAt(i, L);
        vec3 H = normalize(V + L);
        float ndl = max(dot(N, L), 0.0);
        s += rad * ggxSpecH(N, V, L, H, rough) * fresnelSchlick(max(dot(H, V), 0.0), 0.02) * ndl;
    }
    return s * strength;
}

// Shadow-map visibility from the last shadeLit call: extra light lobes added after it (glints, sheen, back-light)
// reuse it instead of sampling the PCF kernel again.
float gShadow = 1.0;

// One fixture's share of the direct light: Lambert (optionally wrapped) + GGX, sharing one half vector.
vec3 fixtureDirect(vec3 rad, vec3 L, vec3 albedo, vec3 N, vec3 V, float rough, float f0, float wrap, float specScale) {
    float ndl = dot(N, L);
    float diff = max((ndl + wrap) / (1.0 + wrap), 0.0);
    vec3 H = normalize(V + L);
    float spec = ggxSpecH(N, V, L, H, rough) * fresnelSchlick(max(dot(H, V), 0.0), f0) * max(ndl, 0.0);
    return rad * (albedo * diff + vec3(spec * specScale));
}

// Lambert (optionally wrapped) + GGX from both fixtures, hemispherical ambient and caustics; direct light and
// caustics are dimmed under nearby fish (contact shadows).
vec3 shadeLit(vec3 albedo, vec3 N, vec3 V, vec3 p, float rough, float ao, float f0, float wrap, float specScale) {
    vec3 col = hemiAmbient(N) * albedo * ao;
    gRad0 = fixtureLight(0, p, gL0);
    gRad1 = fixtureLight(1, p, gL1);
    vec3 direct = fixtureDirect(gRad0, gL0, albedo, N, V, rough, f0, wrap, specScale)
                + fixtureDirect(gRad1, gL1, albedo, N, V, rough, f0, wrap, specScale);
    // the surface heightfield's slope (4 taps) is read once for both the flicker and the caustics
    // plus the render-only swell (common.glsl), so the waves on the surface steer and brighten the net below
    // Low (Performance, and auto quality's last relief step): the net drifts without the surface's refraction wobble,
    // which saves four heightfield reads and three waves per lit pixel
    vec2 slope = p.y > uWaterLevel || uQuality < 0.5 ? vec2(0.0) : surfaceSlope(p.xz) + swell(p.xz, 3).yz;
    // the rippled surface gathers the beam into the caustic net, so the light between the lines is dimmer
    float gather = p.y < uWaterLevel ? 0.4 * uCausticStrength * max(N.y, 0.0) : 0.0;
    direct *= surfaceFlicker(p, slope) * (1.0 - gather);
    direct += albedo * causticColor(p, N, slope) * uCausticStrength;
#ifndef NO_CONTACT_SHADOW
    if (uCasterCount > 0.5) direct *= contactShadow(p);
#endif
    gShadow = shadowAt(p, N);
    direct *= gShadow;
    return col + direct;
}

// Beer-Lambert spectral attenuation along the in-water part of the view path + depth fog toward the
// (light-tinted) fog colour: fog = 1 - exp(-density x dist).
vec3 applyWater(vec3 col, vec3 p) {
    float d = waterPath(uCamPos.xyz, p);
    vec3 T = exp(-(uAbsorb.rgb + uAbsorb.w) * d);
    float f = 1.0 - exp(-uFog.w * d);
    return mix(col * T, uFog.rgb, f);
}

// Filmic curve (Hejl-style x/(x+0.155)*1.019); it already includes the display gamma, so no extra pow.
// Shared grade, so every shader lands in one look: partial white balance toward the fixture colour (the eye / a
// camera adapts to the AI Prime mix, so cream rock reads cream under a blue-heavy daylight, while dusk keeps more blue
// and moonlight stays blue), then a gentle S-curve; no global saturation boost (colour comes from the materials, research
// 11 §6). The balance is near full (0.9), as a phone camera's is in Tee's photos. Actinic-only light (blue fraction near 1,
// the Blue light look and blue-only ramps) is barely balanced: the real tank reads deep blue under it, with the
// fluorescent corals glowing out of it, and more saturated.
vec3 tonemap(vec3 x) {
    x = max(x, vec3(0.0));
    float actinic = (1.0 - uNight) * smoothstep(0.86, 0.98, uBlueFraction);
    float wb = 0.9 * (1.0 - uNight) * smoothstep(0.03, 0.25, lightIntensity()) * (1.0 - 0.8 * actinic);
    vec3 adapt = mix(vec3(1.0), lightTint(), wb);
    x /= max(adapt, vec3(0.2));
    vec3 c = x / (x + 0.155) * 1.019;
    c = clamp(c, 0.0, 1.0);
    c = mix(c, c * c * (3.0 - 2.0 * c), 0.18);
    float l = dot(c, vec3(0.2126, 0.7152, 0.0722));
    // actinic: the camera / eye sees royal blue as a deep, saturated indigo (Tee's video), not a pale sky blue
    return clamp(mix(vec3(l), c, 1.0 + 0.5 * actinic), 0.0, 1.0);
}

assets/shaders/particles.frag:
#version 300 es
#include "common.glsl"
#include "lighting.glsl"

// Point-sprite shapes (keep the ids in step with FoodVisuals.kt `Shape`): every food has its own silhouette, and the
// action bursts (dye plumes, bubbles, jets, sparkles) theirs. Shapes are 2D signed distances in the sprite's
// rotated coordinates, anti-aliased with fwidth; sprites under ~5 px fall back to the soft dot.

in vec4 vColor;
in vec3 vWorld;
flat in float vShapeId;
in vec3 vShape;
in float vPx;

out vec4 fragColor;

float sdSeg(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}
float sdEll(vec2 p, vec2 r) { return (length(p / r) - 1.0) * min(r.x, r.y); }
float fill(float d) { return clamp(0.5 - d / max(fwidth(d), 1e-3), 0.0, 1.0); }
float hash2(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }

void main() {
    vec2 c = gl_PointCoord * 2.0 - 1.0;
    float r2 = dot(c, c);
    int shape = int(vShapeId + 0.5);
    if (shape != 5 && shape != 14 && shape != 15 && vPx < 5.0) shape = 0;   // too small to read: a dot
    float seed = vShape.x;
    float ca = cos(vShape.y), sa = sin(vShape.y);
    vec2 p = vec2(ca * c.x + sa * c.y, -sa * c.x + ca * c.y);
    float param = vShape.z;

    vec3 base = vColor.rgb;
    float m = 0.0;          // coverage
    float aMul = 1.0;
    bool lit = true;

    if (shape == 0) {                       // soft dot (ambient specks, bubbles, sand clouds)
        if (r2 > 1.0) discard;
        m = 1.0 - smoothstep(0.35, 1.0, r2);
    } else if (shape == 1) {                // flake: thin, irregular, translucent, tumbling (param = visible width)
        vec2 q = vec2(p.x, p.y / max(param, 0.12));
        float th = atan(q.y, q.x);
        float r = 0.62 + 0.15 * sin(th * 3.0 + seed * 21.0) + 0.08 * sin(th * 5.0 + seed * 37.0);
        float d = length(q) - r;
        m = fill(d * max(param, 0.12));
        base *= mix(1.08, 0.72, smoothstep(-0.25, 0.0, d));
        aMul = 0.82;
    } else if (shape == 2) {                // pellet: a lit hard sphere
        float r = 0.85;
        float d = length(c) - r;
        m = fill(d);
        vec3 n = vec3(c / r, sqrt(max(0.0, 1.0 - r2 / (r * r))));
        float shade = 0.45 + 0.55 * max(dot(n, normalize(vec3(-0.4, 0.65, 0.65))), 0.0);
        base = base * shade + vec3(0.35) * pow(max(dot(n, normalize(vec3(-0.3, 0.5, 0.8))), 0.0), 20.0);
    } else if (shape == 3) {                // mysis: a pale, curled, see-through shrimp with dark eyes
        float rr = length(p);
        float th = atan(p.y, p.x);
        float s = clamp((th + 2.3) / 4.6, 0.0, 1.0);
        float d = abs(rr - 0.52) - mix(0.07, 0.19, s);
        if (abs(th) > 2.3) d = max(d, 0.3);
        vec2 eye = 0.6 * vec2(cos(2.2), sin(2.2));
        float eyes = 1.0 - smoothstep(0.06, 0.1, length(p - eye));
        m = max(fill(d), eyes);
        float gut = (rr - 0.52) / 0.05;
        base = mix(base * (1.0 - 0.3 * exp(-gut * gut) * s), vec3(0.03), eyes);
        aMul = 0.78;
    } else if (shape == 4) {                // copepod: teardrop body, tail and two antennae
        float d = sdEll(p - vec2(0.1, 0.0), vec2(0.45, 0.26));
        d = min(d, sdSeg(p, vec2(-0.3, 0.0), vec2(-0.85, 0.0)) - 0.05);
        d = min(d, sdSeg(p, vec2(0.45, 0.05), vec2(0.85, 0.55)) - 0.035);
        d = min(d, sdSeg(p, vec2(0.45, -0.05), vec2(0.85, -0.55)) - 0.035);
        m = fill(d);
        float eye = 1.0 - smoothstep(0.05, 0.09, length(p - vec2(0.42, 0.0)));
        base = mix(base, vec3(0.6, 0.05, 0.02), eye * param);
        aMul = 0.92;
    } else if (shape == 5) {                // haze puff: phyto, coral powder, dye, silt
        if (r2 > 1.0) discard;
        m = exp(-r2 * 3.2) * (1.0 - smoothstep(0.75, 1.0, r2));
        m *= 0.8 + 0.2 * sin(p.x * 5.0 + seed * 10.0) * sin(p.y * 4.0 + seed * 7.0);
    } else if (shape == 6) {                // adult brine shrimp: slender, orange, forked tail (param = wiggle)
        vec2 q = vec2(p.x, p.y + param * 0.35 * p.x * p.x);
        float t = clamp((q.x + 0.7) / 1.35, 0.0, 1.0);
        float d = sdSeg(q, vec2(-0.7, 0.0), vec2(0.62, 0.0)) - mix(0.05, 0.14, t);
        d = min(d, sdSeg(q, vec2(-0.68, 0.0), vec2(-0.92, 0.16)) - 0.03);
        d = min(d, sdSeg(q, vec2(-0.68, 0.0), vec2(-0.92, -0.16)) - 0.03);
        float eyes = 1.0 - smoothstep(0.045, 0.08, min(length(q - vec2(0.64, 0.11)), length(q - vec2(0.64, -0.11))));
        m = max(fill(d), eyes);
        base = mix(base * (0.85 + 0.15 * sin(q.x * 30.0)), vec3(0.02), eyes);
        aMul = 0.88;
    } else if (shape == 7) {                // krill piece: curved, banded, black eyes
        vec2 q = vec2(p.x, p.y + 0.28 * p.x * p.x);
        float t = clamp((q.x + 0.75) / 1.35, 0.0, 1.0);
        float d = sdSeg(q, vec2(-0.75, 0.0), vec2(0.58, 0.0)) - mix(0.09, 0.22, t);
        d = min(d, sdSeg(q, vec2(-0.72, 0.0), vec2(-0.95, 0.17)) - 0.06);
        d = min(d, sdSeg(q, vec2(-0.72, 0.0), vec2(-0.95, -0.17)) - 0.06);
        float eyes = 1.0 - smoothstep(0.07, 0.11, length(q - vec2(0.58, 0.12)));
        m = max(fill(d), eyes);
        base = mix(base * (0.82 + 0.18 * sin(q.x * 24.0)), vec3(0.01), eyes);
    } else if (shape == 8) {                // prawn chunk: blocky pink lump with pale flesh bands
        float th = atan(p.y, p.x);
        float r = 0.68 + 0.12 * sin(th * 3.0 + seed * 17.0) + 0.07 * sin(th * 5.0 + seed * 29.0);
        float l = mix(length(p), max(abs(p.x), abs(p.y)) * 1.12, 0.55);
        m = fill(l - r);
        float band = smoothstep(0.4, 0.9, sin(p.x * 8.0 + p.y * 3.0 + seed * 10.0));
        base = mix(base, vec3(0.92, 0.84, 0.78), 0.45 * band) * (0.8 + 0.2 * (1.0 - l));
    } else if (shape == 9) {                // algae wafer: dark green disc, rim, speckles (param = visible width)
        vec2 q = vec2(p.x, p.y / max(param, 0.15));
        float d = length(q) - 0.86;
        m = fill(d * max(param, 0.15));
        float speck = step(0.82, hash2(floor(q * 7.0) + seed * 13.0));
        base = mix(base * mix(1.0, 0.6, smoothstep(-0.18, 0.0, d)), base * 2.2 + vec3(0.03, 0.03, 0.0), speck * 0.6);
    } else if (shape == 10) {               // cyclops: tiny red teardrop with a bright eye spot
        float d = sdEll(p - vec2(0.1, 0.0), vec2(0.5, 0.36));
        d = min(d, sdSeg(p, vec2(-0.3, 0.0), vec2(-0.8, 0.0)) - 0.06);
        m = fill(d);
        float eye = 1.0 - smoothstep(0.07, 0.12, length(p - vec2(0.38, 0.0)));
        base = mix(base, vec3(1.0, 0.05, 0.02), eye);
    } else if (shape == 11) {               // frozen cube: frosted rounded block, edges going ragged as it thaws
        float th = atan(p.y, p.x);
        vec2 q = abs(p) - vec2(0.6);
        float d = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - 0.12;
        d += param * 0.16 * sin(th * 7.0 + seed * 30.0);
        m = fill(d);
        float frost = smoothstep(-0.35, 0.0, d) * (1.0 - 0.7 * param);
        base = mix(base, vec3(0.88, 0.92, 0.98), 0.6 * frost) + vec3(0.1) * step(p.x + p.y, -0.5);
        aMul = 0.95 - 0.35 * param;
    } else if (shape == 12) {               // nori: a translucent dark-green sheet tile with torn edges and fibres
        vec2 q = abs(p) - vec2(0.8);
        float d = max(q.x, q.y) + 0.1 * sin(p.x * 9.0 + seed * 40.0) * sin(p.y * 7.0 + seed * 17.0);
        m = fill(d);
        base *= 0.82 + 0.18 * sin((p.x * 0.6 + p.y) * 25.0 + seed * 50.0);
        aMul = 0.8;
    } else if (shape == 13) {               // bubble: thin bright ring with a highlight
        float d = abs(length(c) - 0.72) - 0.13;
        float hi = 1.0 - smoothstep(0.08, 0.2, length(c - vec2(-0.3, -0.3)));
        m = max(fill(d), hi);
        base = mix(base, vec3(1.0), hi);
        aMul = 0.7;
    } else if (shape == 14) {               // glow: emissive soft core (sparkles, UV, sparks)
        if (r2 > 1.0) discard;
        m = exp(-r2 * 5.0);
        lit = false;
    } else if (shape == 15) {               // streak: a soft line along the sprite's x (jets, swirls, falling grains)
        float d = sdSeg(p, vec2(-0.9, 0.0), vec2(0.9, 0.0));
        m = (1.0 - smoothstep(0.0, 0.16, d)) * (0.35 + 0.65 * clamp(p.x * 0.5 + 0.5, 0.0, 1.0));
    } else if (shape == 16) {               // fish feces: a short bent string with constrictions (param: bend; > 1 lying, crumbling)
        float lying = step(1.0, param);
        float decay = clamp(param - 1.0, 0.0, 1.0);
        float bend = mix(param, 0.15, lying);
        vec2 q = vec2(p.x, p.y + bend * 0.45 * (p.x * p.x - 0.3));
        float t = clamp(q.x * 0.5 + 0.5, 0.0, 1.0);
        float w = mix(0.17, 0.22, lying) * (0.8 + 0.2 * sin(t * 18.0 + seed * 9.0));   // segmented, pinched string
        float d = sdSeg(q, vec2(-0.82, 0.0), vec2(0.82, 0.0)) - w;
        d += decay * 0.12 * (hash2(floor(q * 6.0) + seed * 7.0) - 0.5);                 // ragged as it falls apart
        m = fill(d);
        base *= 0.85 + 0.25 * smoothstep(0.0, -w, d);
        aMul = 0.95 - 0.35 * decay;
    } else {
        if (r2 > 1.0) discard;
        m = 1.0 - smoothstep(0.35, 1.0, r2);
    }
    if (m < 0.01) discard;

    vec3 col;
    if (lit) {
        vec3 L;
        vec3 rad = fixtureLight(0, vWorld, L) + fixtureLight(1, vWorld, L);
        col = base * (rad * 0.9 + hemiAmbient(vec3(0.0, 1.0, 0.0)) * 2.0);
    } else {
        col = base * 2.5;
    }
    col = applyWater(col, vWorld);
    float a = vColor.a * m * aMul * mix(1.0, 0.5, uNight);
    fragColor = vec4(tonemap(col), a);
}

assets/shaders/particles.vert:
#version 300 es
#include "common.glsl"
// GL_POINTS particles (ARCHITECTURE §8.4 item 9): suspended particulate, detritus, bubbles, food and action bursts.
// Positions are advected on the CPU; size is a world size (cm) projected to pixels, clamped to a px range.
// aShape picks the sprite drawn in the fragment shader (0 = the plain soft dot; see particles.frag and
// FoodVisuals.kt). A VAO that does not feed location 2 gets the GL default (0, 0, 0, 1): the plain dot.

layout(location = 0) in vec4 aPosSize;  // xyz cm, w size (cm)
layout(location = 1) in vec4 aColor;    // linear rgb, alpha
layout(location = 2) in vec4 aShape;    // x shape id, y seed 0..1, z screen angle (rad), w shape parameter

uniform float uViewportH;
uniform vec2 uSizeClamp;                // min/max point size (px)

out vec4 vColor;
out vec3 vWorld;
flat out float vShapeId;
out vec3 vShape;                        // seed, angle, parameter
out float vPx;

void main() {
    vec4 clip = uViewProj * vec4(aPosSize.xyz, 1.0);
    gl_Position = clip;
    float px = aPosSize.w * uProj[1][1] * uViewportH * 0.5 / max(clip.w, 0.1);
    gl_PointSize = clamp(px, uSizeClamp.x, uSizeClamp.y);
    vColor = aColor;
    vWorld = aPosSize.xyz;
    vShapeId = aShape.x;
    vShape = aShape.yzw;
    vPx = gl_PointSize;
}

assets/shaders/polyp.frag:
#version 300 es
#include "common.glsl"
#include "lighting.glsl"
// Polyp shading: wrap diffuse, per-instance tint jitter, fluorescent emissive scaled by the blue fraction
// (GSP pop under actinics), optional alpha test (clove / duster feathers).

in vec3 vWorld;
in vec3 vNormal;
in vec2 vUv;
in vec4 vColor;
in float vVariant;
in float vOpen;
in float vTip;
in float vGlow;
in float vRing;

uniform sampler2D uAlbedo;
uniform vec4 uBaseColor;
uniform float uHasTexture;
uniform float uRoughness;
uniform vec3 uEmissive;
uniform float uAlphaCutoff;
uniform float uBleach;
uniform vec3 uBleachTint;  // what bleached tissue fades to (per species)
uniform float uDead;       // 1 - living tissue: receding colony
uniform float uBrown;

out vec4 fragColor;

void main() {
    vec4 tex = uHasTexture > 0.5 ? texture(uAlbedo, vUv) : vec4(1.0);
    float alpha = tex.a * uBaseColor.a;
    if (uAlphaCutoff > 0.0) {
        // (duster feathers) mipmapping averages the fine barbs' alpha down, so as the crown shrinks on screen the
        // alpha test ate them into a shimmering hatch / moire: scale alpha back up by the mip level being sampled
        if (uHasTexture > 0.5) {
            vec2 tc = vUv * vec2(textureSize(uAlbedo, 0));
            vec2 d = max(abs(dFdx(tc)), abs(dFdy(tc)));
            alpha *= 1.0 + 0.25 * max(0.0, log2(max(d.x, d.y)));
        }
        if (alpha < uAlphaCutoff) discard;
    }
    vec3 albedo = toLinear(tex.rgb) * uBaseColor.rgb;
    albedo *= 0.85 + 0.3 * vVariant;
    // bubble-tip anemone: magenta tips on swollen bulbs (Tee's photos 2026-10-15)
    albedo = mix(albedo, vec3(0.95, 0.12, 0.5), vTip * 0.85);
    albedo = mix(albedo, vec3(0.86, 0.84, 0.78), vRing * 0.65);
    albedo = mix(albedo, uBleachTint, clamp(uBleach, 0.0, 1.0));
    // receding: patches of a dying colony melt away (world-space noise), the edge of the living tissue goes dull
    if (uDead > 0.001) {
        float n = clamp((vnoise(vWorld * 0.45) * 0.7 + vnoise(vWorld * 1.7 + 5.0) * 0.3 - 0.5) * 2.4 + 0.5, 0.0, 1.0);
        if (n < uDead * 1.02) discard;
        albedo = mix(vec3(0.55, 0.5, 0.42), albedo, smoothstep(uDead, uDead + 0.12, n));
    }
    albedo = mix(albedo, vec3(0.195, 0.102, 0.042), clamp(uBrown, 0.0, 1.0) * 0.4);
    vec3 N = normalize(vNormal);
    vec3 V = normalize(uCamPos.xyz - vWorld);
    if (dot(N, V) < 0.0) N = -N;
    vec3 col = shadeLit(albedo, N, V, vWorld, uRoughness, 1.0, 0.03, 0.8, 0.5);
    // glossy oral discs / tentacle tips (High: second, tighter lobe)
    if (uQuality >= 1.5) col += wetCoat(N, V, vWorld, 0.28, 0.3) * gShadow;
    col += uEmissive * (0.4 + 2.4 * uBlueFraction) * lightIntensity() * (0.3 + 0.7 * vOpen) * (1.0 - uBleach) * vGlow;
    col += vec3(0.9, 0.1, 0.55) * vTip * (0.15 + 0.9 * uBlueFraction) * lightIntensity() * (1.0 - uBleach);
    col = applyWater(col, vWorld);
    fragColor = vec4(tonemap(col), 1.0);
}

assets/shaders/polyp.vert:
#version 300 es
#include "common.glsl"
// Instanced polyps (ARCHITECTURE §8.4 item 3): GSP, zoas, clove, Kenya tufts, organ-pipe polyps, the
// feather-duster crown. Prototype in cm, base at the origin, axis +Y; COLOR_0.b = tentacle hinge 0..1.
// COLOR_0.r = 1 marks long curling tentacles (long-tentacle GSP, Tee's photos 2026-10-13): they writhe slowly,
// retract by shortening into the stalk (the whole polyp sinks into the mat) and sway more toward the tips.

layout(location = 0) in vec3 aPos;
layout(location = 1) in vec3 aNormal;
layout(location = 2) in vec2 aUv;
layout(location = 3) in vec4 aColor;
layout(location = 4) in vec4 iPosScale;   // world position (cm), scale
layout(location = 5) in vec4 iQuat;       // local +Y -> surface normal
layout(location = 6) in vec2 iPhaseVar;   // phase 0..1, colour variant 0..1

uniform mat4 uModel;        // identity for coral GLBs (instances are in world cm); places the duster crown
uniform float uExtension;   // colony extension 0..1
uniform vec3 uSwayDir;
uniform float uSwayAmp;     // cm at the tentacle tips
// tree mode (Kenya sprigs, extras.swayMode = 1): the instance rides its branch's treeSway (same uniforms as the body)
uniform float uSwayMode;
uniform vec3 uBase;
uniform float uHeight;
uniform float uPhase;
uniform float uBodySwayAmp;
uniform vec4 uWake;
// anemone mode (uSwayMode 2, the bubble-tip anemone, research 40): x bubble 0..1, y contraction 0..1 (deflated),
// z feeding curl 0..1, w curl direction (radians about the disc axis, model space)
uniform vec4 uAnem;
// fish contacts A and B (core AnemoneRig): world point (xyz) and radius (cm, w); drift = the fish's smoothed velocity (cm/s)
uniform vec4 uAnemPush;
uniform vec4 uAnemPushB;
uniform vec4 uAnemDrift;
uniform vec4 uAnemDriftB;
// x contact A strength (springy, about 0..1), y model scale (world cm per model cm), z contact B strength, w unused
uniform vec4 uAnemMisc;
// green star polyps on a mat built from the rock (GspMatDraw): the mat's reach along the rock (cm; 0 = a GLB colony).
// Each instance then packs its own distance along the rock into iPhaseVar.y (floor(y) / 16 cm, variant = fract(y)).
uniform float uMatRadius;
// touches closing the polyps around them (core GspPolyps): xyz in the rock's frame, w seconds since the first touch;
// uPokeT x seconds since the last touch, y strength
uniform vec4 uPokes[8];
uniform vec4 uPokeT[8];
uniform float uPokeCount;
// polyp motion mode (DrawPart.polypMode): 0 ordinary, 1 night tentacles (Euphyllia sweepers, LPS feeding tentacles)
// that grow out of their base as uPolypDrive (core CoralPose.tentacles) rises after dark, long, thin and writhing;
// 2 LPS day tentacles (one strand per instance, bending as a whole, shortening as the colony retracts), 3 inflating
// tissue (bubble vesicles, open brain mantle) that swells by day and deflates as the night tentacles come out,
// 4 pulsing xenia polyps (uPolypDrive = pulse strength)
uniform float uPolypMode;
uniform float uPolypDrive;

out vec3 vWorld;
out vec3 vNormal;
out vec2 vUv;
out vec4 vColor;
out float vVariant;
out float vOpen;
out float vTip;
out float vGlow;
out float vRing;

// Rodrigues rotation of v about the unit axis k
vec3 rotAxis(vec3 v, vec3 k, float a) {
    float c = cos(a), s = sin(a);
    return v * c + cross(k, v) * s + k * dot(k, v) * (1.0 - c);
}

// Tentacle radius (fraction of the stringy length) and length factor at hinge h; tools/blender/anemone.py
// tentacle_profile is the same formula. Stringy: long taper. Bubbled: shorter, a bulb at bp and a narrow tip.
vec2 anemoneProfile(float h, float bubble, float bp) {
    float lf = 1.0 - 0.5 * bubble;
    float rs = 0.085 * (1.0 - 0.5 * h);
    float bq = (h - bp) / 0.25;
    float bulb = exp(-bq * bq);
    float rb = 0.045 * (1.0 - 0.3 * h) + 0.13 * bulb;
    float nip = smoothstep(bp + 0.16, bp + 0.32, h);
    rb = mix(rb, 0.035, nip);
    float r = mix(rs, rb, bubble);
    float cq = (h - 0.93) / 0.07;
    if (h > 0.93) r *= sqrt(clamp(1.0 - cq * cq, 0.0, 1.0));
    return vec2(r, lf);
}

// Sideways tip offset (world cm) one fish contact asks of a tentacle: away from the fish, plus a little of the water it
// drags along. Evaluated once per tentacle (at a point along its axis), so the whole tentacle bends as one piece.
vec3 anemoneContact(vec3 q, vec3 ax, vec3 outward, float len, vec4 c, float k, vec3 drift) {
    vec3 d = q - c.xyz;
    float R = c.w + 0.35 * len;
    float near = 1.0 - smoothstep(0.3 * R, R, length(d));
    // sideways part only, nudged outward from the disc so a tentacle right under the fish still has a smooth way out
    vec3 side = d - ax * dot(d, ax) + outward * (0.2 * R);
    float sl = length(side);
    vec3 dir = sl > 1e-4 ? side / sl : outward;
    vec3 dr = drift * 0.22;
    float dm = length(dr);
    if (dm > 0.5 * len) dr *= 0.5 * len / dm;
    return (dir * (0.85 * R) + dr) * (k * near);
}

void anemone(float phase) {
    float bubble = clamp(uAnem.x, 0.0, 1.0);
    float ext = 1.0 - clamp(uAnem.y, 0.0, 1.0);
    float k = mix(0.45, 1.0, ext);
    vec3 p;
    vec3 n;
    float h = aColor.b;
    vTip = 0.0;
    vRing = 0.0;
    if (aColor.g > 0.5) {
        // oral disc + column: the disc shrinks and the column squats as the animal deflates
        p = aPos * vec3(k, mix(0.75, 1.0, ext), k);
        n = normalize(aNormal * vec3(1.0 / k, 1.0, 1.0 / k));
        vGlow = aColor.r;
        h = 0.0;
    } else {
        float bp = 0.55 + 0.2 * iPhaseVar.y;
        float rl = length(aPos.xz);
        vec2 dir = rl > 1e-5 ? aPos.xz / rl : vec2(0.0);
        vec2 pr = anemoneProfile(h, bubble, bp);
        vec2 pr2 = anemoneProfile(min(h + 0.02, 1.0), bubble, bp);
        float len = 0.35 + 0.65 * ext;
        p = vec3(dir.x * pr.x, h * pr.y, dir.y * pr.x) * len;
        float drdy = (pr2.x - pr.x) / (0.02 * pr.y);
        n = rl > 1e-5 ? normalize(vec3(dir.x, -drdy, dir.y)) : vec3(0.0, 1.0, 0.0);
        // slow writhe about a per-tentacle side axis, larger for long stringy tentacles; the wave travels base to tip
        vec3 side = vec3(cos(phase), 0.0, sin(phase));
        float wr = h * h * (0.08 + 0.3 * (1.0 - bubble)) * sin(uTime * 0.55 + phase * 3.0 - h * 2.2);
        p = rotAxis(p, side, wr);
        n = rotAxis(n, side, wr);
        vGlow = 1.0 - smoothstep(0.1, 0.3, h);
        vTip = bubble * smoothstep(0.84, 0.96, h);
        // no bulb: a pale ring where its equator would be (Fautin 2007 via SeaLifeBase)
        float rq = (h - bp) / 0.045;
        vRing = (1.0 - bubble) * exp(-rq * rq);
    }
    vec3 base = iPosScale.xyz * vec3(k, 1.0, k);
    vec3 v = qrot(iQuat, p * iPosScale.w);
    vec3 nn = qrot(iQuat, n);
    vec3 ax = qrot(iQuat, vec3(0.0, 1.0, 0.0));
    vec2 rad = length(iPosScale.xz) > 1e-4 ? normalize(iPosScale.xz) : vec2(1.0, 0.0);
    if (aColor.g < 0.5) {
        // tentacles tip inward as the animal balls up, and the ones on the food's side curl to the mouth
        vec3 axis = vec3(-rad.y, 0.0, rad.x);
        float sector = smoothstep(0.2, 0.9, cos(atan(rad.y, rad.x) - uAnem.w));
        float a = 0.7 * (1.0 - ext) + 1.5 * clamp(uAnem.z, 0.0, 1.0) * sector;
        v = rotAxis(v, axis, a);
        nn = rotAxis(nn, axis, a);
        ax = rotAxis(ax, axis, a);
    }
    vec4 world = uModel * vec4(base + v, 1.0);
    vec3 wn = normalize(mat3(uModel) * nn);
    if (aColor.g < 0.5) {
        vec3 wBase = (uModel * vec4(base, 1.0)).xyz;
        vec3 wAx = normalize(mat3(uModel) * ax);
        vec3 wOut = normalize(mat3(uModel) * vec3(rad.x, 0.0, rad.y));
        float tl = (0.35 + 0.65 * ext) * (1.0 - 0.5 * bubble) * iPosScale.w * uAnemMisc.y;
        float hw = h * h * iPosScale.w * uAnemMisc.y;
        // flow: bulbs are stiffer than stringy tentacles (phase from the tentacle's base, so it moves as one piece)
        float sw = sin(uTime * 1.3 + phase + dot(wBase.xz, vec2(0.21, 0.13)));
        world.xyz += uSwayDir * (uSwayAmp * (1.0 - 0.6 * bubble) * (0.6 + 0.4 * sw)) * hw;
        // fish pressing in (a nestling clown pair, a blundering tang): each tentacle bends away from them about its base,
        // more toward the tip, so it curves smoothly instead of its vertices being shoved apart
        vec3 q = wBase + wAx * (0.65 * tl);
        vec3 bend = anemoneContact(q, wAx, wOut, tl, uAnemPush, uAnemMisc.x, uAnemDrift.xyz)
                  + anemoneContact(q, wAx, wOut, tl, uAnemPushB, uAnemMisc.z, uAnemDriftB.xyz);
        bend -= wAx * dot(bend, wAx);
        float bl = length(bend);
        if (bl > 1e-4 && tl > 1e-3) {
            float th = min(1.25 * bl / tl, 1.4) * (1.0 - 0.3 * bubble);
            vec3 bax = normalize(cross(wAx, bend));
            float g = th * h;
            world.xyz = wBase + rotAxis(world.xyz - wBase, bax, g);
            wn = rotAxis(wn, bax, g);
        }
    }
    vWorld = world.xyz;
    vNormal = wn;
    vUv = aUv;
    vColor = aColor;
    vVariant = iPhaseVar.y;
    vOpen = ext;
    gl_Position = uViewProj * world;
}

void main() {
    float phase = iPhaseVar.x * 6.2831;
    if (uSwayMode > 1.5) { anemone(phase); return; }
    vTip = 0.0;
    vRing = 0.0;
    vGlow = 1.0;
    float variant = fract(iPhaseVar.y);
    float sc = iPosScale.w;
    float ext = uExtension;
    if (uMatRadius > 0.0) {
        // bare stolon at the margin, young polyps sprouting behind it, the older ones inside a little longer
        float e = gspEdge(iPosScale.xyz, uMatRadius) - floor(iPhaseVar.y) / 16.0;
        sc *= smoothstep(0.5, 2.5, e) * (0.8 + 0.2 * smoothstep(2.5, 8.0, e));
        // GspPolyps.closure: a ring spreading 3 cm/s from each touch to 3.5 cm, shut 4 s after the last touch,
        // reopening over 40 s
        float closed = 0.0;
        for (int i = 0; i < 8; i++) {
            if (float(i) >= uPokeCount) break;
            float st = uPokeT[i].y;
            float ring = min(0.8 + 3.0 * uPokes[i].w, 3.5 * (0.5 + 0.5 * st));
            float d = distance(iPosScale.xyz, uPokes[i].xyz);
            float c = st * (1.0 - smoothstep(ring - 0.8, ring, d)) * (1.0 - smoothstep(4.0, 44.0, uPokeT[i].x));
            closed = max(closed, c);
        }
        ext *= 1.0 - clamp(closed, 0.0, 1.0);
    }
    float hinge = aColor.b;
    bool longTent = aColor.r > 0.5;
    vec3 p = aPos;
    vec3 n = aNormal;
    float open;
    float swayW = hinge;
    if (uPolypMode > 0.5 && uPolypMode < 1.5) {
        // night tentacles: stretch out of the base, bend over about a per-tentacle side axis and writhe slowly,
        // most at the tip; fully in they shrink to a stub inside the day tentacles
        open = clamp(uPolypDrive, 0.0, 1.0);
        vec3 side = vec3(cos(phase), 0.0, sin(phase));
        float wr = hinge * (0.35 + 0.25 * sin(uTime * 0.45 + phase * 3.0 - hinge * 2.0)) * open;
        p.y *= mix(0.04, 1.0, open);
        p.xz *= mix(0.4, 1.0, open);
        p = rotAxis(p, side, wr);
        n = rotAxis(n, side, wr);
        swayW = 3.0 * hinge * hinge * open;
    } else if (uPolypMode > 1.5 && uPolypMode < 2.5) {
        // LPS day tentacles (Euphyllia): each strand bends as a whole about its own side axis, a slow wave running up
        // it; retracting shortens it down into the fleshy mantle
        open = clamp(ext * (0.9 + 0.1 * sin(uTime * 0.35 + phase)), 0.0, 1.0);
        vec3 side = vec3(cos(phase * 1.7), 0.0, sin(phase * 1.7));
        float wr = hinge * (0.15 + 0.2 * sin(uTime * 0.6 + phase * 5.0 - hinge * 1.6));
        p.y *= mix(0.25, 1.0, open);
        p.xz *= mix(0.8, 1.0, open);
        p = rotAxis(p, side, wr);
        n = rotAxis(n, side, wr);
        swayW = 2.0 * hinge * hinge;
    } else if (uPolypMode > 3.5) {
        // pulsing xenia (core Xenia): each polyp is its own pacemaker; the tentacles snap shut and open again more
        // slowly, about once a second at full pulse (uPolypDrive), and the polyps sit still when the pulse is gone
        open = clamp(ext, 0.0, 1.0);
        float drive = clamp(uPolypDrive, 0.0, 1.0);
        float cyc = fract(uTime * (0.45 + 0.5 * drive) + iPhaseVar.x * 3.7);
        float beat = drive * smoothstep(0.0, 0.18, cyc) * (1.0 - smoothstep(0.3, 0.95, cyc));
        float fold = max(1.0 - open, 0.85 * beat) * hinge;
        p.xz *= 1.0 - 0.8 * fold;
        p.y *= 1.0 - 0.3 * fold;
        n.xz *= 1.0 - 0.5 * fold;
        swayW = hinge * (1.0 - 0.6 * beat);
    } else if (uPolypMode > 2.5) {
        // inflating tissue (bubble coral vesicles, the open brain's swollen mantle): the whole piece swells about its
        // base with the colony extension and a slow breath, and deflates as the night tentacles come out
        open = clamp(ext * (1.0 - 0.65 * clamp(uPolypDrive, 0.0, 1.0)) * (0.94 + 0.06 * sin(uTime * 0.25 + phase)), 0.0, 1.0);
        float k = mix(0.35, 1.0, open);
        p *= vec3(k, mix(0.25, 1.0, open), k);
        n = normalize(n * vec3(1.0 / k, 1.0 / mix(0.25, 1.0, open), 1.0 / k));
        swayW = 0.15 * hinge;
    } else if (longTent) {
        // long tentacles stay out: only a small breathing pulse on top of the colony extension
        open = clamp(ext * (0.88 + 0.12 * sin(uTime * 0.3 + phase)), 0.0, 1.0);
        // writhe: each strand bends slowly about its own side axis, most at the tip
        float rl = length(p.xz);
        if (rl > 1e-4) {
            vec2 rad = p.xz / rl;
            vec3 side = vec3(-rad.y, 0.0, rad.x);
            float wr = hinge * hinge * 0.45 * sin(uTime * 0.8 + phase * 3.0 + atan(rad.y, rad.x) * 3.0);
            p = rotAxis(p, side, wr);
            n = rotAxis(n, side, wr);
        }
        // retract: tentacles shorten toward the stalk and the stalk sinks into the mat
        float shut = 1.0 - open;
        p.xz *= 1.0 - 0.9 * shut * hinge;
        p.y *= 1.0 - 0.85 * shut;
        // a long strand bends in the flow like a beam: tips swing ~2.5x a short polyp's
        swayW = 2.5 * hinge * hinge;
    } else {
        open = clamp(ext * (0.6 + 0.4 * sin(uTime * 0.3 + phase)), 0.0, 1.0);
        // close: fold the tentacles in toward the axis and down, and twist about the axis
        float fold = (1.0 - open) * hinge;
        p.xz *= 1.0 - 0.75 * fold;
        p.y *= 1.0 - 0.5 * fold;
        float ang = (1.0 - open) * 1.2 * hinge;
        float c = cos(ang), s = sin(ang);
        p.xz = vec2(c * p.x - s * p.z, s * p.x + c * p.z);
        n.xz = vec2(c * n.x - s * n.z, s * n.x + c * n.z);
    }

    vec3 w = iPosScale.xyz + qrot(iQuat, p * sc);
    if (uSwayMode > 0.5) {
        // ride the branch: the body's extension shrink and tree sway at the instance base (uModel is a pure
        // translation for coral GLBs, so a world-space offset can be added before it), then a quick fringe flutter
        vec3 ip = (uModel * vec4(iPosScale.xyz, 1.0)).xyz;
        vec3 shrunk = uBase + (ip - uBase) * mix(0.55, 1.0, clamp(uExtension, 0.0, 1.0));
        w += shrunk - ip + treeSway(shrunk, uBase, uHeight, uPhase, uSwayDir, uBodySwayAmp, uWake);
        float fl = sin(uTime * 5.7 + phase * 3.0 + dot(iPosScale.xz, vec2(0.9, 0.7)));
        w += uSwayDir * fl * uSwayAmp * hinge * iPosScale.w;
    } else {
        // sway with the flow (coherent phase across a mat)
        float sw = sin(uTime * 1.6 + phase + dot(iPosScale.xz, vec2(0.15, 0.1)));
        w += uSwayDir * sw * uSwayAmp * swayW * sc;
    }
    vec4 world = uModel * vec4(w, 1.0);
    vWorld = world.xyz;
    vNormal = normalize(mat3(uModel) * qrot(iQuat, n));
    vUv = aUv;
    vColor = aColor;
    vVariant = variant;
    vOpen = open;
    gl_Position = uViewProj * world;
}

assets/shaders/rock.frag:
#version 300 es
#include "common.glsl"
#include "lighting.glsl"
// Rock and sand PBR-lite (ARCHITECTURE §8.4 item 1): Lambert + GGX, caustics, hair-algae bloom, Beer-Lambert + fog.
// SAND: tiled detail normal map via a derivative cotangent frame (the GLBs carry no tangents) and the front-glass
// green film (COLOR_0.r). ROCK: distance-based detail levels of procedural relief, plus the small life on it.
// Algae cover (research 09 A6) from the Frame UBO as patchy world-space noise masks: sand gets diatom dust,
// red cyano mats and khaki dino strands; rock tops hair turf, cyano and dinos; shaded rock coralline crust.

in vec3 vWorld;
in vec3 vNormal;
in vec2 vUv;
in vec4 vColor;

uniform sampler2D uAlbedo;
uniform sampler2D uNormalMap;
uniform vec4 uBaseColor;
uniform float uHasTexture;
uniform float uRoughness;
uniform float uNormalStrength; // 0 disables the normal map (Low quality)
uniform float uDetailScale;    // normal-map uv multiplier
// Microfauna on the rock (MicrofaunaState.visible, animals in view per cm² of rock): x harpacticoid copepods,
// y ostracods, z forams (Homotrema), w cyclopoid copepods. Zero turns them off.
uniform vec4 uMicro;
// Up to four fish heads near the camera (world cm; w 1 = in use): pods close to one drop into the turf.
uniform vec4 uPred[4];
#ifndef SAND
// object-space position (static.vert, ROCK): the rock detail is pinned to the rock, so it rides along if a rock moves
in vec3 vObj;
uniform mat4 uModel;
#endif
uniform float uDryRock;        // aquascape builder dry rock: 1 fresh white, 0 fully cured live rock
#ifdef SAND
// Dynamic sand bed (SIMULATION §16, SandFx): r height offset (cm), g freshness, b detritus, a dug cavity under rock.
uniform sampler2D uSandMap;
uniform float uSandOn;
uniform vec2 uSandExtent;
#endif

out vec4 fragColor;

vec3 perturb(vec3 N, vec3 p, vec2 uv, vec3 tn) {
    vec3 dp1 = dFdx(p), dp2 = dFdy(p);
    vec2 du1 = dFdx(uv), du2 = dFdy(uv);
    vec3 dp2perp = cross(dp2, N);
    vec3 dp1perp = cross(N, dp1);
    vec3 T = dp2perp * du1.x + dp1perp * du2.x;
    vec3 B = dp2perp * du1.y + dp1perp * du2.y;
    float invmax = inversesqrt(max(dot(T, T), dot(B, B)) + 1e-12);
    mat3 tbn = mat3(T * invmax, B * invmax, N);
    return normalize(tbn * tn);
}

vec3 hash33(vec3 p) { return vec3(hash13(p), hash13(p + 19.19), hash13(p + 47.31)); }

// Value noise (common.glsl vnoise lattice) with its analytic gradient: xyz = d/dp, for relief normals without
// screen-space derivatives (no 2x2 blockiness up close, no shimmer far away).
vec4 vnoiseD(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    vec3 u = f * f * (3.0 - 2.0 * f);
    vec3 du = 6.0 * f * (1.0 - f);
    float a = hash13(i), b = hash13(i + vec3(1.0, 0.0, 0.0)), c = hash13(i + vec3(0.0, 1.0, 0.0));
    float d = hash13(i + vec3(1.0, 1.0, 0.0)), e = hash13(i + vec3(0.0, 0.0, 1.0)), g = hash13(i + vec3(1.0, 0.0, 1.0));
    float h = hash13(i + vec3(0.0, 1.0, 1.0)), k = hash13(i + vec3(1.0, 1.0, 1.0));
    float k1 = b - a, k2 = c - a, k3 = e - a, k4 = a - b - c + d, k5 = a - c - e + h, k6 = a - b - e + g;
    float k7 = -a + b + c - d + e - g - h + k;
    float v = a + k1 * u.x + k2 * u.y + k3 * u.z + k4 * u.x * u.y + k5 * u.y * u.z + k6 * u.z * u.x + k7 * u.x * u.y * u.z;
    vec3 gr = du * vec3(k1 + k4 * u.y + k6 * u.z + k7 * u.y * u.z,
                        k2 + k5 * u.z + k4 * u.x + k7 * u.z * u.x,
                        k3 + k6 * u.x + k5 * u.y + k7 * u.x * u.y);
    return vec4(v, gr);
}

// Limestone voids: the rock is cut through a field of spherical holes (one maybe in each unit cell, jittered, 2x2x2
// search), so where the surface slices a void it shows a round pit whose size depends on how deep the cut goes, as on
// real live rock. Returns the pit depth profile (0 rim .. 1 centre, a hemisphere) and its gradient (per unit of p).
vec4 voids(vec3 p, float density) {
    vec3 b = floor(p - 0.5);
    vec4 best = vec4(0.0);
    for (int z = 0; z < 2; z++)
    for (int y = 0; y < 2; y++)
    for (int x = 0; x < 2; x++) {
        vec3 c = b + vec3(float(x), float(y), float(z));
        float h = hash13(c + 0.37);
        if (h >= density) continue;
        vec3 j = fract((h / max(density, 1e-3)) * vec3(97.13, 41.71, 13.37) + hash13(c + 5.1));
        vec3 dv = p - (c + 0.2 + 0.6 * j);
        float r = 0.28 + 0.22 * fract(h * 531.7);
        float q = dot(dv, dv) / (r * r);
        if (q < 1.0) {
            float dep = sqrt(1.0 - q);
            // d(dep)/dp = -dv / (r² dep); capped at the rim so the wall stays steep but finite
            if (dep > best.x) best = vec4(dep, -dv / (r * r * max(dep, 0.2)));
        }
    }
    return best;
}

// Detail level weight of a relief octave with `freq` cycles per cm at `fp` (length(fwidth), about two pixel widths):
// 1 while a period spans 8+ pixels, 0 below ~3 (it would only alias).
float lodW(float freq, float fp) { return 1.0 - smoothstep(0.15, 0.33, fp * freq); }   // fp ~ 2 pixel widths

// Colours in life (research 17 §1.3, §3, §6.3, §14.2; hex values converted to linear). The pods are translucent:
// their bodies are mixed over the rock at about half opacity and what reads is the gut, the eye and the egg sacs.
const vec3 FORAM_RED = vec3(0.43, 0.03, 0.025);    // Homotrema rubrum test #B0302A
const vec3 FORAM_PINK = vec3(0.67, 0.26, 0.24);    // weathered / dead test #D68C86
const vec3 FORAM_PORE = vec3(0.12, 0.005, 0.01);
const vec3 TIG_BODY = vec3(0.81, 0.35, 0.19);      // Tigriopus: pale orange cuticle #E8A07A
const vec3 TIG_GUT = vec3(0.69, 0.09, 0.025);      // astaxanthin gut lining #D9542B
const vec3 TISBE_BODY = vec3(0.70, 0.66, 0.55);    // Tisbe: nearly transparent
const vec3 TISBE_GUT = vec3(0.19, 0.25, 0.14);     // diatom-filled gut #7A8A6A
const vec3 POD_EYE = vec3(0.45, 0.006, 0.012);     // naupliar eye #B3121C
const vec3 HARP_EGGS = vec3(0.30, 0.22, 0.10);
const vec3 CYC_BODY = vec3(0.68, 0.72, 0.64);      // cyclopoid: pale grey #D7DDD2
const vec3 CYC_GUT = vec3(0.15, 0.16, 0.07);       // #6B6E4A
const vec3 CYC_EGGS = vec3(0.49, 0.49, 0.25);      // gravid egg sacs #B9B98A
const vec3 OST_SHELL = vec3(0.79, 0.72, 0.58);     // podocopid carapace #E6DDC8
const vec3 OST_GUT = vec3(0.16, 0.10, 0.045);      // #6E5A3C

#ifndef SAND
// Coverage of a 2D signed distance (negative inside) with a pixel-wide edge; fp is about two pixel widths.
float cover(float sd, float fp) { return clamp(0.5 - 2.0 * sd / max(fp, 1e-5), 0.0, 1.0); }
float sdSeg(vec2 q, vec2 a, vec2 b) {
    vec2 pa = q - a, ba = b - a;
    return length(pa - ba * clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0));
}
float sdEll(vec2 q, vec2 r) { return (length(q / r) - 1.0) * min(r.x, r.y); }

// One crawling pod drawn in its own frame: q.x along the body (cm, head +), q.y across. kind 0 harpacticoid, 1
// cyclopoid, 2 ostracod; v per-animal variation (Tigriopus vs Tisbe, gravid females, size); moving 0..1 drives the
// limbs. Returns the coverage and writes the colour.
float podShape(vec2 q, float kind, vec3 v, float moving, float fp, out vec3 col) {
    float sz = 0.8 + 0.4 * v.z;
    q /= sz;
    float m = 0.0;
    if (kind < 0.5) {
        // Harpacticoid (research 17 §1): ~1 mm, cylindrical prosome 2.5x as long as wide, a narrow urosome a third of
        // the length, short forward antennules, two bristle-tipped caudal rami; a red naupliar eye; Tigriopus orange
        // with a red gut, Tisbe glassy with a dark gut; a gravid female carries one egg sac under the urosome.
        bool tig = v.x < 0.5;
        float pro = sdEll(q - vec2(0.012, 0.0), vec2(0.036, 0.0135));
        float uro = sdSeg(q, vec2(-0.022, 0.0), vec2(-0.048, 0.0)) - mix(0.0065, 0.004, clamp((-0.022 - q.x) / 0.026, 0.0, 1.0));
        float body = min(pro, uro);
        float sw = sin(uTime * 14.0 + v.y * 9.0) * 0.004 * moving;   // antennae tapping while it walks
        float app = min(min(sdSeg(q, vec2(0.044, 0.006), vec2(0.056, 0.016 + sw)), sdSeg(q, vec2(0.044, -0.006), vec2(0.056, -0.016 - sw))) - 0.0012,
                        min(sdSeg(q, vec2(-0.047, 0.002), vec2(-0.060, 0.004)), sdSeg(q, vec2(-0.047, -0.002), vec2(-0.060, -0.004))) - 0.0009);
        float gut = sdSeg(q, vec2(-0.040, 0.0), vec2(0.030, 0.0)) - 0.0035;
        float eye = length(q - vec2(0.040, 0.0)) - 0.0028;
        float eggs = v.y < 0.3 ? sdEll(q - vec2(-0.030, 0.0), vec2(0.016, 0.010)) : 1.0;
        // somite boundaries: faint rings across the prosome
        float ring = smoothstep(0.75, 0.95, abs(sin((q.x - 0.012) * 260.0))) * step(pro, 0.0) * step(-0.024, q.x);
        vec3 b = tig ? TIG_BODY : TISBE_BODY;
        col = mix(b, b * 0.75, ring * 0.5);
        col = mix(col, tig ? TIG_GUT : TISBE_GUT, cover(gut, fp) * 0.85);
        col = mix(col, HARP_EGGS, cover(eggs, fp));
        col = mix(col, POD_EYE, cover(eye, fp));
        m = max(max(cover(body, fp) * (tig ? 0.8 : 0.45), cover(app, fp) * 0.3), cover(eggs, fp) * 0.9);
        m = max(m, cover(gut, fp) * (tig ? 0.9 : 0.75));
        m = max(m, cover(eye, fp));
    } else if (kind < 1.5) {
        // Cyclopoid (research 17 §3): oval prosome, slender urosome, antennules swept back at the sides; gravid
        // females carry a pair of egg sacs splayed off the genital somite.
        float pro = sdEll(q - vec2(0.012, 0.0), vec2(0.030, 0.016));
        float uro = sdSeg(q, vec2(-0.016, 0.0), vec2(-0.044, 0.0)) - 0.0045;
        float body = min(pro, uro);
        float app = min(sdSeg(q, vec2(0.036, 0.008), vec2(0.020, 0.034)), sdSeg(q, vec2(0.036, -0.008), vec2(0.020, -0.034))) - 0.0012;
        float eggs = v.y < 0.4 ? min(sdEll(q - vec2(-0.032, 0.011), vec2(0.015, 0.0065)), sdEll(q - vec2(-0.032, -0.011), vec2(0.015, 0.0065))) : 1.0;
        float gut = sdSeg(q, vec2(-0.030, 0.0), vec2(0.026, 0.0)) - 0.004;
        float eye = length(q - vec2(0.036, 0.0)) - 0.0026;
        col = mix(CYC_BODY, CYC_GUT, cover(gut, fp) * 0.8);
        col = mix(col, CYC_EGGS, cover(eggs, fp));
        col = mix(col, POD_EYE, cover(eye, fp));
        m = max(max(cover(body, fp) * 0.4, cover(app, fp) * 0.25), max(cover(eggs, fp) * 0.85, cover(eye, fp)));
        m = max(m, cover(gut, fp) * 0.7);
    } else {
        // Podocopid ostracod (research 17 §6): a smooth oval bivalved carapace about 2:1, slightly kidney-shaped, the
        // dorsal hinge line down the middle, a brown gut showing through and a black eye; while it walks the antennae
        // and legs flicker out of the gape at the front (2-5 Hz strokes).
        vec2 k = q - vec2(0.0, 0.004 * (1.0 - (q.x * q.x) / 0.0016));
        float shell = sdEll(k, vec2(0.040, 0.022));
        float stroke = 0.5 + 0.5 * sin(uTime * 22.0 + v.y * 7.0);
        float ant = moving > 0.5 ? min(sdSeg(q, vec2(0.036, 0.004), vec2(0.050 + 0.008 * stroke, 0.014)), sdSeg(q, vec2(0.036, -0.004), vec2(0.050 + 0.008 * stroke, -0.012))) - 0.0012 : 1.0;
        float hinge = abs(k.y) - 0.0012;
        float gut = sdEll(q - vec2(-0.004, 0.0), vec2(0.022, 0.009));
        float eye = length(q - vec2(0.026, 0.006)) - 0.0024;
        float rim = smoothstep(-0.006, 0.0, shell);   // paler, thinner shell at the margin
        col = mix(OST_SHELL * (0.8 + 0.25 * v.x), OST_GUT, cover(gut, fp) * 0.55);
        col = mix(col, OST_SHELL * 1.15, rim * 0.6);
        col *= 1.0 - 0.3 * cover(hinge, fp) * step(shell, 0.0);
        col = mix(col, vec3(0.01), cover(eye, fp));
        m = max(cover(shell, fp) * 0.6, cover(ant, fp) * 0.3);
    }
    return m;
}

// Small life on the rock, only where it resolves (research 10 / 17): sessile red forams (Homotrema rubrum, 2-8 mm,
// on shaded rock and undersides) and crawling pods (harpacticoid and cyclopoid copepods, ostracods, ~1 mm).
// Densities come from the sim (uMicro, per cm² of rock in view); pods gather in patches and drop into the turf when
// a fish comes near (uPred). Each animal lives in its own lattice cell and stays inside it, so nothing is cut at a
// cell edge; shapes are drawn in the surface plane. N (world) is tilted over the foram domes so they catch the light.
void rockLife(vec3 p, float fp, float sky, vec3 No, mat3 toW, inout vec3 N, inout vec3 albedo, inout float rough) {
    float wf = 1.0 - smoothstep(0.03, 0.08, fp);
    if (wf > 0.0 && uMicro.z > 0.0) {
        const float FC = 1.2;
        vec3 cc = floor(p / FC);
        vec3 hh = hash33(cc + 71.0);
        // cryptic: shaded rock, crevices and undersides; rare on lit tops
        float pref = mix(0.12, 1.0, 1.0 - sky) * mix(1.0, 0.25, smoothstep(0.2, 0.8, No.y));
        if (hh.x < min(uMicro.z * FC * FC * 1.5, 0.6) * pref) {
            vec3 c = (cc + 0.3 + 0.4 * hash33(cc + 5.0)) * FC;
            vec3 dv = p - c;
            vec3 dt = dv - No * dot(dv, No);
            // 2-5 mm, now and then a big one up to 8 mm (Bermuda field guide)
            float r = hh.y > 0.94 ? 0.3 + 1.5 * (hh.y - 0.94) : 0.1 + 0.16 * hh.y;
            float d = length(dt);
            if (d < r * 1.45) {
            vec3 h2 = hash33(cc + 29.0);
            vec3 ax = normalize(cross(No, vec3(0.31, 0.57, 0.76)));
            float ang = atan(dot(dt, cross(No, ax)), dot(dt, ax));
            // morphotypes in their Bermuda proportions: hemispherical 37 %, globose 19, knobby 17, encrusting 12,
            // columnar 3 (the rest drawn hemispherical)
            float mt = hh.z;
            float knobs = 0.0, relief = 1.0, rr = r;
            if (mt < 0.37 || mt >= 0.886) {
                rr = r * (0.92 + 0.08 * sin(ang * 3.0 + h2.y * 6.0));
            } else if (mt < 0.555) {
                rr = r * 0.85; relief = 1.4;
            } else if (mt < 0.726) {
                float n = 4.0 + floor(h2.y * 4.0);
                knobs = pow(abs(cos(ang * n * 0.5 + h2.z * 6.0)), 3.0);
                rr = r * (0.7 + 0.35 * knobs);
                relief = 1.2;
            } else if (mt < 0.849) {
                rr = r * 1.3 * (0.8 + 0.12 * sin(ang * 2.0 + h2.z * 6.0) + 0.08 * sin(ang * 5.0 + h2.y * 9.0));
                relief = 0.35;
            } else {
                rr = r * 0.55; relief = 2.0;
            }
            float m = clamp((rr - d) / max(fp * 0.5, 1e-4) + 0.5, 0.0, 1.0) * step(abs(dot(dv, No)), FC * 0.5) * wf;
            if (m > 0.0) {
                float dome = sqrt(max(1.0 - d * d / (rr * rr), 0.0));
                bool dead = h2.z < 0.1;   // a pale pink empty test now and then
                vec3 base = dead ? FORAM_PINK : FORAM_RED * (0.85 + 0.3 * hh.y);
                // pitted by pores (resolved only up close), paler knob tips
                vec3 pc = floor(dt / 0.03);
                float pore = step(0.55, hash13(pc + cc)) * (1.0 - smoothstep(0.004, 0.012, fp));
                vec3 col = base * (0.55 + 0.45 * dome);
                col = mix(col, FORAM_PINK, knobs * smoothstep(0.6, 1.0, d / rr) * 0.5);
                col = mix(col, FORAM_PORE, pore * 0.5);
                albedo = mix(albedo, col, m);
                rough = mix(rough, 0.55, m);
                // tilt the normal over the dome so the fixtures light one side
                vec3 tilt = toW * (dt / max(rr, 1e-3)) * relief;
                N = normalize(mix(N, normalize(N * max(dome, 0.15) + tilt), m * wf));
            }
            }
        }
    }
    float wp = 1.0 - smoothstep(0.012, 0.03, fp);
    float pods = uMicro.x + uMicro.y + uMicro.w;
    if (wp > 0.0 && pods > 0.0) {
        const float PC = 0.6;
        vec3 cc = floor(p / PC);
        vec3 hh = hash33(cc + 13.0);
        // patchy: pods crowd into turf and detritus pockets (2.4 cm patches) and a little toward shaded faces
        float clump = mix(0.25, 1.75, hash13(floor(p / 2.4) + 3.7)) * mix(1.15, 0.85, smoothstep(0.0, 0.8, No.y));
        if (hh.x < min(pods * PC * PC * 1.5 * clump, 0.85)) {
            float kind = hh.z * pods < uMicro.x ? 0.0 : (hh.z * pods < uMicro.x + uMicro.w ? 1.0 : 2.0);
            vec3 v = hash33(cc + 41.0);
            // gaits (research 17 §1.5, §3, §6.4): harpacticoids crawl 1-3 mm/s in bouts with 0.5-3 s pauses and a
            // rare dart; cyclopoids sit, then hop in a few ms; ostracods scurry steadily with short stops
            float rate = kind < 0.5 ? 0.45 : (kind < 1.5 ? 0.3 : 0.4);
            float t = uTime * rate + hh.y * 17.0;
            float seg = floor(t), f = fract(t);
            float dart = step(0.85, hash13(cc + seg * 3.1));
            float k = kind < 0.5 ? smoothstep(0.0, dart > 0.5 ? 0.05 : 0.45, f)
                    : (kind < 1.5 ? smoothstep(0.0, 0.02, f) : smoothstep(0.0, 0.7, f));
            float moving = kind < 0.5 ? step(f, dart > 0.5 ? 0.05 : 0.45) : (kind < 1.5 ? 0.0 : step(f, 0.7));
            vec3 a = cc + 0.25 + 0.5 * hash33(cc + seg * 1.7);
            vec3 b = cc + 0.25 + 0.5 * hash33(cc + (seg + 1.0) * 1.7);
            vec3 cen = mix(a, b, k) * PC;
            vec3 dv = p - cen;
            vec3 dt = dv - No * dot(dv, No);
            if (dot(dt, dt) < 0.0064) {
            // fish nearby: the pod drops into the turf (shrinks out of sight), back once the fish has gone
            float fear = 0.0;
            if (uPred[0].w > 0.0) {
                vec3 wc = toW * cen + uModel[3].xyz;
                for (int i = 0; i < 4; i++) {
                    if (uPred[i].w > 0.0) fear = max(fear, 1.0 - smoothstep(1.2, 3.0, distance(wc, uPred[i].xyz)));
                }
            }
            if (fear < 0.98) {
                vec3 dir = b - a;
                vec3 ax = dir - No * dot(dir, No);
                ax *= inversesqrt(max(dot(ax, ax), 1e-8));
                vec3 sx = cross(No, ax);
                // ostracods roll a little as they go ("tumbling seed")
                float wob = kind > 1.5 ? 0.15 * sin(uTime * 9.0 + v.y * 6.0) * moving : 0.0;
                vec2 q = vec2(dot(dt, ax), dot(dt, sx)) / (1.0 - fear);
                q = vec2(q.x * cos(wob) - q.y * sin(wob), q.x * sin(wob) + q.y * cos(wob));
                vec3 col;
                float m = podShape(q, kind, v, moving, fp / (1.0 - fear), col) * step(abs(dot(dv, No)), PC * 0.5) * wp;
                float shade = 1.0 - smoothstep(0.0, 0.035, length(q) - 0.03);
                albedo *= 1.0 - 0.3 * wp * shade * (1.0 - m) * (1.0 - fear);   // contact shade round the body
                albedo = mix(albedo, col, m);
                rough = mix(rough, kind > 1.5 ? 0.3 : 0.4, m);
            }
            }
        }
    }
}
#endif

const vec3 ROCK_BLEACH = vec3(0.50, 0.42, 0.28);   // sun-bleached cream-tan skeleton
const vec3 ROCK_WARM = vec3(1.5, 1.0, 0.55);       // baked albedo -> the photos' warm tan (research 11 §4)
const vec3 SAND_GAIN = vec3(1.68, 1.87, 2.45);     // baked cream sand -> bright, cool aragonite (research 11 §8)
const vec3 ROCK_GREY = vec3(0.24, 0.21, 0.16);     // older grey limestone
const vec3 ROCK_FILM = vec3(0.148, 0.170, 0.036); // olive-yellow turf film, #6B7238 (photo green fuzz)
const vec3 SHELL_PINK = vec3(0.50, 0.32, 0.30);    // shell grit
const vec3 SHELL_GREY = vec3(0.24, 0.21, 0.18);    // dark aragonite / rubble grit

const vec3 ALG_HAIR = vec3(0.148, 0.170, 0.036);   // #6B7238 yellow-olive turf, as in the photos
const vec3 ALG_DIATOM = vec3(0.26, 0.13, 0.03);    // tan / golden brown
const vec3 ALG_CYANO = vec3(0.30, 0.020, 0.030);   // burgundy-red slime (reads red, not black, from the room)
const vec3 ALG_CYANO_DARK = vec3(0.09, 0.006, 0.012); // maroon where little light reaches
const vec3 ALG_DINO = vec3(0.30, 0.17, 0.05);      // khaki-brown snot
const vec3 ALG_DINO_DARK = vec3(0.13, 0.075, 0.025); // the thicker brown strands
const vec3 ALG_BUBBLE = vec3(0.02, 0.07, 0.03);    // glossy dark green
const vec3 ALG_CORAL_PINK = vec3(0.33, 0.128, 0.17);    // #9A6472 dusty pink, as on Tee's rock
const vec3 ALG_CORAL_PURPLE = vec3(0.111, 0.055, 0.122); // #5E4462 dusty mauve

// Slimy mats shared by sand and rock (research 09 A6, SIMULATION §11.2).
// Cyano: burgundy-red sheets with a lighter, lifting edge (it peels in sheets), maroon to black-red where little light
// reaches ([lit] 0..1), O2 bubbles trapped under it by day, a wet sheen. Dinos: a khaki-brown snotty film drawn out
// into stringy strands that hold bright O2 bubbles at their tips while the lights are on; at night the film lifts into
// the water (uDinoLift) and only a faint stain stays. Covers are 0..1; n is an fbm3 value (cyano takes the low end,
// dinos the high end, so they sit apart); albedo and roughness are updated in place, gSlime feeds the wet coat.
float gSlime = 0.0;
// Outbreak mats are judged from the room: a slime that has started to spread (past the hidden ~1 % seed) shows as
// patches somewhat larger than its cover share, and dense inside them, so a few-percent bloom already reads at the
// default view; the seed itself stays out of sight.
float slimeShow(float c) { return smoothstep(0.012, 0.035, c) * max(c, 0.9 * sqrt(max(c, 0.0))); }
float slimeDensity(float c) { return mix(0.78, 0.96, smoothstep(0.0, 0.4, c)); }
// A round bubble of radius r (in cells) at a random spot of each cell of `cells` per cm that passes `keep`: 0..1.
float bubbleDots(vec3 p, float cells, float keep, float r) {
    vec3 q = p * cells;
    vec3 c = floor(q);
    float h = hash13(c + 11.0);
    vec3 at = c + 0.5 + (vec3(hash13(c + 3.0), hash13(c + 7.0), hash13(c + 5.0)) - 0.5) * 0.4;
    return step(keep, h) * (1.0 - smoothstep(r * 0.6, r, length(q - at)));
}

void slimeMats(vec3 p, float n, float cyano, float dinos, float lit, vec3 strandScale, inout vec3 albedo, inout float rough) {
    float day = (1.0 - uNight) * clamp(lightIntensity() * 2.0, 0.0, 1.0);
    float cs = slimeShow(cyano);
    float cy = algaePatch(1.0 - n, cs) * slimeDensity(cs);
    float lip = cy * (1.0 - smoothstep(0.2, 0.65, cy));
    vec3 sheet = mix(ALG_CYANO_DARK, ALG_CYANO, clamp(lit, 0.0, 1.0)) * (0.8 + 0.4 * vnoise(p * 0.9 + vec3(4.0, 1.0, 7.0)));
    albedo = mix(albedo, sheet, cy);
    albedo = mix(albedo, ALG_CYANO * 1.5, lip * 0.35);
    // O2 trapped under the sheets by day: pale beads big enough to see from the room
    float bub = bubbleDots(p, 0.9, 0.82, 0.32) * cy * day;
    albedo = mix(albedo, vec3(0.62, 0.66, 0.66), bub * 0.7);
    float ds = slimeShow(dinos);
    float strand = 1.0 - abs(2.0 * vnoise(p * strandScale) - 1.0);
    float di = algaePatch(n, ds) * slimeDensity(ds) * mix(0.5, 1.0, strand) * (1.0 - 0.8 * uDinoLift);
    albedo = mix(albedo, mix(ALG_DINO, ALG_DINO_DARK, smoothstep(0.6, 0.92, strand)), di);
    // bright O2 bubbles held in the snot while the lights are on (the dino tell), more at the strand crests
    float tip = bubbleDots(p + 3.7, 0.75, 0.7, 0.36) * smoothstep(0.35, 0.8, strand) * step(0.3, di) * day;
    tip = max(tip, smoothstep(0.86, 0.97, strand) * step(0.8, hash13(floor(p * 3.1) + 5.0)) * di * day);
    albedo = mix(albedo, vec3(0.80, 0.84, 0.82), tip * 0.85);
    gSlime = clamp(max(cy, 0.6 * di) + tip, 0.0, 1.0);
    rough = mix(rough, 0.22, clamp(max(cy, di), 0.0, 1.0));
}

void main() {
    vec2 uv0 = vUv;
#ifdef SAND
    // The skirt (the sand cross-section seen through the front / side glass) shares its top ring with the bed in
    // tank.glb, so its uv is constant down the wall (vertical smears) and its smooth vertex normals tilt. Take the
    // geometric normal there and project the bed texture onto the wall plane at the bed's own scale (30.475 cm tile).
    vec3 Ng = normalize(cross(dFdx(vWorld), dFdy(vWorld)));
    if (dot(Ng, uCamPos.xyz - vWorld) < 0.0) Ng = -Ng;
    float wall = 1.0 - smoothstep(0.35, 0.6, abs(Ng.y));
    vec2 wp2 = abs(Ng.z) > abs(Ng.x) ? vWorld.xy : vWorld.zy;   // cm on the wall plane
    if (wall > 0.5) uv0 = wp2 / 30.475;
#endif
    vec4 tex = uHasTexture > 0.5 ? texture(uAlbedo, uv0) : vec4(1.0);
    vec3 albedo = toLinear(tex.rgb) * uBaseColor.rgb;
    vec3 N = normalize(vNormal);
    vec3 V = normalize(uCamPos.xyz - vWorld);
    float rough = uRoughness;
    float ao = 1.0;
    float bumpHt = 0.0;   // procedural height (cm) for bumpH: rock pits, sand ripples
    float glint = 0.0;    // sand sparkle weight
    vec3 glintN = N;
#ifdef SAND
    // bright, cool aragonite: the bed in the photos is the brightest thing in the tank (blue-white, L ~0.75)
    albedo *= SAND_GAIN;
    albedo = mix(albedo, vec3(0.27, 0.35, 0.12), clamp(vColor.r, 0.0, 1.0) * 0.25 * (1.0 - wall));
    {
        // aragonite bed: per-grain tone, sparse shell / rubble grit, broad tone drift, flow ripples, damp contact slopes.
        // Grain detail fades with the pixel footprint so it settles to its mean instead of shimmering at a distance.
        float fp = length(fwidth(vWorld));
        float grainVis = 1.0 - smoothstep(0.06, 0.3, fp);
        vec3 gc = floor(vWorld * 7.0);
        float g = hash13(gc);
        albedo *= mix(1.0, 0.84 + 0.32 * g, grainVis * mix(0.35, 0.85, max(smoothstep(0.2, 0.6, N.y), wall)));
        if (wall > 0.0) {
            // side profile against the glass: round 0.5-2 mm aragonite grains with dark gaps, a few shell bits, faint
            // horizontal layering, darker and damper with depth, pod / worm burrows, and a green-brown film near the
            // lit top edge
            N = normalize(mix(N, Ng, wall));
            // two jittered grain layers (~1.6 and ~0.9 mm) so no grid shows
            vec2 q = wp2 * 6.2;
            vec3 gh = hash33(vec3(floor(q), 7.0));
            float grain = 1.0 - smoothstep(0.2 + 0.18 * gh.z, 0.32 + 0.18 * gh.z, length(fract(q) - 0.5 - (gh.xy - 0.5) * 0.6));
            vec2 q2 = mat2(0.8, 0.6, -0.6, 0.8) * wp2 * 11.0 + 3.7;
            vec3 gh2 = hash33(vec3(floor(q2), 13.0));
            float grain2 = 1.0 - smoothstep(0.18 + 0.15 * gh2.z, 0.3 + 0.15 * gh2.z, length(fract(q2) - 0.5 - (gh2.xy - 0.5) * 0.6));
            float wv = wall * (1.0 - smoothstep(0.03, 0.12, fp));
            float body = max(grain * (0.92 + 0.3 * gh.z), grain2 * (0.85 + 0.3 * gh2.z));
            albedo *= mix(1.0, mix(0.72, 1.0, body), wv);
            albedo = mix(albedo, gh.x > 0.5 ? SHELL_PINK : SHELL_GREY, step(0.975, gh.y) * grain * wv * 0.8);
            float layer = sin(wp2.y * 4.2 + vnoise(vec3(wp2.x * 0.25, wp2.y * 0.6, 3.0)) * 4.0);
            albedo *= 1.0 + 0.07 * layer * wall;
            // depth darkening starts a cm below the bed's top edge, so the top of the skirt carries the bed's own tone and
            // the sand meets the front glass without a dark seam
            float deep = smoothstep(uParams2.w - 0.8, -0.5, wp2.y);
            float topEdge = wall * smoothstep(uParams2.w - 1.2, uParams2.w + 0.4, wp2.y);
            albedo = mix(albedo, albedo * vec3(1.12, 1.1, 1.04), topEdge * 0.5);
            albedo *= mix(1.0, 0.85, deep * wall);
            rough = mix(rough, rough * 0.7, deep * wall);
            float worm = 1.0 - abs(2.0 * vnoise(vec3(wp2.x * 0.32, wp2.y * 0.85, 11.0)) - 1.0);
            float pod = smoothstep(0.8, 0.86, vnoise(vec3(wp2 * 0.75, 23.0)));
            // only a few stretches of the pane have tunnels, and they settle into the sand tone at a distance
            float colony = smoothstep(0.55, 0.7, vnoise(vec3(wp2.x * 0.06, 0.0, 41.0)));
            float burrow = max(smoothstep(0.92, 0.96, worm) * colony, pod) * smoothstep(uParams2.w + 0.2, uParams2.w - 1.0, wp2.y);
            albedo *= 1.0 - 0.6 * burrow * wall * (1.0 - smoothstep(0.1, 0.35, fp));
            float film = smoothstep(uParams2.w - 0.3, uParams2.w + 1.8, wp2.y) * (0.3 + 0.7 * vnoise(vec3(wp2 * 0.4, 31.0)));
            albedo = mix(albedo, vec3(0.16, 0.17, 0.07), film * wall * 0.18);
        }
        // shell / rubble chips: a round, jittered blob in ~1 of 25 half-cm cells (spheres cut by the bed surface)
        vec3 cp = vWorld * 2.2;
        vec3 ch = hash33(floor(cp) + 3.7);
        float chipD = length(fract(cp) - 0.5 - (ch - 0.5) * 0.4);
        float chip = step(0.96, ch.x) * smoothstep(0.1 + 0.12 * ch.y, 0.05 + 0.12 * ch.y, chipD);
        float gritVis = (1.0 - smoothstep(0.2, 0.7, fp)) * smoothstep(0.2, 0.6, N.y);
        albedo = mix(albedo, ch.z > 0.6 ? SHELL_PINK : SHELL_GREY, chip * gritVis * 0.7);
        albedo *= 0.9 + 0.2 * vnoise(vWorld * vec3(0.09, 0.2, 0.09));
        float up = smoothstep(0.6, 0.95, N.y);
        if (uQuality >= 0.5) {
            // ripples across the main flow (along x), wavelength ~2.6 cm, warped and in patches; sharp crests
            float warp = vnoise(vWorld * vec3(0.18, 0.1, 0.32));
            float ph = (vWorld.z + warp * 5.0 + vWorld.x * 0.12) * 2.4;
            float r = 1.0 - abs(sin(ph));
            float patchR = smoothstep(0.35, 0.7, vnoise(vWorld * 0.05 + vec3(7.0, 0.0, 3.0)));
            float rip = r * r * patchR * up * (1.0 - smoothstep(0.4, 1.2, fp));
            bumpHt = rip * 0.22;
            albedo *= 1.0 + 0.05 * (rip - 0.3 * patchR * up);
        }
        // mounded sand banked against rock and holes is damper and darker
        float slope = 1.0 - smoothstep(0.75, 0.98, N.y);
        float bank = smoothstep(uParams2.w + 0.8, uParams2.w + 4.5, vWorld.y);
        albedo *= 1.0 - 0.30 * max(slope * step(0.3, N.y), bank * 0.6) * (1.0 - wall);
        // glints: one grain in ~25 is a cleaved facet that flashes when it lines up with a fixture
        if (uQuality >= 0.5) {
            vec3 gr = hash33(gc + 11.0);
            glint = step(0.96, gr.x) * grainVis * up;
            glintN = normalize(N + (gr - 0.5) * vec3(0.9, 0.0, 0.9));
        }
    }
    if (uSandOn > 0.5) {
        vec2 ext = max(uSandExtent, vec2(1.0));
        vec2 suv = clamp(vWorld.xz / ext, 0.0, 1.0);
        vec4 sm = textureLod(uSandMap, suv, 0.0);
        vec2 ts = vec2(textureSize(uSandMap, 0));
        vec2 cell = ext / ts;
        vec2 du = vec2(1.0 / ts.x, 0.0);
        vec2 dv = vec2(0.0, 1.0 / ts.y);
        float hx = (textureLod(uSandMap, suv + du, 0.0).r - textureLod(uSandMap, suv - du, 0.0).r) / (2.0 * cell.x);
        float hz = (textureLod(uSandMap, suv + dv, 0.0).r - textureLod(uSandMap, suv - dv, 0.0).r) / (2.0 * cell.y);
        // slope of the displaced surface (the mesh normal is the flat bed's)
        N = normalize(N + vec3(-hx, 0.0, -hz) * step(0.5, N.y));
        // freshly turned sand: the damp, darker layer from below, speckled, a little glossier
        float wet = clamp(sm.g, 0.0, 1.0);
        float speck = hash13(floor(vWorld * 6.0));
        albedo *= mix(1.0, 0.66 + 0.1 * speck, wet);
        rough = mix(rough, rough * 0.65, wet);
        // mulm collects as a brown film; sifted patches come up clean and bright
        albedo = mix(albedo, vec3(0.16, 0.11, 0.06), smoothstep(0.35, 1.5, sm.b) * 0.45);
        albedo *= mix(1.06, 1.0, smoothstep(0.0, 0.2, sm.b));
        // a, dug cavity under rock (SandBed.cavity): the burrow floor sits in the rock's shadow, darkest deep in
        albedo *= 1.0 - 0.55 * clamp(sm.a, 0.0, 1.0);
    }
    if (dot(uAlgaeSand, vec4(1.0)) > 0.001) {
        vec3 sp = vWorld * 0.07;
        float n1 = fbm3(sp);
        float n2 = fbm3(sp * 1.7 + vec3(31.0, 7.0, 13.0));
        // diatoms: powdery brown dust, plus a faint even haze at high cover
        float dia = algaePatch(n2, uAlgaeSand.x) * algaeDensity(uAlgaeSand.x) * 0.8 + uAlgaeSand.x * 0.2;
        albedo = mix(albedo, ALG_DIATOM, clamp(dia, 0.0, 1.0));
        // stray hair tufts (sand is a poor substrate)
        albedo = mix(albedo, ALG_HAIR, algaePatch(n1, uAlgaeSand.w) * 0.6);
        slimeMats(vWorld, n1, uAlgaeSand.y, uAlgaeSand.z, 0.8, vec3(0.14, 0.8, 0.5), albedo, rough);
    }
#else
    // Rock detail levels: the mesh normals are smoothed over ~2 cm (tools/blender/rock_surface.py), and the relief
    // comes back here as procedural octaves with analytic gradients. Each octave fades out once its period spans fewer
    // than ~4 pixels (lodW), so a close camera sees pores, vugs and grit while a far one pays for two octaves only.
    // COLOR_0 (rock_surface.py): r cavity, g ridge, b open sky (SDF ambient occlusion), a broad blotch noise.
    float fp = length(fwidth(vWorld));   // cm per pixel (about two pixel widths)
    float fpL = uQuality >= 0.5 ? fp : 100.0;   // Low quality: lumps only
    float cavity = vColor.r, ridge = vColor.g, sky = vColor.b;
    rough = uRoughness;
    ao = (0.3 + 0.7 * sky) * (1.0 - 0.35 * cavity);
    // warm tan limestone (photos: hue 25-42); one multiply on the baked albedo
    albedo *= ROCK_WARM;
    vec3 op = vObj;            // detail coordinates: object space
    mat3 toW = mat3(uModel);   // rigid (no scale): object -> world for gradients and normals
    vec3 No = N * toW;         // world normal in object space (transpose of a rotation)
    vec3 relief = vec3(0.0);   // gradient of the relief height in object space (cm / cm)
    float pores = 0.0, grit = 0.5, lost = 0.0;
    // lumps (2 cm period): always on, and its value doubles as the mid-scale tone noise
    vec4 n0 = vnoiseD(op * 0.5 + vec3(1.7, 9.2, 4.4));
    relief += n0.yzw * (0.5 * 0.45);
    float mid = n0.x;
    float big = vColor.a;   // fbm3(vWorld * 0.05 + (3.1, 7.7, 1.3)), baked per vertex
    {
        // big holes (~1-2 cm across, sparse): what gives live rock its texture from across the room
        vec4 v0 = voids(op * 0.45 + vec3(2.0, 17.0, 9.0), 0.34 + (big - 0.5) * 0.4);
        pores = v0.x;
        relief -= v0.yzw * (0.45 * 0.8);
        // pores (~7 mm): rounded pits, denser in some blotches than others
        float w1 = lodW(1.4, fpL);
        lost += 1.0 - w1;
        if (w1 > 0.0) {
            vec4 v1 = voids(op * 1.4 + vec3(11.0, 5.0, 2.0), 0.3 + (big - 0.5) * 0.6);
            pores = max(pores, v1.x * (0.6 + 0.4 * cavity) * w1);
            relief -= v1.yzw * (1.4 * 0.22 * w1);
        }
        // vugs and boring holes (~3 mm)
        float w2 = lodW(3.6, fpL);
        lost += 1.0 - w2;
        if (w2 > 0.0) {
            vec4 v2 = voids(op * 3.6 + vec3(4.0, 13.0, 8.0), 0.35);
            pores = max(pores, v2.x * 0.8 * w2);
            relief -= v2.yzw * (3.6 * 0.08 * w2);
        }
        // grit (~1 mm) and micro grain (~0.4 mm): close-ups only
        float w3 = lodW(9.0, fpL);
        lost += 1.0 - w3;
        if (w3 > 0.0) {
            vec4 n3 = vnoiseD(op * 9.0 + vec3(7.0, 2.0, 19.0));
            relief += n3.yzw * (9.0 * 0.03 * w3);
            grit = mix(0.5, n3.x, w3);
            float w4 = lodW(23.0, fpL);
            if (w4 > 0.0) {
                vec4 n4 = vnoiseD(op * 23.0 + vec3(3.0, 29.0, 5.0));
                relief += n4.yzw * (23.0 * 0.009 * w4);
                grit = mix(grit, 0.5 * (grit + n4.x), w4);
            }
        }
    }
    // tilt the smooth normal by the relief slope (tangential part only)
    relief = toW * relief;
    N = normalize(N - (relief - N * dot(relief, N)));
    // detail the far view can no longer resolve turns into a slightly rougher, flatter-toned surface
    rough = mix(rough, min(rough + 0.12, 1.0), lost / 3.0);
    {
        // Live-rock character, independent of the algae covers below: broad bleached / grey limestone blotches,
        // porous pits, cavity AO and bright worn ridges, a faint coralline baseline (real live rock always carries
        // some) and a soft wet sheen.
        float lum = dot(albedo, vec3(0.3, 0.59, 0.11));
        float bl = smoothstep(0.5, 0.68, big + (mid - 0.5) * 0.25);
        float gr = smoothstep(0.46, 0.32, big);
        albedo = mix(albedo, ROCK_BLEACH * (0.6 + 3.0 * lum), bl * 0.5 + 0.28);
        albedo = mix(albedo, ROCK_GREY * (0.6 + 3.0 * lum), gr * 0.15);
        // thin olive film of turf / diatoms that live rock always carries, heavier on lit, up-facing crusts
        float film = smoothstep(0.3, 0.7, mid) * mix(0.3, 0.65, smoothstep(0.0, 0.8, N.y));
        albedo = mix(albedo, ROCK_FILM * (0.7 + 2.0 * lum), film * 0.34);
        // the baked albedo's coralline zones were mauve / purple; Tee's rock carries pink-red coralline: pull the blue
        // out of purple tones
        float purple = clamp((albedo.b - albedo.g) * 6.0, 0.0, 1.0) * clamp((albedo.r - albedo.g) * 6.0, 0.0, 1.0);
        albedo.b = mix(albedo.b, albedo.g * 1.15, purple * 0.7);
        // pores too small to resolve keep their average darkening, so the far tone matches the close one
        albedo *= (1.0 - 0.5 * pores * pores) * (1.0 - 0.07 * lost / 3.0) * (0.8 + 0.4 * grit) * (0.8 + 0.4 * mid) * (1.0 - 0.25 * cavity);
        albedo = mix(albedo, ROCK_BLEACH * 1.1, ridge * 0.1 * (1.0 - pores));
        ao *= 1.0 - 0.6 * pores * pores;   // deep pore bottoms see little of the water above
        // coralline crust in lit-but-shaded spots, with pale growth margins and its own fine bumps up close
        float cbn = vnoise(op * 0.13 + vec3(19.0, 3.0, 7.0));
        float cb = smoothstep(0.76, 0.86, cbn) * (1.0 - 0.6 * smoothstep(0.1, 0.7, N.y)) * smoothstep(0.15, 0.5, sky);
        float margin = cb * (1.0 - smoothstep(0.25, 0.8, cb));
        // mostly pink-red, as on Tee's rock; purple only in a few deep-shade patches
        albedo = mix(albedo, mix(ALG_CORAL_PINK, ALG_CORAL_PURPLE, smoothstep(0.6, 0.9, mid) * (1.0 - sky)) * (0.65 + 0.35 * grit), cb * 0.22 * (1.0 - pores));
        albedo = mix(albedo, vec3(0.62, 0.52, 0.58), margin * 0.3);
        rough = mix(rough, 0.6, 0.45 * smoothstep(0.45, 0.8, mid) * (1.0 - pores));
    }
    if (uDryRock > 0.0) {
        // bleached white aragonite fresh from the bag; a tan bacterial / diatom film comes in partway through the cure,
        // then the live-rock colour and coralline above take over
        float dn = vnoise(vWorld * 0.4 + vec3(2.0, 5.0, 9.0));
        vec3 dry = vec3(0.80, 0.77, 0.70) * (0.86 + 0.22 * dn);
        dry = mix(dry, vec3(0.42, 0.33, 0.20), 4.0 * uDryRock * (1.0 - uDryRock) * 0.6 * smoothstep(0.3, 0.7, dn));
        albedo = mix(albedo, dry, uDryRock);
        rough = mix(rough, 0.85, uDryRock);
    }
    float hair = tex.a; // baked hair-algae mask in the albedo alpha
    float top = smoothstep(0.1, 0.7, N.y);
    vec4 cv = mix(uAlgaeShade, uAlgaeTop, top);
    float hairC = max(uAlgaeTop.x, uAlgaeBloom) * top;
    float coralC = uAlgaeShade.x * mix(1.0, 0.25, top);
    if (hairC + coralC + cv.y + cv.z + cv.w > 0.001) {
        vec3 rp = op * 0.18;
        float n1 = fbm3(rp);
        float n2 = fbm3(rp * 1.9 + vec3(5.0, 23.0, 11.0));
        // coralline: pink/purple matte crust with pale growth margins
        float cr = algaePatch(n2, coralC);
        float edge = cr * (1.0 - smoothstep(0.35, 0.9, cr));
        vec3 crust = mix(ALG_CORAL_PINK, ALG_CORAL_PURPLE, smoothstep(0.35, 0.65, n1));
        albedo = mix(albedo, crust, cr * algaeDensity(coralC));
        albedo = mix(albedo, vec3(0.6, 0.5, 0.58), edge * 0.35);
        rough = mix(rough, 0.9, cr);
        // hair turf toward #3B5B2E on up-facing rock, hugging the baked hair mask
        float ht = algaePatch(n1 + (hair - 0.5) * 0.12, hairC) * algaeDensity(hairC) * (0.6 + 0.4 * hair);
        albedo = mix(albedo, ALG_HAIR, clamp(ht + hairC * 0.25 * hair, 0.0, 1.0));
        // bubble algae: a glossy dark-green tint in small clustered spots (no geometry)
        float bb = algaePatch(0.5 + (vnoise(op * 0.6) - 0.5) * 0.63, cv.w) * algaeDensity(cv.w);
        albedo = mix(albedo, ALG_BUBBLE, bb);
        rough = mix(rough, 0.15, bb);
        // cyano and dinos sit in the low-flow, low-light places: darker there (sky = open-sky AO)
        slimeMats(op, n1, cv.y, cv.z, mix(0.3, 1.0, max(top, sky)), vec3(0.8, 0.12, 0.8), albedo, rough);
    }
    // the animals and forams on top of whatever covers the rock
    if (uQuality >= 0.5) rockLife(op, fp, sky, No, toW, N, albedo, rough);
#endif
#ifdef SAND
    if (uNormalStrength > 0.0) {
        vec3 tn = texture(uNormalMap, uv0 * uDetailScale).xyz * 2.0 - 1.0;
        tn.xy *= uNormalStrength;
        N = perturb(N, vWorld, uv0 * uDetailScale, normalize(tn));
    }
    if (uQuality >= 0.5) N = bumpH(N, vWorld, bumpHt); // uniform branch: derivatives stay defined
    // the cross-section against the glass is lit by light scattered through the bed and the pane: wrap it
    vec3 col = shadeLit(albedo, N, V, vWorld, rough, ao, 0.04, wall * 0.7, 1.0);
    if (gSlime > 0.01 && uQuality >= 0.5) col += wetCoat(N, V, vWorld, 0.12, 0.7 * gSlime);
    if (glint > 0.0) {
        // sparkle: a tight specular lobe on the grain's own facet, from both fixtures (none in rock/fish shadow)
        for (int i = 0; i < 2; i++) {
            vec3 L;
            vec3 rad = fixtureAt(i, L);
            float s = pow(max(dot(glintN, normalize(V + L)), 0.0), 90.0);
            col += rad * s * glint * 1.6 * gShadow;
        }
    }
#else
    // slight wrap: crusts and turf scatter light past the terminator
    vec3 col = shadeLit(albedo, N, V, vWorld, rough, ao, 0.04, 0.25, 1.0);
    if (gSlime > 0.01 && uQuality >= 0.5) col += wetCoat(N, V, vWorld, 0.12, 0.7 * gSlime);
#endif
    col = applyWater(col, vWorld);
    fragColor = vec4(tonemap(col), 1.0);
}

assets/shaders/room.frag:
#version 300 es
#include "common.glsl"
#include "lighting.glsl"
const float ROOM_EXPOSURE = 0.4;
// My tank's room (HomeRoom.kt, tools/blender/rooms.py) and the stand under the tank (tools/blender/stands.py). The
// room has its own soft light, not the AI Prime fixtures: daylight from the room (uDay: 1 at noon, 0 at night) as a
// warm key from the front left and a hemisphere fill, a floor lamp that glows in the evening, and the tank's own
// light spilling out of its open top onto the wall and ceiling and out of the front glass onto the floor. Corners,
// the floor under the stand and the wall behind the tank are softly shaded; far patterns fade out and colours are a
// little muted, so the room frames the tank without pulling the eye from it.
//
// Kinds (HomeRoomScene.kindOf, from the material name): 0 own colour, 1 stand paint (uPaint), 2 stand trim (uTrim),
// 3 metal (steel, or gold with uBrass), 4 dark insides, 5 glow strip (uGlowOn), 6 sump window, 7 floor, 8 wall,
// 9 ceiling, 10 lamp shade, 11 rug, 12 leaves, 13 clear plastic / glass, 14 a window's outside view (uOutside: the
// scene's view, drawn procedurally and softly, as if a little out of focus), 15 fire. COLOR_0.r is baked occlusion. Walls and
// floor take their pattern and two colours from the room shop (uWallStyle / uFloorStyle, core room/Decor.kt RoomStyle).

in vec3 vWorld;
in vec3 vNormal;
in vec2 vUv;
in vec4 vColor;

uniform sampler2D uAlbedo;
uniform vec4 uBaseColor;
uniform float uHasTexture;
uniform float uRoughness;
uniform vec3 uEmissive;
uniform float uAlphaCutoff;
uniform float uKind;
uniform float uGrain;         // 1: wood grain (material named *wood* / *plank*)
uniform vec3 uPaint;          // stand colours (linear)
uniform vec3 uTrim;
uniform float uBrass;         // 1: gold handles
uniform float uGlowOn;        // this glow part is lit (the Glow strip extra, or the reef pro's own edge light)
uniform float uGlowStrip;     // the Glow strip extra is on: its light on the floor
uniform float uDay;           // room daylight 0..1
uniform vec4 uLampPos;        // xyz the floor lamp's bulb (cm), w 1 when the room has one
uniform vec3 uLampCol;        // its colour (linear, x brightness)
uniform vec4 uTankBox;        // x length, y top of the glass, z depth, w unused (the glass box: x 0..len, z 0..depth)
uniform vec4 uFoot;           // stand footprint on the floor: x0, x1, z0, z1
uniform vec4 uRoomBox;        // room: x0, x1, back z, floor y
uniform float uFloorStyle;    // RoomStyle: 0 planks, 1 tile, 2 checker, 3 carpet, 4 slate, 5 metal deck, 6 tatami
uniform float uWallStyle;     // RoomStyle: 0 paint, 1 stripes, 2 waves, 3 brick, 4 panels, 5 logs, 6 metal, 7 boards
uniform vec3 uFloorA;         // the floor's two colours (linear)
uniform vec3 uFloorB;
uniform vec3 uWallA;          // the walls' two colours (linear)
uniform vec3 uWallB;
uniform float uOutside;       // kind 14: 1 garden, 2 beach, 3 city, 4 snowy pines, 5 cherry blossom, 6 space

out vec4 fragColor;

const float FLOOR_Y = -82.0;

float luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

// Rounded-box distance in 2D: < 0 inside.
float boxDist(vec2 p, vec2 lo, vec2 hi) {
    vec2 c = (lo + hi) * 0.5, h = (hi - lo) * 0.5;
    vec2 q = abs(p - c) - h;
    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);
}

// Oak planks: 14 cm boards along x, staggered 120 cm lengths, per-board tone and a stretched grain. [fw] is the
// pixel footprint: seams and grain fade out where they would alias (far away, the "out of focus" floor).
vec3 planks(vec3 p, vec3 base, float fw) {
    float row = floor(p.z / 14.0);
    float off = hash12(vec2(row, 3.0)) * 120.0;
    float col = floor((p.x + off) / 120.0);
    vec2 f = vec2(fract((p.x + off) / 120.0) * 120.0, fract(p.z / 14.0) * 14.0);
    float seam = min(min(f.x, 120.0 - f.x), min(f.y, 14.0 - f.y));
    float aa = clamp(fw * 1.5, 0.05, 6.0);
    float line = 1.0 - smoothstep(0.0, 0.25 + aa, seam);
    float fade = 1.0 - smoothstep(0.6, 2.5, fw);
    float tone = mix(0.86, 1.1, hash12(vec2(row, col)));
#if QUALITY > 0
    float grain = vnoise(vec3(p.x * 0.04, p.z * 1.3, row * 3.1)) * 0.6 + vnoise(vec3(p.x * 0.11, p.z * 3.0, col)) * 0.4;
#else
    float grain = 0.5;   // Low: board tones and seams only
#endif
    vec3 c = base * mix(1.0, tone * mix(0.9, 1.08, grain), fade);
    return c * (1.0 - 0.45 * line * fade);
}

// A seam line [d] cm from the nearest joint, faded out with distance (the pixel footprint [fw]).
float seamLine(float d, float width, float fw) {
    return (1.0 - smoothstep(0.0, width + clamp(fw * 1.5, 0.05, 6.0), d)) * (1.0 - smoothstep(0.6, 2.5, fw));
}

// The floor's pattern (uFloorStyle) in its two colours.
vec3 floorPattern(vec3 p, float fw) {
    int st = int(uFloorStyle + 0.5);
    vec3 a = uFloorA, b = uFloorB;
    float fade = 1.0 - smoothstep(0.6, 2.5, fw);
    if (st == 1 || st == 2) {
        // square tiles with grout (1), or a checkerboard (2)
        float s = st == 1 ? 40.0 : 30.0;
        vec2 c = floor(p.xz / s), f = fract(p.xz / s) * s;
        float g = min(min(f.x, s - f.x), min(f.y, s - f.y));
        vec3 t = st == 1 ? a * mix(0.95, 1.04, hash12(c)) : (mod(c.x + c.y, 2.0) < 0.5 ? a : b);
        return mix(t, st == 1 ? b : t * 0.7, seamLine(g, st == 1 ? 0.5 : 0.15, fw));
    }
    if (st == 3) return a * mix(1.0, mix(0.9, 1.07, vnoise(vec3(p.xz * 0.6, 0.0))) * mix(0.94, 1.04, vnoise(vec3(p.xz * 0.05, 2.0))), fade);
    if (st == 4) {
        // slate: staggered 60 x 30 stones, each its own tone between the two colours
        float row = floor(p.z / 30.0);
        float x = p.x + mod(row, 2.0) * 30.0;
        vec2 c = vec2(floor(x / 60.0), row), f = vec2(fract(x / 60.0) * 60.0, fract(p.z / 30.0) * 30.0);
        float g = min(min(f.x, 60.0 - f.x), min(f.y, 30.0 - f.y));
        vec3 t = mix(a, b, hash12(c)) * mix(1.0, mix(0.92, 1.06, vnoise(vec3(p.xz * 0.15, c.x))), fade);
        return mix(t, t * 0.45, seamLine(g, 0.4, fw));
    }
    if (st == 5) {
        // metal deck: 50 cm plates, a faint diamond tread and darker seams
        vec2 f = fract(p.xz / 50.0) * 50.0;
        float g = min(min(f.x, 50.0 - f.x), min(f.y, 50.0 - f.y));
        vec2 d = fract(vec2(p.x + p.z, p.x - p.z) / 4.0) - 0.5;
        float tread = smoothstep(0.32, 0.22, length(d)) * fade;
        return mix(a * (1.0 + 0.08 * tread), b, seamLine(g, 0.4, fw));
    }
    if (st == 6) {
        // tatami: 90 x 180 mats in a staggered weave, straw lines along each, a dark cloth edge on the long sides
        float row = floor(p.z / 90.0);
        float x = p.x + mod(row, 2.0) * 90.0;
        vec2 f = vec2(fract(x / 180.0) * 180.0, fract(p.z / 90.0) * 90.0);
        float straw = 0.5 + 0.5 * sin(f.y * 3.1);
        vec3 t = a * mix(1.0, mix(0.93, 1.03, straw), fade);
        float edge = min(f.y, 90.0 - f.y);
        t = mix(t, b, 1.0 - smoothstep(3.0, 3.6 + fw, edge));
        return mix(t, t * 0.6, seamLine(min(f.x, 180.0 - f.x), 0.3, fw));
    }
    return planks(p, a, fw);
}

// The walls' pattern (uWallStyle) in their two colours. [u] runs along the wall, [y] up it.
vec3 wallPattern(vec3 p, vec3 n, float fw) {
    int st = int(uWallStyle + 0.5);
    vec3 a = uWallA, b = uWallB;
    float u = abs(n.x) > 0.5 ? p.z : p.x;
    float y = p.y - FLOOR_Y;
    float fade = 1.0 - smoothstep(0.6, 2.5, fw);
    float soft = clamp(fw * 1.5, 0.05, 6.0);
    if (st == 1) {
        // wide stripes with a thin pinstripe between
        float f = fract(u / 24.0) * 24.0;
        float band = smoothstep(11.5 - soft, 11.5 + soft, f) * (1.0 - smoothstep(23.5 - soft, 23.5 + soft, f));
        return mix(a, b, band * mix(0.6, 1.0, fade));
    }
    if (st == 2) {
        // wave print: rows of little scallops
        vec2 q = vec2(u / 16.0, y / 10.0);
        float row = floor(q.y);
        vec2 f = vec2(fract(q.x + mod(row, 2.0) * 0.5) - 0.5, fract(q.y));
        float r = length(vec2(f.x, f.y * 0.62));
        float ring = smoothstep(0.08 + soft * 0.05, 0.0, abs(r - 0.42));
        return mix(a, b, ring * fade * 0.6);
    }
    if (st == 3) {
        // brick: 21 x 7 cm in running bond, each its own tone, pale mortar
        float row = floor(y / 7.5);
        float x = u + mod(row, 2.0) * 11.0;
        vec2 c = vec2(floor(x / 22.0), row), f = vec2(fract(x / 22.0) * 22.0, fract(y / 7.5) * 7.5);
        float g = min(min(f.x, 22.0 - f.x), min(f.y, 7.5 - f.y));
        vec3 t = a * mix(0.82, 1.12, hash12(c)) * mix(1.0, mix(0.9, 1.06, vnoise(vec3(u * 0.4, y * 0.4, 1.0))), fade);
        return mix(t, b, seamLine(g, 0.6, fw));
    }
    if (st == 4 || st == 7) {
        // wood panels (vertical boards, 4) or painted boards (horizontal, 7) with dark gaps
        float w = st == 4 ? 15.0 : 16.0;
        float q = st == 4 ? u : y;
        float c = floor(q / w), f = fract(q / w) * w;
        vec3 t = st == 4 ? mix(a, b, hash12(vec2(c, 5.0)) * 0.6) : a * mix(0.97, 1.03, hash12(vec2(c, 7.0)));
        return mix(t, st == 4 ? b * 0.45 : b * 0.85, seamLine(min(f, w - f), st == 4 ? 0.3 : 0.25, fw));
    }
    if (st == 5) {
        // logs: round 22 cm logs, lit across their curve, dark chinking between
        float f = fract(y / 22.0);
        float c = floor(y / 22.0);
        float round = sin(f * 3.14159);
        vec3 t = mix(b, a, sqrt(max(round, 0.0))) * mix(0.9, 1.08, hash12(vec2(c, 9.0)));
        t *= mix(1.0, mix(0.9, 1.06, vnoise(vec3(u * 0.05, c, 3.0))), fade);
        return mix(t, b * 0.35, (1.0 - smoothstep(0.0, 0.07 + soft * 0.02, round)) * fade);
    }
    if (st == 6) {
        // metal: 80 x 50 cm panels with seams and rivets, a darker band at hand height
        vec2 f = vec2(fract(u / 80.0) * 80.0, fract(y / 50.0) * 50.0);
        float g = min(min(f.x, 80.0 - f.x), min(f.y, 50.0 - f.y));
        vec3 t = mix(a, b, smoothstep(88.0, 89.0, y) * (1.0 - smoothstep(118.0, 119.0, y)));
        float rivet = length(vec2(min(f.x, 80.0 - f.x) - 3.0, (fract(y / 10.0) - 0.5) * 10.0));
        t *= 1.0 - 0.25 * smoothstep(0.9, 0.5, rivet) * fade;
        return mix(t, t * 0.5, seamLine(g, 0.4, fw));
    }
    return a * mix(0.97, 1.03, vnoise(p * 0.05));
}

// What a window looks onto (uOutside), along [dir] from the eye: soft shapes only, so it reads as out of focus.
vec3 outsideView(vec3 dir, float day) {
    int v = int(uOutside + 0.5);
    float az = atan(dir.x, -dir.z);
    float el = dir.y / max(length(dir.xz), 1e-3);
    float night = 1.0 - day;
    vec3 zen = mix(vec3(0.010, 0.016, 0.045), vec3(0.22, 0.46, 0.80), day);
    vec3 hor = mix(vec3(0.030, 0.040, 0.080), vec3(0.72, 0.82, 0.90), day);
    vec3 sky = mix(hor, zen, smoothstep(-0.05, 0.7, el));
    float stars = step(0.9965, hash12(floor(vec2(az, el) * 260.0))) * night * smoothstep(0.0, 0.2, el);
    if (v == 6) {
        // space: stars and the slowly turning Earth below, with its thin blue air
        vec3 c = vec3(0.004, 0.006, 0.014) + step(0.992, hash12(floor(vec2(az, el) * 300.0))) * vec3(0.9);
        vec2 e = vec2(az + 0.3, el - 0.12);
        float r = length(e) / 0.3;
        if (r < 1.0) {
            vec2 g = e / 0.3;
            vec3 sp = vec3(g, sqrt(1.0 - r * r));
            float lon = atan(sp.x, sp.z) + uTime * 0.01;
            vec3 q = vec3(lon * 2.0, sp.y * 3.0, 0.0);
            float land = smoothstep(0.55, 0.62, vnoise(q * 1.3) * 0.7 + vnoise(q * 3.1) * 0.3);
            float cloud = smoothstep(0.55, 0.75, vnoise(q * 2.3 + vec3(uTime * 0.005, 0.0, 4.0)));
            vec3 ground = mix(vec3(0.03, 0.12, 0.32), vec3(0.20, 0.30, 0.14), land);
            float lit = smoothstep(-0.25, 0.4, dot(sp, normalize(vec3(-0.7, 0.4, 0.6))));
            c = mix(ground, vec3(0.75), cloud * 0.8) * (0.05 + 0.65 * lit);
        }
        c += vec3(0.15, 0.35, 0.9) * exp(-abs(r - 1.0) * 30.0) * 0.6;
        return c;
    }
    if (v == 3) {
        // city: two rows of towers with lit windows (more of them at night), a warm glow over the streets
        vec3 c = sky + stars + vec3(0.12, 0.06, 0.03) * night * exp(-max(el, 0.0) * 6.0);
        for (int layer = 0; layer < 2; layer++) {
            float n = layer == 0 ? 26.0 : 12.0;
            float x = az * n + float(layer) * 7.3;
            float id = floor(x);
            float h = (layer == 0 ? 0.05 : 0.0) + hash12(vec2(id, float(layer))) * (layer == 0 ? 0.28 : 0.42) - 0.08;
            if (el < h) {
                vec3 wall = mix(vec3(0.02, 0.025, 0.04), hor * 0.55, day) * (layer == 0 ? 1.25 : 1.0);
                vec2 w = vec2(fract(x) * 7.0, el * 120.0);
                vec2 wc = floor(w);
                float inWin = step(0.25, fract(w.x)) * step(0.35, fract(w.y)) * step(0.8, fract(x) * 7.0) * step(fract(x) * 7.0, 6.2);
                float on = step(mix(0.9, 0.78, night), hash12(wc + id * 13.0));
                c = wall + inWin * on * mix(vec3(0.04, 0.05, 0.06), vec3(1.0, 0.72, 0.38) * (layer == 0 ? 0.3 : 0.5), night);
            }
        }
        return c;
    }
    vec3 c = sky + stars;
    if (v == 2) {
        // beach: sun or moon, the sea with glints, foam rolling in, then sand
        vec2 sd = vec2(az - 0.45, el - 0.28);
        c += mix(vec3(0.9, 0.9, 1.0) * 0.6, vec3(1.0, 0.85, 0.55) * 1.5, day) * smoothstep(0.06, 0.035, length(sd));
        c += mix(vec3(0.0), vec3(1.0, 0.8, 0.5) * 0.25, day) * exp(-length(sd) * 6.0);
        if (el < 0.0) {
            float t = clamp(-el / 0.13, 0.0, 1.0);
            vec3 sea = mix(mix(vec3(0.01, 0.03, 0.06), vec3(0.16, 0.48, 0.66), day), mix(vec3(0.02, 0.05, 0.08), vec3(0.20, 0.62, 0.66), day), t);
            float glint = step(0.985, hash12(floor(vec2(az * 220.0, el * 900.0 + uTime * 0.7)))) * mix(0.3, 1.0, day);
            sea += glint * vec3(0.9) * smoothstep(0.4, 0.0, abs(az - 0.45));
            float shore = -0.13 + 0.008 * sin(uTime * 0.5 + az * 6.0);
            vec3 sand = mix(vec3(0.05, 0.045, 0.04), vec3(0.86, 0.76, 0.58), day);
            c = el > shore ? sea : sand * (1.0 + 0.06 * vnoise(vec3(az * 30.0, el * 60.0, 0.0)));
            c = mix(c, mix(vec3(0.15), vec3(0.95), day), smoothstep(0.012, 0.0, abs(el - shore - 0.004)) * 0.8);
        }
        return c;
    }
    vec3 ground = v == 4 ? mix(vec3(0.05, 0.06, 0.09), vec3(0.88, 0.91, 0.95), day) : mix(vec3(0.01, 0.02, 0.01), vec3(0.28, 0.48, 0.18), day);
    if (v == 4) c = mix(c, mix(vec3(0.04, 0.05, 0.08), vec3(0.70, 0.74, 0.80), day), 0.6);       // overcast
    // distant hills, then a row of trees (pines in the snow, round crowns in the garden, pink blossom)
    float hill = 0.03 + 0.04 * vnoise(vec3(az * 2.0, 0.0, 1.0));
    if (el < hill) c = mix(ground, mix(c, ground, 0.5), smoothstep(-0.02, hill, el)) * (v == 4 ? 1.0 : 0.85);
    float x = az * 7.0;
    float id = floor(x), f = fract(x) - 0.5;
    float top = 0.12 + 0.12 * hash12(vec2(id, 3.0));
    if (v == 4) {
        float w = (top - el) * 0.9;
        if (el > -0.02 && abs(f) < w) {
            float snowy = step(0.5, fract((top - el) * 18.0)) * 0.5 + 0.2;
            c = mix(mix(vec3(0.01, 0.02, 0.02), vec3(0.10, 0.20, 0.16), day), ground, snowy);
        }
        // falling snow
        float flake = step(0.993, hash12(floor(vec2(az * 90.0, el * 90.0 + uTime * 0.6))));
        c += flake * mix(0.25, 0.9, day);
    } else {
        vec2 q = vec2(f * 1.4, (el - top + 0.06) * 6.0);
        float crown = length(q) + 0.25 * vnoise(vec3(az * 30.0, el * 30.0, id));
        float trunk = step(abs(f), 0.04) * step(-0.01, el) * step(el, top - 0.1);
        vec3 leaf = v == 5 ? mix(vec3(0.06, 0.03, 0.04), vec3(0.96, 0.66, 0.76), day) : mix(vec3(0.01, 0.02, 0.01), vec3(0.18, 0.38, 0.14), day);
        leaf *= mix(0.85, 1.1, vnoise(vec3(az * 40.0, el * 40.0, 1.0)));
        if (trunk > 0.5) c = mix(vec3(0.01), vec3(0.22, 0.15, 0.10), day);
        if (crown < 0.5) c = leaf;
        if (v == 5) {
            float petal = step(0.994, hash12(floor(vec2(az * 80.0 + uTime * 0.2, el * 80.0 + uTime * 0.4))));
            c = mix(c, vec3(1.0, 0.75, 0.82) * mix(0.2, 1.0, day), petal);
        }
    }
    return c;
}

// Wood grain for stand surfaces: rings along the board's long axis (the larger of x / z on a face).
float woodGrain(vec3 p, vec3 n) {
    vec3 q = abs(n.y) > 0.5 ? p.xzy : (abs(n.x) > 0.5 ? p.zyx : p.xyz);
    float g = vnoise(vec3(q.x * 0.05, q.y * 0.9, q.z * 0.9)) * 0.7 + vnoise(vec3(q.x * 0.2, q.y * 3.0, 1.7)) * 0.3;
    return mix(0.85, 1.12, g);
}

void main() {
    vec4 tex = uHasTexture > 0.5 ? texture(uAlbedo, vUv) : vec4(1.0);
    vec3 albedo = toLinear(tex.rgb) * uBaseColor.rgb;
    float alpha = tex.a * uBaseColor.a;
    int kind = int(uKind + 0.5);
    vec3 p = vWorld;
    vec3 N = normalize(vNormal);
    vec3 V = normalize(uCamPos.xyz - p);
    if (dot(N, V) < 0.0 && kind != 12) N = -N;
    float fw = length(fwidth(p));
    float ao = clamp(vColor.r, 0.0, 1.0);
    if (vColor.a < 0.01) ao = 1.0;

    // ---- surface colour
    float rough = uRoughness;
    float metal = 0.0;
    if (kind == 1) albedo = uPaint;
    else if (kind == 2) albedo = uTrim;
    else if (kind == 3) { albedo = uBrass > 0.5 ? vec3(0.95, 0.68, 0.28) : vec3(0.60, 0.61, 0.63); metal = 1.0; rough = uBrass > 0.5 ? 0.22 : 0.3; }
    else if (kind == 7) albedo = floorPattern(p, fw);
    else if (kind == 8) albedo = wallPattern(p, N, fw);
    if (uGrain > 0.5 && (kind == 1 || kind == 2 || kind == 0)) albedo *= mix(1.0, woodGrain(p, N), 1.0 - smoothstep(0.4, 2.0, fw));
    if (kind == 11) {
        // wool rug: a soft woven texture and a darker border band
        vec2 q = p.xz;
        float edge = min(min(q.x - (uFoot.x + uFoot.y) * 0.5 + 110.0, (uFoot.x + uFoot.y) * 0.5 + 110.0 - q.x), min(q.y - 70.0, 230.0 - q.y));
        albedo *= mix(0.72, 1.0, smoothstep(9.0, 11.0, edge)) * mix(1.0, 0.82, smoothstep(14.0, 15.5, edge) * (1.0 - smoothstep(17.0, 18.5, edge)));
        albedo *= mix(0.93, 1.05, vnoise(vec3(q * 0.9, 0.0)));
    }

    // ---- light
    float day = uDay;
    vec3 sky = mix(vec3(0.034, 0.038, 0.052), vec3(0.50, 0.49, 0.46), day);
    vec3 bounce = mix(vec3(0.010, 0.010, 0.012), vec3(0.24, 0.20, 0.16), day);
    vec3 keyCol = vec3(1.0, 0.91, 0.78) * 1.25 * day;
    vec3 Lk = normalize(vec3(-0.45, 0.75, 0.5));
    vec3 diff = albedo * (1.0 - metal);
    vec3 F0 = mix(vec3(0.04), albedo, metal);

    float occ = ao;
    // the floor under and round the stand, the wall behind the tank and stand: soft contact shade
    if (kind == 7 || kind == 11) {
        float d = boxDist(p.xz, uFoot.xz, uFoot.yw);
        occ *= mix(0.35, 1.0, smoothstep(-4.0, 30.0, d));
    }
    if (kind == 8 && p.z < uRoomBox.z + 3.0) {
        float d = boxDist(p.xy, vec2(uFoot.x, FLOOR_Y), vec2(uFoot.y, uTankBox.y));
        occ *= mix(0.6, 1.0, smoothstep(-10.0, 45.0, d));
    }
    // the stand's own underside and recesses get less of the sky
    float shadowKey = 1.0;
    if (kind <= 6) shadowKey = mix(0.5, 1.0, smoothstep(FLOOR_Y, FLOOR_Y + 40.0, p.y));

    float ndl = max(dot(N, Lk), 0.0);
    vec3 col = keyCol * (diff * ndl + F0 * ggxSpec(N, V, Lk, max(rough, 0.12)) * ndl) * shadowKey * mix(0.6, 1.0, occ);
    col += mix(bounce, sky, N.y * 0.5 + 0.5) * diff * occ;

    // the tank's light: out of the open top (onto the wall above, the ceiling) and through the front glass
    vec3 tankCol = (uLightColor[0].rgb + uLightColor[1].rgb) * 0.5 * vec3(0.62, 0.86, 1.0);
    {
        vec3 q = vec3(clamp(p.x, 0.0, uTankBox.x), uTankBox.y, clamp(p.z, 0.0, uTankBox.z));
        vec3 d = q - p;
        float d2 = dot(d, d);
        vec3 L = d * inversesqrt(max(d2, 1.0));
        float up = max(-L.y, 0.0);                    // only what is above the tank sees its open top
        col += tankCol * diff * max(dot(N, L), 0.0) * up * 2600.0 / (d2 + 1600.0) * occ;
        q = vec3(clamp(p.x, 0.0, uTankBox.x), clamp(p.y, 0.0, uTankBox.y), uTankBox.z);
        d = q - p;
        d2 = dot(d, d);
        L = d * inversesqrt(max(d2, 1.0));
        float front = max(-L.z, 0.0);                 // only what is in front of the front glass
        col += tankCol * diff * max(dot(N, L), 0.0) * front * 900.0 / (d2 + 2500.0) * occ;
    }
    // the floor lamp
    if (uLampPos.w > 0.5) {
        vec3 d = uLampPos.xyz - p;
        float d2 = dot(d, d);
        vec3 L = d * inversesqrt(max(d2, 1.0));
        float down = kind == 9 ? 0.35 : 1.0;          // the drum shade throws most of its light down and out
        col += uLampCol * diff * max(dot(N, L), 0.0) * down * 3600.0 / (d2 + 900.0) * mix(0.7, 1.0, occ);
    }
    // the glow strip's light pooled on the floor in front of the stand
    if (uGlowStrip > 0.5 && (kind == 7 || kind == 11 || kind == 4 || kind == 1 || kind == 2)) {
        float d = boxDist(p.xz, vec2(uFoot.x + 1.0, uFoot.w - 1.0), vec2(uFoot.y - 1.0, uFoot.w + 1.0));
        float h = max(p.y - FLOOR_Y, 0.0);
        col += vec3(0.25, 0.62, 1.0) * albedo * exp(-max(d, 0.0) / 16.0) * exp(-h / 6.0) * 1.6;
    }
    // a soft reflection of the room in polished surfaces (gloss paint, metal)
    if (rough < 0.35 || metal > 0.5) {
        vec3 R = reflect(-V, N);
        float ndv = max(dot(N, V), 1e-3);
        vec3 env = mix(bounce * 1.4, sky * 1.2 + tankCol * 0.15, smoothstep(-0.2, 0.4, R.y));
        vec3 Fr = F0 + (max(vec3(1.0 - rough), F0) - F0) * pow(1.0 - ndv, 5.0);
        col += Fr * env * mix(0.5, 1.0, occ);
    }

    if (kind == 5) {
        if (uGlowOn < 0.5) discard;
        col = vec3(0.35, 0.78, 1.0) * 2.2;
    } else if (kind == 6) {
        // the sump window: dark glass with the blue-lit sump and its rising bubbles behind it
        float bub = step(0.93, hash12(floor(vec2(p.x * 0.8, p.y * 0.6 - uTime * 3.0))));
        col = vec3(0.01, 0.03, 0.05) + vec3(0.05, 0.25, 0.45) * (0.5 + 0.5 * smoothstep(FLOOR_Y + 10.0, FLOOR_Y + 50.0, p.y)) + bub * 0.12;
        col += pow(1.0 - max(dot(N, V), 0.0), 4.0) * sky;
    } else if (kind == 10) {
        // lamp shade: lit from inside in the evening, a warm fabric in the day
        float on = clamp(uLampPos.w * (1.0 - day * 0.85), 0.0, 1.0);
        col = mix(col, albedo * uLampCol * 0.8, on);
    } else if (kind == 12) {
        // leaves: the key shines through them a little
        col += diff * keyCol * 0.25 * max(dot(-N, Lk), 0.0);
    } else if (kind == 15) {
        // fire: flickering flames, hottest at the bottom
        float h = clamp((p.y - FLOOR_Y - 12.0) / 28.0, 0.0, 1.0);
        float flick = 0.75 + 0.25 * sin(uTime * 9.0 + p.x * 0.7) * sin(uTime * 5.3 + p.x * 0.3);
        col = mix(vec3(1.0, 0.75, 0.3), vec3(0.9, 0.25, 0.05), h) * 2.2 * flick * (1.0 - h * 0.6);
        alpha = 1.0;
    } else if (kind == 14) {
        // a window: the view outside, a little dimmer than real so it frames the tank, and a faint reflection
        col = outsideView(normalize(p - uCamPos.xyz), day) * 0.8;
        col += pow(1.0 - max(dot(N, V), 0.0), 4.0) * 0.08 * (sky + tankCol * 0.2);
    } else if (kind == 13) {
        col = col * 0.5 + pow(1.0 - max(dot(N, V), 0.0), 3.0) * (sky + tankCol * 0.1);
        alpha = clamp(alpha + 0.2 * pow(1.0 - max(dot(N, V), 0.0), 2.0), 0.0, 0.85);
    }
    col += uEmissive;

    // the room steps back: walls, floor and props a little muted and dimmer than the tank, more so far away
    if (kind >= 7 || kind == 0) {
        float far = smoothstep(150.0, 600.0, length(p.xz - vec2(uTankBox.x * 0.5, uTankBox.z * 0.5)));
        col = mix(col, vec3(luma(col)), 0.12 + 0.15 * far) * (0.92 - 0.12 * far);
    }
    // tonemap() adapts the frame to the tank lights' colour; the room keeps its own white balance
    col *= max(mix(vec3(1.0), lightTint(), 0.9 * (1.0 - uNight) * smoothstep(0.03, 0.25, lightIntensity())), vec3(0.2));
    // exposed for the tank, as in Tee's photos: the room sits darker than the lit reef (research 11 §10)
    col *= ROOM_EXPOSURE;
    fragColor = vec4(tonemap(col), alpha);
}

assets/shaders/shadow.frag:
#version 300 es
precision mediump float;
// Shadow-map depth pass (ShadowMap.kt): paired with static.vert / fish.vert while the Frame UBO's uViewProj holds the
// fixtures' orthographic projection. Depth only; the colour output is discarded (no colour attachment).
out vec4 fragColor;

void main() {
    fragColor = vec4(1.0);
}

assets/shaders/shafts.frag:
#version 300 es
#include "common.glsl"
#include "lighting.glsl"
// God rays under the two AI Prime fixtures: soft-edged additive quads (shafts.vert) in the live light colour,
// flickering with the surface (scrolling caustic noise), strength by quality tier (uShaftStrength). They fade
// toward the sand, near the camera (no hard quad edges in close-ups) and when seen from above, where a camera-facing
// sheet would read as a flat plane.

in vec2 vCoord;
in float vSeed;
in float vLight;
in vec3 vWorld;
in float vKind;

out vec4 fragColor;

void main() {
    int li = int(vLight + 0.5);
    if (vKind > 6.5) {
        // lens halo: a hot core and a wide soft bloom in the lamp's colour, so the fixtures read as lit (and their
        // colour shows what the lamps are doing: white daylight, blue actinics, dim moonlight)
        float r2 = dot(vec2(vCoord.x, vCoord.y * 2.0 - 1.0), vec2(vCoord.x, vCoord.y * 2.0 - 1.0));
        float g = exp(-r2 * 18.0) * 1.4 + exp(-r2 * 4.0) * 0.35;
        g *= 1.0 - smoothstep(0.7, 1.0, r2);
        vec3 c = uLightColor[li].rgb / max(uLightColor[li].w, 1e-3);
        fragColor = vec4(tonemap(c * 1.5), g * clamp(uLightColor[li].w * 3.0, 0.0, 1.0) * (0.6 + 0.4 * uShaftStrength));
        return;
    }
    if (vKind > 5.5) {
        // beam in the air: faint haze lit by the lamp, brightest near the lens and along the cone's axis
        float ac = 1.0 - abs(vCoord.x);
        float a = ac * ac * (1.0 - vCoord.y * 0.6) * 0.07 * uShaftStrength * uLightColor[li].w;
        fragColor = vec4(tonemap(uLightColor[li].rgb * 1.2), a);
        return;
    }
    float across = 1.0 - abs(vCoord.x);
    across = across * across * (3.0 - 2.0 * across);
    // scrolling noise along the shaft plus a slower surface flicker
    float n = texture(uCaustic, vec2(vCoord.x * 0.15 + vSeed, vCoord.y * 0.6 - uTime * 0.03)).r;
    float flicker = 0.75 + 0.25 * sin(uTime * (0.7 + vSeed) + vSeed * 31.0);
    // surface focus above this shaft (blurred caustic read, drifts like the floor caustics); High only, the cheaper
    // presets keep the plain flicker (the shafts are big blended quads, so every read is paid over a lot of pixels)
    if (uQuality >= 1.5) {
        vec2 su = (vWorld.xz + surfaceSlope(vWorld.xz) * 20.0) * uCausticScale * 0.45 + uTime * vec2(0.017, -0.012);
        flicker *= 0.6 + 0.4 * clamp(texture(uCaustic, su, 3.0).r * 28.0, 0.0, 2.5);
    } else flicker *= 0.9;
    float along = (1.0 - vCoord.y) * smoothstep(0.0, 0.08, vCoord.y + 0.02);
    vec3 toFrag = vWorld - uCamPos.xyz;
    float dist = length(toFrag);
    float nearFade = smoothstep(6.0, 28.0, dist);
    float topFade = 1.0 - smoothstep(0.55, 0.92, abs(toFrag.y) / max(dist, 1e-3));
    float a = 0.6 * uShaftStrength * uLightColor[li].w * along * across * (0.45 + n) * flicker * nearFade * topFade;
    vec3 col = uLightColor[li].rgb * 1.2;
    col = applyWater(col, vWorld);
    fragColor = vec4(tonemap(col), a);
}

assets/shaders/shafts.vert:
#version 300 es
#include "common.glsl"
// Light shafts (ARCHITECTURE §8.4 item 8): 6 vertical quads per fixture, billboarded about Y, fanning
// out with the 120 deg cone below the surface; index 6 is the beam through the air from the lens down to the water,
// index 7 a camera-facing glow halo on the lens.

layout(location = 0) in vec4 aCorner;   // x -1..1 across, y 0 (top) .. 1 (bottom), z quad index 0..7, w light index
layout(location = 1) in vec4 aShaft;    // x,z offset at the surface (cm), y width (cm), w seed

out vec2 vCoord;
out float vSeed;
out float vLight;
out vec3 vWorld;
out float vKind;

void main() {
    int li = int(aCorner.w + 0.5);
    vec3 lp = uLightPos[li].xyz;
    vKind = aCorner.z;
    vSeed = aShaft.w;
    vLight = float(li);
    vCoord = vec2(aCorner.x, aCorner.y);
    if (aCorner.z > 6.5) {
        // halo: a square facing the eye just under the lens
        vec3 right = vec3(uView[0][0], uView[1][0], uView[2][0]);
        vec3 up = vec3(uView[0][1], uView[1][1], uView[2][1]);
        vec3 c = lp - vec3(0.0, 1.2, 0.0);
        vec3 p = c + (right * aCorner.x + up * (aCorner.y * 2.0 - 1.0)) * 9.0 + normalize(uCamPos.xyz - c) * 2.0;
        vWorld = p;
        gl_Position = uViewProj * vec4(p, 1.0);
        return;
    }
    if (aCorner.z > 5.5) {
        // beam in the air: from the lens down to the water, widening with the 120 deg cone (billboarded about Y)
        float yb = mix(lp.y - 1.0, uWaterLevel, aCorner.y);
        vec3 cb = vec3(lp.x, yb, lp.z);
        vec3 tc = uCamPos.xyz - cb;
        vec3 rb = normalize(vec3(tc.z, 0.0, -tc.x) + vec3(1e-4, 0.0, 0.0));
        float wb = mix(6.0, 2.0 * 1.2 * (lp.y - uWaterLevel), aCorner.y);
        vec3 p = cb + rb * aCorner.x * wb * 0.5;
        vWorld = p;
        gl_Position = uViewProj * vec4(p, 1.0);
        return;
    }
    float depth = aCorner.y;
    float sand = uParams2.w;
    float y = mix(uWaterLevel, sand, depth);
    // spread outward with depth (cone), drift slowly
    vec2 off = aShaft.xz * (1.0 + depth * 1.6) + vec2(sin(uTime * 0.07 + aShaft.w * 6.0), cos(uTime * 0.05 + aShaft.w * 4.0)) * 2.0;
    // refraction at the moving surface tilts each shaft: offset grows with depth below the water line
    off += surfaceSlope(lp.xz + aShaft.xz) * (uWaterLevel - y) * 0.6;
    vec3 center = vec3(lp.x + off.x, y, clamp(lp.z + off.y, 1.0, uTank.z - 1.0));
    vec3 toCam = uCamPos.xyz - center;
    vec3 right = normalize(vec3(toCam.z, 0.0, -toCam.x) + vec3(1e-4, 0.0, 0.0));
    float w = aShaft.y * (1.0 + depth * 0.8);
    vec3 p = center + right * aCorner.x * w * 0.5;
    vWorld = p;
    gl_Position = uViewProj * vec4(p, 1.0);
}

assets/shaders/shelf.frag:
#version 300 es
#include "common.glsl"
#include "lighting.glsl"
// Supply shelf beside the tank (SupplyShelf.kt, docs/ASSETS.md §5.1, UI_STYLE.md "Supply shelf"). The shelf stands in
// the room, not in the water, so it has its own light rig instead of the AI Prime fixtures: a soft overhead key from
// the front left (shadowed by the board above and by the props, as soft analytic shadows), a cool fill from the
// front right, the warm LED pucks under each board, a faint spill from the lit tank on the left, and a room
// environment (ceiling, walls, floor and the key's softbox) reflected with roughness-aware Fresnel. Contact shadows
// and crease occlusion are analytic (uFoot*, the rack layout); props carry baked vertex AO in COLOR_0.r. Materials
// by uKind: plank and driftwood grain, prints (low specular, so labels stay legible), frosted sea glass, metal.
// The room dims at night; the pucks and the sign stay lit.

in vec3 vWorld;
in vec3 vNormal;
in vec2 vUv;
in vec4 vColor;

uniform sampler2D uAlbedo;
uniform vec4 uBaseColor;
uniform float uHasTexture;
uniform float uRoughness;
uniform vec3 uEmissive;       // linear, x the texture: the lit sign and pucks, the picked prop's highlight (SupplyShelfScene)
uniform float uAlphaCutoff;
uniform float uKind;          // SupplyShelfScene.KIND_*: 0 plain, 1 board, 2 driftwood, 3 print, 4 sea glass, 5 backdrop, 6 lamp, 7 metal
uniform float uSelf;          // footprint index of the prop being drawn, -1 for the rack
uniform vec4 uFoot[28];       // per prop (rows feed, care, tools; slot order): centre x, centre z, half width, half depth (cm)
uniform vec4 uFootY[28];      // per prop: base y, top y (both lifted with the pick), lift 0..1, unused

out vec4 fragColor;

// SupplyShelfLayout / supplies.py
const float X0 = 134.0;
const float X1 = 236.0;
const float Z0 = 2.0;
const float Z1 = 24.0;
const float SLOT_X0 = 136.4;
const float SLOT_X1 = 233.6;

// light rig: unit directions toward each light, linear radiance
const vec3 KEY_DIR = vec3(-0.3506, 0.5009, 0.7913);
const vec3 KEY_X = vec3(0.9143, 0.0, 0.4051);     // softbox frame (KEY_X, KEY_Y, KEY_DIR)
const vec3 KEY_Y = vec3(0.2029, 0.8655, -0.4579);
const vec3 KEY_COL = vec3(1.0, 0.95, 0.87) * 0.78;
const vec3 FILL_DIR = vec3(0.5507, 0.1502, 0.8211);
const vec3 FILL_COL = vec3(0.80, 0.88, 1.0) * 0.20;
const vec3 LED_COL = vec3(1.0, 0.72, 0.42) * 70.0;

// Underside (y) of the board above height y; the pucks hang under the top three.
float undersideAbove(float y) {
    if (y < -5.6) return -5.6;
    if (y < 15.4) return 15.4;
    if (y < 34.4) return 34.4;
    if (y < 52.4) return 52.4;
    return 1e4;
}

// Top (y) of the board under height y (inside the rack).
float boardBelow(float y) {
    if (y >= 52.4) return 54.4;
    if (y >= 35.9) return 36.4;
    if (y >= 16.9) return 17.4;
    return -3.6;
}

// Key light past the board above: the ray toward the light must leave the bay through the open front (or an open
// end) before it reaches the underside; the penumbra widens with the distance to the board.
float boardShadow(vec3 p) {
    float yu = undersideAbove(p.y + 0.05);
    if (yu > 1000.0) return 1.0;
    float dy = yu - p.y;
    vec2 hit = p.xz + KEY_DIR.xz * (dy / KEY_DIR.y);
    float pen = 0.4 + 0.16 * dy;
    float front = smoothstep(Z1 - pen, Z1 + pen, hit.y);
    float end = 1.0 - smoothstep(X0 - pen, X0 + pen, hit.x) * (1.0 - smoothstep(X1 - pen, X1 + pen, hit.x));
    return max(front, end);
}

// Soft key shadows of the neighbouring props (each a box silhouette in its centre plane) and the contact darkening
// round their feet. Only the props in this row's slot and the slots either side are tested.
void propTerms(vec3 p, out float keyVis, out float contact) {
    keyVis = 1.0;
    contact = 1.0;
    int row = p.y >= 35.9 ? 0 : (p.y >= 16.9 ? 1 : 2);
    int base = row == 0 ? 0 : (row == 1 ? 13 : 23);
    int count = row == 0 ? 13 : (row == 1 ? 10 : 5);
    float pitch = (SLOT_X1 - SLOT_X0) / float(count);
    int slot = int(floor((p.x - SLOT_X0) / pitch));
    int own = int(floor(uSelf + 0.5));
    for (int k = -1; k <= 1; k++) {
        int j = slot + k;
        if (j < 0 || j >= count) continue;
        int i = base + j;
        if (i == own) continue;
        vec4 f = uFoot[i];
        vec4 fy = uFootY[i];
        if (f.z <= 0.0) continue;
        float t = (f.y - p.z) / KEY_DIR.z;
        if (t > 0.0) {
            vec2 q = p.xy + KEY_DIR.xy * t;
            float pen = 0.25 + 0.09 * t;
            float sx = 1.0 - smoothstep(f.z * 0.85 - pen, f.z * 0.85 + pen, abs(q.x - f.x));
            float sy = smoothstep(fy.x - pen, fy.x + pen, q.y) * (1.0 - smoothstep(fy.y - pen, fy.y + pen, q.y));
            keyVis = min(keyVis, 1.0 - 0.88 * sx * sy);
        }
        vec2 d = abs(p.xz - f.xy) - f.zw;
        float dist = length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
        float near = exp(-max(dist, 0.0) * 0.9) * exp(-max(p.y - fy.x, 0.0) * 0.7);
        contact = min(contact, 1.0 - 0.7 * near * (1.0 - 0.7 * fy.z));
    }
}

// Crease occlusion inside the rack: deep in a bay sees less of the room, and the corners where the boards, the back
// panel and the uprights meet are darker (weighted by the normal, so a face is not darkened by its own plane).
float bayOcc(vec3 p, vec3 N) {
    if (p.x < X0 || p.x > X1 || p.z > Z1 + 0.5 || p.y > 52.4 || p.y < -5.6) return 1.0;
    float depth = clamp((p.z - Z0) / (Z1 - Z0), 0.0, 1.0);
    float o = mix(0.6, 1.0, sqrt(depth));
    vec3 a = 1.0 - abs(N);
    float yb = boardBelow(p.y), yu = undersideAbove(p.y + 0.05);
    o *= 1.0 - 0.4 * a.y * clamp(exp(-(p.y - yb) * 0.55) + exp(-(yu - p.y) * 0.55), 0.0, 1.0);
    o *= 1.0 - 0.4 * a.z * exp(-max(p.z - Z0 - 0.6, 0.0) * 0.55);
    o *= 1.0 - 0.3 * a.x * clamp(exp(-max(p.x - X0 - 2.4, 0.0) * 0.5) + exp(-max(X1 - 2.4 - p.x, 0.0) * 0.5), 0.0, 1.0);
    return o;
}

// The four warm LED pucks under the board above (supplies.py: x = X0 + 14 + 24.67 k, z = Z1 - 5), Lambert emitters
// facing down.
vec3 ledLight(vec3 p, vec3 N) {
    float yu = undersideAbove(p.y + 0.05);
    if (yu < 15.0 || yu > 60.0) return vec3(0.0);
    float e = 0.0;
    for (int k = 0; k < 4; k++) {
        vec3 d = vec3(148.0 + 24.667 * float(k), yu - 0.4, 19.0) - p;
        float d2 = dot(d, d);
        vec3 L = d * inversesqrt(d2);
        e += max(dot(N, L), 0.0) * max(L.y, 0.0) / (d2 + 8.0);
    }
    return LED_COL * e;
}

// The room as seen in a reflection: floor, walls, ceiling, the key's softbox and the lit tank on the left.
vec3 roomEnv(vec3 R, float rough) {
    vec3 c = mix(vec3(0.16, 0.15, 0.14), vec3(0.36, 0.35, 0.34), smoothstep(-0.1, 0.8, R.y));
    c = mix(vec3(0.045, 0.036, 0.03), c, smoothstep(-0.4, -0.02, R.y));
    float w = dot(R, KEY_DIR);
    vec2 uv = vec2(dot(R, KEY_X), dot(R, KEY_Y)) / max(w, 0.1);
    float e = 0.03 + rough * 0.7;
    float box = (1.0 - smoothstep(0.42 - e, 0.42 + e, abs(uv.x))) * (1.0 - smoothstep(0.3 - e, 0.3 + e, abs(uv.y)));
    c += KEY_COL * (box * step(0.0, w) * 5.0 / (1.0 + rough * 5.0));
    c += lightTint() * (lightIntensity() * 0.45 * smoothstep(0.35, 0.95, -R.x));
    return c;
}

void main() {
    vec4 tex = uHasTexture > 0.5 ? texture(uAlbedo, vUv) : vec4(1.0);
    vec3 albedo = toLinear(tex.rgb) * uBaseColor.rgb;
    float alpha = tex.a * uBaseColor.a;
    if (uAlphaCutoff > 0.0 && alpha < uAlphaCutoff) discard;
    vec3 p = vWorld;
    vec3 N = normalize(vNormal);
    vec3 V = normalize(uCamPos.xyz - p);
    if (dot(N, V) < 0.0) N = -N;
    int kind = int(uKind + 0.5);

    // ---- material: procedural detail (no textures), roughness, specular / reflection weights ----
    float rough = uRoughness;
    float specK = 1.0;
    float envK = 1.0;
    float wrap = 0.0;
    float metal = 0.0;
    float h = 0.0;                                     // bump height (cm)
    float fp = length(fwidth(p));                      // cm per pixel: fine detail fades out with distance
    float fine = 1.0 - smoothstep(0.03, 0.12, fp);
    if (kind == 1) {
        // planks: growth rings across the board, streaming along x, and fine fibres
        float warp = fbm3(vec3(p.x * 0.035, p.y * 0.3, p.z * 0.3));
        float ring = 0.5 + 0.5 * sin((p.z * 0.8 + p.y * 1.4 + warp * 9.0) * 3.1);
        float fib = mix(0.5, vnoise(vec3(p.x * 0.5, p.y * 9.0, p.z * 9.0)), fine);
        float g = 0.6 * smoothstep(0.55, 1.0, ring) + 0.4 * fib;
        albedo *= mix(1.1, 0.66, g);
        rough = clamp(rough + (g - 0.5) * 0.2, 0.35, 1.0);
        h = (fib - 0.5) * 0.012 - smoothstep(0.8, 1.0, ring) * 0.008;
        specK = 0.7;
        envK = 0.6;
    } else if (kind == 2) {
        // driftwood: weathered fibres along the length (y), paler on the ridges
        float warp = fbm3(vec3(p.x * 0.4, p.y * 0.05, p.z * 0.4));
        float fib = 0.6 * vnoise(vec3(p.x * 5.0, p.y * 0.3, p.z * 5.0)) + 0.4 * mix(0.5, vnoise(vec3(p.x * 13.0, p.y * 0.9, p.z * 13.0)), fine);
        albedo *= mix(1.12, 0.7, smoothstep(0.25, 0.8, fib)) * mix(0.9, 1.06, warp);
        rough = 0.85;
        h = (fib - 0.5) * 0.05;
        specK = 0.5;
        envK = 0.4;
    } else if (kind == 3) {
        // printed labels: satin, and never a mirror (the print must stay legible)
        rough = max(rough, 0.5);
        specK = 0.3;
        envK = 0.3;
    } else if (kind == 4) {
        // frosted sea glass: light scatters through it (wrapped diffuse), a soft sheen
        rough = 0.32;
        wrap = 0.5;
        envK = 1.2;
    } else if (kind == 5) {
        // the painted back panel: matte, a faint brush texture
        rough = 0.9;
        h = (vnoise(p * vec3(0.6, 2.5, 0.6)) - 0.5) * 0.006 * fine;
        specK = 0.2;
        envK = 0.2;
    } else if (kind == 7) {
        metal = 1.0;
        rough = max(rough, 0.25);
    }
    if (uQuality >= 0.5 && (kind == 1 || kind == 2 || kind == 5)) N = bumpH(N, p, h * (1.0 - smoothstep(0.08, 0.3, fp)));

    // ---- visibility ----
    float keyVis, contact;
    propTerms(p, keyVis, contact);
    keyVis *= boardShadow(p);
    float occ = clamp(vColor.r, 0.0, 1.0) * bayOcc(p, N) * contact;

    // ---- the room rig ----
    float day = smoothstep(0.03, 0.5, lightIntensity());
    float room = uNight > 0.5 ? 0.28 : mix(0.6, 1.0, day);
    vec3 roomTint = uNight > 0.5 ? vec3(0.72, 0.84, 1.0) : vec3(1.0);
    vec3 diff = albedo * (1.0 - metal);
    vec3 F0 = mix(vec3(0.04), albedo, metal);
    float ndv = max(dot(N, V), 1e-3);

    float ndk = dot(N, KEY_DIR);
    vec3 Hk = normalize(V + KEY_DIR);
    vec3 Fk = F0 + (1.0 - F0) * pow(clamp(1.0 - dot(Hk, V), 0.0, 1.0), 5.0);
    vec3 key = KEY_COL * keyVis * (diff * max((ndk + wrap) / (1.0 + wrap), 0.0)
        + Fk * (ggxSpec(N, V, KEY_DIR, max(rough, 0.18)) * max(ndk, 0.0) * specK));

    float ndf = dot(N, FILL_DIR);
    vec3 fill = FILL_COL * (0.5 + 0.5 * occ) * (diff * max((ndf + 0.3 + wrap) / (1.3 + wrap), 0.0)
        + F0 * (ggxSpec(N, V, FILL_DIR, max(rough, 0.25)) * max(ndf, 0.0) * specK));

    vec3 amb = mix(vec3(0.05, 0.045, 0.04), vec3(0.15, 0.15, 0.16), N.y * 0.5 + 0.5) * diff * occ;

    vec3 R = reflect(-V, N);
    vec3 Fr = F0 + (max(vec3(1.0 - rough), F0) - F0) * pow(clamp(1.0 - ndv, 0.0, 1.0), 5.0);
    vec3 env = roomEnv(R, rough) * Fr * (envK * clamp(occ * 1.3, 0.0, 1.0));

    vec3 col = (key + fill + amb + env) * room * roomTint;
    // practical lights: the pucks under the board above (shaded a little by the props' feet) and the tank's spill
    col += ledLight(p, N) * (diff * (0.5 + 0.5 * contact) + F0 * (specK * 0.5));
    vec3 ts = vec3(118.0, 34.0, 16.0) - p;
    float td2 = dot(ts, ts);
    col += lightTint() * (lightIntensity() * 0.9 + 0.03) * (max(dot(N, ts * inversesqrt(td2)) * 0.8 + 0.2, 0.0) * 450.0 / (td2 + 1400.0)) * diff * occ;
    col += uEmissive * toLinear(tex.rgb);

    // the same water / grade path as the tank, but the room keeps its own white balance (tonemap() adapts the frame
    // to the AI Prime colour; undo that here so wood stays wood under a blue daylight)
    col = applyWater(col, p);
    col *= max(mix(vec3(1.0), lightTint(), 0.6 * (1.0 - uNight) * smoothstep(0.03, 0.25, lightIntensity())), vec3(0.2));
    fragColor = vec4(tonemap(col), alpha);
}

assets/shaders/snow.frag:
#version 300 es
#include "common.glsl"
#include "lighting.glsl"
// Marine snow flake: soft disc lit by the fixtures, with a forward-scatter glint when the flake sits between the
// camera and a light (it sparkles in the beams), then water absorption + fog like everything else.

in float vAlpha;
in float vSeed;
in vec3 vWorld;

out vec4 fragColor;

void main() {
    vec2 c = gl_PointCoord * 2.0 - 1.0;
    float r2 = dot(c, c);
    if (r2 > 1.0) discard;
    float soft = 1.0 - smoothstep(0.2, 1.0, r2);
    vec3 V = normalize(uCamPos.xyz - vWorld);
    vec3 L0;
    vec3 L1;
    vec3 rad = fixtureLight(0, vWorld, L0);
    vec3 rad1 = fixtureLight(1, vWorld, L1);
    float g0 = pow(max(dot(-V, L0), 0.0), 8.0);
    float g1 = pow(max(dot(-V, L1), 0.0), 8.0);
    vec3 col = vec3(0.75, 0.8, 0.78) * ((rad + rad1) * 0.8 + hemiAmbient(vec3(0.0, 1.0, 0.0)) * 1.5)
             + (rad * g0 + rad1 * g1) * 2.5;
    col = applyWater(col, vWorld);
    float a = vAlpha * soft * mix(0.22, 0.38, vSeed) * mix(1.0, 0.45, uNight);
    fragColor = vec4(tonemap(col), a);
}

assets/shaders/snow.vert:
#version 300 es
#include "common.glsl"
// Marine snow: drifting particulate animated entirely on the GPU (no vertex buffer; position from gl_VertexID and
// time), so it costs no CPU per frame. Flakes sink slowly, wander with the flow and wrap from the sand back to the
// surface. Size is a world size (cm) projected to pixels; sub-pixel flakes fade instead of shrinking below 1 px.

uniform float uViewportH;

out float vAlpha;
out float vSeed;
out vec3 vWorld;

void main() {
    float id = float(gl_VertexID);
    float hx = hash12(vec2(id, 1.7));
    float hy = hash12(vec2(id * 1.31, 9.3));
    float hz = hash12(vec2(id * 0.73, 4.1));
    float hs = hash12(vec2(id * 2.17, 7.7));
    float sand = uParams2.w;
    vec3 box = vec3(uTank.x - 2.0, uWaterLevel - sand - 1.5, uTank.z - 2.0);
    float sink = mix(0.25, 0.9, hs);                         // cm/s
    float y = fract(hy - uTime * sink / box.y);
    vec3 p = vec3(1.0 + hx * box.x, sand + 0.75 + y * box.y, 1.0 + hz * box.z);
    // slow wander with the flow (bigger near the top where the return pump pushes)
    float w = 0.6 + 0.8 * y;
    p.x += sin(uTime * 0.21 + id * 0.37) * 1.8 * w * uFlowStrength;
    p.z += cos(uTime * 0.17 + id * 0.53) * 1.1 * w;
    p.y += sin(uTime * 0.5 + id) * 0.25;
    p.x = clamp(p.x, 0.5, uTank.x - 0.5);
    p.z = clamp(p.z, 0.5, uTank.z - 0.5);
    vec4 clip = uViewProj * vec4(p, 1.0);
    gl_Position = clip;
    float sizeCm = mix(0.05, 0.16, hash12(vec2(id, 3.3)));
    float px = sizeCm * uProj[1][1] * uViewportH * 0.5 / max(clip.w, 0.1);
    gl_PointSize = clamp(px, 1.0, 7.0);
    // fade at the wrap (sand / surface), very close to the lens, and for sub-pixel flakes
    vAlpha = smoothstep(0.0, 0.05, y) * smoothstep(1.0, 0.93, y) * smoothstep(1.5, 6.0, clip.w) * clamp(px * 1.5, 0.25, 1.0);
    vSeed = hs;
    vWorld = p;
}

assets/shaders/softcoral.frag:
#version 300 es
#include "common.glsl"
#include "lighting.glsl"
// Soft corals, mushrooms, macroalgae, algae cards (ARCHITECTURE §8.4 item 2): wrap diffuse, subsurface
// back-light by thickness (COLOR_0.r), rim, bleaching/browning, fluorescence driven by the blue fraction.
// CARD: alpha-tested hair-algae cards that grow root->tip (COLOR_0.b) with uAlgaeBloom.

in vec3 vWorld;
in vec3 vNormal;
in vec2 vUv;
in vec4 vColor;

uniform sampler2D uAlbedo;
uniform vec4 uBaseColor;
uniform float uHasTexture;
uniform float uRoughness;
uniform vec3 uEmissive;     // material fluorescence colour
uniform float uExtension;
uniform float uBleach;
uniform vec3 uBleachTint;  // what bleached tissue fades to (per species)
uniform float uDead;       // 1 - living tissue: receding colony
uniform float uBrown;
uniform float uAlphaCutoff;
uniform vec3 uSssColor;

out vec4 fragColor;

void main() {
    vec4 tex = uHasTexture > 0.5 ? texture(uAlbedo, vUv) : vec4(1.0);
    vec3 albedo = toLinear(tex.rgb) * uBaseColor.rgb;
    float alpha = tex.a * uBaseColor.a;
#ifdef CARD
    if (uAlgaeBloom < 0.02 || vColor.b > uAlgaeBloom * 1.25) discard;
#endif
    if (uAlphaCutoff > 0.0 && alpha < uAlphaCutoff) discard;
    albedo = mix(albedo, uBleachTint, clamp(uBleach, 0.0, 1.0));
    // receding: patches of a dying colony melt away (world-space noise), the edge of the living tissue goes dull
    // a stony coral's skeleton (COLOR_0.a < 0.5) stays where the tissue has gone: bare white limestone
    float bare = 0.0;
    if (uDead > 0.001) {
        float n = clamp((vnoise(vWorld * 0.45) * 0.7 + vnoise(vWorld * 1.7 + 5.0) * 0.3 - 0.5) * 2.4 + 0.5, 0.0, 1.0);
        if (n < uDead * 1.02) {
            if (vColor.a > 0.5) discard;
            bare = 1.0;
        } else albedo = mix(vec3(0.55, 0.5, 0.42), albedo, smoothstep(uDead, uDead + 0.12, n));
    }
    albedo = mix(albedo, vec3(0.195, 0.102, 0.042), clamp(uBrown, 0.0, 1.0) * 0.4);
    if (bare > 0.5) albedo = vec3(0.80, 0.78, 0.72) * (0.85 + 0.25 * vnoise(vWorld * 3.0));

    vec3 N = normalize(vNormal);
    vec3 V = normalize(uCamPos.xyz - vWorld);
    if (dot(N, V) < 0.0) N = -N;
    // tissue micro-relief (polyp pores, wrinkles) where the mesh is smooth, Medium+; fades with pixel footprint
#ifndef CARD
    if (uQuality >= 0.5) {
        float fp = length(fwidth(vWorld));
        float relief = (vnoise(vWorld * 2.6) - 0.5) * 0.09 * (1.0 - smoothstep(0.15, 0.6, fp));
        if (uQuality >= 1.5) relief += (vnoise(vWorld * 7.0 + 3.0) - 0.5) * 0.03 * (1.0 - smoothstep(0.05, 0.25, fp));
        N = bumpH(N, vWorld, relief);
    }
#endif
    // view-angle terms (sheen, rim) use the smooth normal, so the micro-relief does not sparkle white up close
    vec3 Ng = normalize(vNormal);
    if (dot(Ng, V) < 0.0) Ng = -Ng;
    vec3 col = shadeLit(albedo, N, V, vWorld, uRoughness, 1.0, 0.03, 1.0, 0.6);
#ifndef CARD
    // mucus sheen: soft corals and mushrooms read wet in the tank
    col += wetCoat(Ng, V, vWorld, 0.3, 0.35) * gShadow;
#endif
    float thickness = clamp(vColor.r, 0.0, 1.0) * gShadow;   // no back-light glow inside a shadow
    for (int i = 0; i < 2; i++) {
        vec3 L;
        vec3 rad = fixtureAt(i, L);
        float bl = clamp(dot(V, -L), 0.0, 1.0);
        col += rad * uSssColor * albedo * (bl * bl * bl) * thickness;
    }
    float ndv = max(dot(Ng, V), 0.0);
    col += pow(1.0 - ndv, 2.5) * 0.35 * (uLightColor[0].rgb + uLightColor[1].rgb) * 0.5 * albedo;
    // fluorescence: emissive scaled by blue light and extension (bleached tissue loses it)
    col += uEmissive * uBlueFraction * lightIntensity() * mix(0.4, 1.0, uExtension) * (1.0 - uBleach) * (1.0 - bare) * 0.8;
    col = applyWater(col, vWorld);
    fragColor = vec4(tonemap(col), 1.0);
}

assets/shaders/static.vert:
#version 300 es
#include "common.glsl"
// Static geometry: rock, sand, tank, equipment. With SOFTCORAL defined: soft-coral / macro / algae-card
// sway and extension (ARCHITECTURE §8.4 item 2). Coral COLOR_0: R thickness, G sway phase, B sway weight, A softness.

layout(location = 0) in vec3 aPos;
layout(location = 1) in vec3 aNormal;
layout(location = 2) in vec2 aUv;
layout(location = 3) in vec4 aColor;

uniform mat4 uModel;
#ifdef SOFTCORAL
uniform vec3 uBase;        // attachment point (world cm)
uniform float uHeight;     // colony height (cm)
uniform float uExtension;  // 0 retracted .. 1 open
uniform float uPhase;      // per-colony sway phase
uniform vec3 uSwayDir;     // unit, horizontal flow direction
uniform float uSwayAmp;    // cm at the tips (0.08 x height x flow; tree mode: 0.035 x height x flow)
uniform float uSwayMode;   // 0 legacy sway, 1 branching tree (treeSway in common.glsl; Kenya)
uniform vec4 uWake;        // tree mode: nearest fish (xyz world cm) and ripple strength (w 0..1)
#endif
#ifdef SAND
// Dynamic sand bed (SIMULATION §16, SandFx): r height offset (cm), g freshness, b detritus; xz / uSandExtent -> uv.
uniform sampler2D uSandMap;
uniform float uSandOn;
uniform vec2 uSandExtent;
#endif

out vec3 vWorld;
out vec3 vNormal;
out vec2 vUv;
out vec4 vColor;
#if defined(ROCK) || defined(GSPMAT)
out vec3 vObj;   // object-space position: rock.frag pins its detail to the rock
#endif

void main() {
    vec4 w = uModel * vec4(aPos, 1.0);
    vec3 p = w.xyz;
#ifdef SOFTCORAL
    // COLOR_0.a: how soft the tissue is (1 soft coral; 0 a stony coral's skeleton, which neither shrinks nor sways)
    float soft = aColor.a;
    // extension: shrink toward the base (retracted colonies are ~55% size)
    p = uBase + (p - uBase) * (1.0 - soft * (1.0 - mix(0.55, 1.0, clamp(uExtension, 0.0, 1.0))));
    float h = clamp((p.y - uBase.y) / max(uHeight, 1.0), 0.0, 1.0);
    if (uSwayMode > 0.5) {
        p += soft * treeSway(p, uBase, uHeight, uPhase, uSwayDir, uSwayAmp, uWake);
    } else {
        float weight = max(aColor.b, h * 0.5) * soft;
        float ph = uTime * 1.3 + p.y * 0.15 + uPhase + aColor.g * 6.2831;
        p += uSwayDir * sin(ph) * uSwayAmp * weight;
        p.y -= 0.15 * uSwayAmp * weight * (0.5 + 0.5 * sin(ph * 1.7));
    }
#endif
#ifdef SAND
    // pits, mounds and trails: lift the top surface only (the skirt sits at y = -0.5)
    if (uSandOn > 0.5 && p.y > 0.5) {
        vec2 suv = clamp(p.xz / max(uSandExtent, vec2(1.0)), 0.0, 1.0);
        p.y += textureLod(uSandMap, suv, 0.0).r;
    }
#endif
    vNormal = normalize(mat3(uModel) * aNormal);
#ifdef GSPMAT
    // the stolon mat is a skin about a millimetre thick over the rock it copies
    p += vNormal * 0.07;
#endif
    vWorld = p;
    vUv = aUv;
    vColor = aColor;
#if defined(ROCK) || defined(GSPMAT)
    vObj = aPos;
#endif
    gl_Position = uViewProj * vec4(p, 1.0);
}

assets/shaders/store.frag:
#version 300 es
#include "common.glsl"
#include "lighting.glsl"
// Fish store interior around the live display tank (StoreRoom.kt, tools/blender/store_rooms.py): a row of bays, each
// with a stand, a display tank under a hanging tank light and a ceiling panel over the aisle. The room has its own
// light rig, not the AI Prime fixtures: those lights repeat every uBay cm along x (so they follow the bays wherever
// the renderer draws them), a cool glow spills from every tank's water onto the stands and the floor, and a
// store-coloured hemisphere fills the rest. Kinds (StoreRoomScene.kindOf, from the material name): 0 paint,
// 1 floor tiles, 2 lamp / screen / neon (emissive), 3 glass, 4 tank water, 5 metal (gold, fixtures), 6 a tank's
// lamp (glows in its tank's light colour), 7 rising bubbles, 8 egg crate, 9 vertex-painted (people, fish, corals).
// uGlowCol is set per bay: the colour of that tank's light (core DisplayLight.glow), so a frag tank glows purple and
// throws a slow caustic shimmer onto its stand and the floor in front of it. Each store has its own floor: 11 sealed
// concrete (Frag Shack), 12 polished marble (Deep Reef). Outside (store_fronts.py, seen while walking in from the street):
// 10 sunlit paint, 13 the sky backdrop.

in vec3 vWorld;
in vec3 vNormal;
in vec2 vUv;
in vec4 vColor;

uniform sampler2D uAlbedo;
uniform vec4 uBaseColor;
uniform float uHasTexture;
uniform float uRoughness;
uniform vec3 uEmissive;
uniform float uAlphaCutoff;
uniform float uKind;
uniform float uBay;           // bay pitch (cm, StoreRoomLayout.BAY)
uniform vec3 uLampCol;        // the store's light colour (linear radiance of a tank light)
uniform vec3 uFillCol;        // hemisphere fill: x sky, the floor bounce is a darker share of it
uniform vec3 uGlowCol;        // this bay's tank light colour: its water, its lamp and the glow it spills
uniform float uRoomX;         // x of the live tank's centre: the bays (and their lights) repeat from it
uniform float uCeil;          // the store's ceiling height (world y): its aisle lights hang just under it
uniform float uFront;         // the front wall's inner face (world z): daylight comes in through its windows
// Soft contact shadows on the floor under the people and the pet (StoreRoomScene): world x, z, radius, strength.
uniform vec4 uShadows[12];
uniform float uShadowN;

out vec4 fragColor;


// A slow caustic ripple (two drifting wave sets): the light that comes out of a tank through its moving surface.
float shimmer(vec3 p) {
    float a = sin(p.x * 0.19 + uTime * 1.3) * sin(p.z * 0.16 - uTime * 1.05);
    float b = sin((p.x + p.z) * 0.11 - uTime * 0.7 + p.y * 0.05);
    return 0.72 + 0.28 * a * a * 2.0 + 0.12 * b;
}

// Bubbles rising up a column or a skimmer: round dots on a grid that scrolls up, each column at its own speed.
float bubbles(vec3 p) {
    vec2 q = vec2(p.x + p.z * 0.7, p.y);
    float col = floor(q.x / 1.1);
    float speed = 9.0 + 6.0 * hash12(vec2(col, 3.1));
    vec2 g = vec2(q.x / 1.1, (q.y - uTime * speed) / 1.6 + hash12(vec2(col, 7.7)) * 4.0);
    vec2 f = fract(g) - 0.5;
    float on = step(0.45, hash12(floor(g) + vec2(0.0, 17.0)));
    float r = 0.18 + 0.16 * hash12(floor(g));
    return on * (1.0 - smoothstep(r - 0.06, r, length(f)));
}

// One bay's lights at bay centre x [bx]: the tank light (down, over the tank) and the ceiling panel over the aisle.
vec3 bayLight(vec3 p, vec3 N, vec3 V, float bx, vec3 diff, vec3 F0, float rough, float shim) {
    vec3 c = vec3(0.0);
    // tank light: a 104 x 30 cm panel at y 117.4, over the tank, facing down
    vec3 q = vec3(clamp(p.x, bx - 52.0, bx + 52.0), 117.4, clamp(p.z, 8.0, 38.0));
    vec3 d = q - p;
    float d2 = dot(d, d);
    vec3 L = d * inversesqrt(d2);
    float down = max(L.y, 0.0);   // the panel only lights what is below it
    float ndl = max(dot(N, L), 0.0);
    c += uLampCol * (down * 9000.0 / (d2 + 900.0)) * (diff * ndl + F0 * ggxSpec(N, V, L, max(rough, 0.2)) * ndl);
    // ceiling light over the aisle (80 x 60 cm just under the ceiling, z 140..200)
    q = vec3(clamp(p.x, bx - 40.0, bx + 40.0), uCeil - 1.0, clamp(p.z, 140.0, 200.0));
    d = q - p;
    d2 = dot(d, d);
    L = d * inversesqrt(d2);
    ndl = max(dot(N, L), 0.0);
    c += uLampCol * (max(L.y, 0.0) * 26000.0 / (d2 + 4000.0)) * (diff * ndl + F0 * ggxSpec(N, V, L, max(rough, 0.3)) * ndl * 0.5);
    // the tank's water glow, from its front face, rippling like light through a moving surface
    vec3 t = vec3(clamp(p.x, bx - 60.0, bx + 60.0), 20.0, 46.0) - p;
    float t2 = dot(t, t);
    vec3 Lt = t * inversesqrt(t2);
    c += uGlowCol * (max(dot(N, Lt), 0.0) * 1800.0 / (t2 + 2500.0)) * diff * shim;
    return c;
}

// Baked-looking soft occlusion, all analytic (no extra pass): the floor darkens into the back wall and under the
// stands, the walls into the floor and ceiling, and a soft blob lies under each person.
float roomAO(vec3 p, vec3 N) {
    float floorish = smoothstep(0.5, 0.9, N.y) * (1.0 - smoothstep(-80.0, -70.0, p.y));
    // floor: the shade of the stands (their fronts end ≤ 67 cm out) and of the back wall
    float a = 1.0 - floorish * 0.45 * (1.0 - smoothstep(30.0, 95.0, p.z));
    // walls and fronts: dark where they meet the floor, a little under the ceiling
    float wallish = 1.0 - abs(N.y);
    a *= 1.0 - wallish * (0.35 * (1.0 - smoothstep(-82.0, -40.0, p.y)) + 0.25 * smoothstep(uCeil - 60.0, uCeil, p.y));
    // contact shadows under people (skipped on Low picture quality, which can be switched to while running)
    if (floorish > 0.01 && uQuality > 0.5) {
        int n = int(uShadowN + 0.5);
        for (int i = 0; i < 12; i++) {
            if (i >= n) break;
            vec4 s = uShadows[i];
            float d = length(p.xz - s.xy);
            a *= 1.0 - floorish * s.w * (1.0 - smoothstep(s.z * 0.25, s.z * 1.5, d));
        }
    }
    return a;
}

// The fog into the store's air, the white balance and the tonemap, shared by every lit surface.
vec4 finish(vec3 col, vec3 p, float alpha) {
    // far bays fade into the store's air
    float dist = length(uCamPos.xyz - p);
    col = mix(col, uFillCol * 0.4, smoothstep(450.0, 1100.0, dist));
    // tonemap() adapts the frame to the tank lights' colour; the room keeps its own white balance
    col *= max(mix(vec3(1.0), lightTint(), 0.6 * (1.0 - uNight) * smoothstep(0.03, 0.25, lightIntensity())), vec3(0.2));
    return vec4(tonemap(col), alpha);
}

void main() {
    vec4 tex = uHasTexture > 0.5 ? texture(uAlbedo, vUv) : vec4(1.0);
    vec3 albedo = toLinear(tex.rgb) * uBaseColor.rgb;
    float alpha = tex.a * uBaseColor.a;
    if (uAlphaCutoff > 0.0 && alpha < uAlphaCutoff) discard;
    vec3 p = vWorld;
    vec3 N = normalize(vNormal);
    vec3 V = normalize(uCamPos.xyz - p);
    if (dot(N, V) < 0.0) N = -N;
    int kind = int(uKind + 0.5);

    if (kind == 2) {
        // lamps, screens and neon: their own light, a little body colour so they are never flat
        fragColor = vec4(tonemap(uEmissive + albedo * 0.15), alpha);
        return;
    }
    if (kind == 6) {
        // a display tank's lamp: as bright as its emissive, in its tank's light colour
        float e = dot(uEmissive, vec3(0.2126, 0.7152, 0.0722));
        vec3 hue = uGlowCol / max(max(uGlowCol.r, max(uGlowCol.g, uGlowCol.b)), 1e-3);
        fragColor = vec4(tonemap(e * mix(vec3(1.0), hue, 0.7) + albedo * 0.1), alpha);
        return;
    }
    if (kind == 7) {
        // bubbles: only the dots are drawn, bright where the light catches them
        float b = bubbles(p);
        if (b < 0.02) discard;
        fragColor = vec4(tonemap(mix(uFillCol * 2.0, vec3(1.0), 0.6) + uGlowCol), b * 0.75);
        return;
    }
    if (kind == 13) {
        // the sky behind the roofs: a soft blue gradient, paler at the horizon (night: deep blue)
        float h = clamp((p.y + 82.0) / 900.0, 0.0, 1.0);
        vec3 day = mix(vec3(0.62, 0.78, 0.95), vec3(0.22, 0.45, 0.85), h);
        vec3 night = mix(vec3(0.05, 0.07, 0.14), vec3(0.01, 0.015, 0.04), h);
        fragColor = vec4(tonemap(mix(day, night, uNight)), 1.0);
        return;
    }
    if (kind == 10) {
        // outside: sun and sky light (street lamps and lit signs are their own kind-2 glow)
        vec3 sunDir = normalize(vec3(0.35, 0.8, 0.5));
        vec3 sunCol = mix(vec3(2.6, 2.4, 2.1), vec3(0.05, 0.06, 0.1), uNight);
        vec3 skyCol = mix(vec3(0.55, 0.65, 0.8), vec3(0.04, 0.05, 0.09), uNight);
        float ndl = max(dot(N, sunDir), 0.0);
        vec3 o = albedo * (sunCol * ndl + skyCol * (0.55 + 0.45 * N.y)) + uEmissive;
        o += vec3(0.04) * pow(1.0 - max(dot(N, V), 0.0), 5.0) * skyCol;
        // a little haze far down the street
        o = mix(o, skyCol * 0.9, smoothstep(900.0, 2600.0, length(uCamPos.xyz - p)));
        fragColor = vec4(tonemap(o), alpha);
        return;
    }
    if (kind == 4) {
        // a stocked tank's water seen from the room: lit from above in its light's colour, rippling
        float lit = 0.25 + 0.75 * smoothstep(-80.0, 38.0, p.y);
        fragColor = finish((albedo * 0.35 + uGlowCol * 1.6) * lit * shimmer(p * 1.7) + uEmissive * 0.25, p, alpha);
        return;
    }
    if (kind == 3) {
        // glass: mostly reflection (no room lights: it only reflects)
        float ndv = max(dot(N, V), 1e-3);
        vec3 F0 = vec3(0.04);
        vec3 Fr = F0 + (max(vec3(1.0 - uRoughness), F0) - F0) * pow(1.0 - ndv, 5.0);
        alpha = clamp(alpha + 0.35 * pow(1.0 - ndv, 3.0), 0.0, 0.8);
        fragColor = finish(Fr * (uLampCol * 2.0 + uFillCol) + albedo * 0.05 + uEmissive, p, alpha);
        return;
    }
    if (kind == 9) albedo *= vColor.rgb;
    if (kind == 8) {
        // egg crate: a square grid of white plastic bars (1.3 cm cells) with the dark water showing through
        vec2 f = abs(fract(p.xz / 1.3) - 0.5);
        albedo *= mix(0.25, 1.0, step(0.36, max(f.x, f.y)));
    }
    float rough = uRoughness;
    float metal = kind == 5 ? 1.0 : 0.0;
    if (kind == 1) {
        // floor tiles: 40 cm squares, alternate tiles a shade apart, dark grout, a faint polish
        vec2 cell = floor(p.xz / 40.0);
        vec2 f = fract(p.xz / 40.0);
        float grout = step(0.985, max(f.x, f.y)) + step(max(f.x, f.y), 0.015);
        float alt = mod(cell.x + cell.y, 2.0);
        albedo *= mix(1.0, 0.86, alt) * mix(1.0, 0.55, clamp(grout, 0.0, 1.0)) * mix(0.94, 1.04, hash12(cell));
        rough = mix(0.25, 0.6, clamp(grout, 0.0, 1.0));
    }
    if (kind == 11) {
        // sealed concrete: big poured slabs with saw cuts, a mottled grey and a soft sheen
        vec2 f = fract(p.xz / 120.0);
        float cut = step(0.992, max(f.x, f.y));
        float mottle = hash12(floor(p.xz / 9.0)) * 0.5 + hash12(floor(p.xz / 31.0)) * 0.5;
        albedo *= mix(0.86, 1.08, mottle) * mix(1.0, 0.5, cut);
        rough = 0.5;
    }
    if (kind == 12) {
        // polished marble: wide slabs, soft veins, a mirror shine
        vec2 cell = floor(p.xz / 80.0);
        vec2 f = fract(p.xz / 80.0);
        float grout = step(0.995, max(f.x, f.y)) + step(max(f.x, f.y), 0.005);
        float vein = abs(sin((p.x + p.z * 0.6) * 0.08 + sin(p.z * 0.05 + hash12(cell) * 6.0) * 2.5));
        albedo *= mix(0.82, 1.0, smoothstep(0.0, 0.12, vein)) * mix(1.0, 0.6, clamp(grout, 0.0, 1.0));
        rough = 0.12;
    }
    vec3 diff = albedo * (1.0 - metal);
    vec3 F0 = mix(vec3(0.04), albedo, metal);

    // the two nearest bays' lights (the lights repeat every bay); the water ripple depends on p only
    float shim = shimmer(p);
    float n = floor((p.x - uRoomX) / uBay);
    vec3 col = bayLight(p, N, V, uRoomX + n * uBay, diff, F0, rough, shim) + bayLight(p, N, V, uRoomX + (n + 1.0) * uBay, diff, F0, rough, shim);
    float ao = roomAO(p, N);
    // daylight through the front windows and door, falling off into the store (none at night)
    float day = (1.0 - uNight) * smoothstep(uFront - 380.0, uFront, p.z);
    col += vec3(0.55, 0.62, 0.72) * day * (max(N.z, 0.0) * 0.8 + max(N.y, 0.0) * 0.5) * diff;
    // hemisphere fill with a warm bounce off the floor (soft, like light that has bounced round the room); people
    // wrap the light a little more so they read soft and round
    float wrap = kind == 9 ? 0.65 : 0.5;
    vec3 amb = mix(uFillCol * 0.45, uFillCol * 1.15, N.y * wrap + (1.0 - wrap)) * diff;
    amb += uLampCol * 0.06 * max(-N.y, 0.0) * diff;
    col = (col * mix(1.0, ao, 0.7) + amb * ao);
    // a soft reflection of the lit room in polished and metal surfaces
    vec3 R = reflect(-V, N);
    float ndv = max(dot(N, V), 1e-3);
    vec3 Fr = F0 + (max(vec3(1.0 - rough), F0) - F0) * pow(1.0 - ndv, 5.0);
    col += Fr * mix(uFillCol * 0.3, uLampCol * 3.0, smoothstep(0.0, 1.0, R.y)) * (kind == 1 ? 0.6 : 1.0);
    col += uEmissive;
    fragColor = finish(col, p, alpha);
}

assets/shaders/water.frag:
#version 300 es
#include "common.glsl"
#include "lighting.glsl"
// Water surface (ARCHITECTURE §8.4 item 8, SIMULATION §9.7 optics). Seen from below: Snell refraction
// (n 1.34 -> 1.0) shows the dark room and the AI Prime glow discs; above the critical angle
// asin(1/1.34) = 48.3 deg the surface is a total-internal-reflection mirror of the lit water. Schlick
// Fresnel F0 0.02 blends the two. Seen from above: reflection of the room over the transmitted scene.

in vec3 vWorld;
in vec3 vNormal;
in vec2 vUv;
in vec4 vColor;

uniform sampler2D uWaterN1;
uniform sampler2D uWaterN2;
uniform sampler2D uEnv;

out vec4 fragColor;

const float ETA_WATER = 1.34;
const vec3 ROOM = vec3(0.0032, 0.0048, 0.0103); // #0A0F1A linear

vec2 equirect(vec3 d) { return vec2(atan(d.z, d.x) / (2.0 * PI) + 0.5, acos(clamp(d.y, -1.0, 1.0)) / PI); }

void main() {
    // detail normals: two scrolling maps (cm/s speeds), 20 cm tiles, plus the simulated slope
    vec2 uv = vWorld.xz / 20.0;
    vec3 n1 = texture(uWaterN1, uv + uTime * vec2(1.5, 0.8) / 20.0).xyz * 2.0 - 1.0;
    vec3 n2 = texture(uWaterN2, uv * 1.3 + uTime * vec2(-1.0, 1.2) / 20.0).xyz * 2.0 - 1.0;
    vec2 slope = surfaceSlope(vWorld.xz);
    // swell and chop (common.glsl swell): the same waves that lift the vertices bend the normals and the caustics
    vec2 rip = -swell(vWorld.xz, 5).yz;
    vec3 N = normalize(vec3((n1.x + n2.x) * 0.12 - slope.x + rip.x, 1.0, (n1.y + n2.y) * 0.12 - slope.y + rip.y));

    vec3 I = normalize(vWorld - uCamPos.xyz);
    bool below = uCamPos.y < uWaterLevel;
    // where each fixture's cone meets the surface: microbubbles and surface film scatter a soft glowing pool that
    // shimmers with the ripples (Medium+)
    vec3 pool = vec3(0.0);
    if (uQuality >= 0.5) {
        float sh = texture(uCaustic, vWorld.xz * 0.05 + N.xz * 0.6 + uTime * vec2(0.015, -0.01)).r;
        for (int i = 0; i < 2; i++) {
            vec2 d = vWorld.xz - uLightPos[i].xz;
            pool += uLightColor[i].rgb * exp(-dot(d, d) / 450.0) * (0.05 + 0.6 * sh);
        }
    }
    // whitewater where the return splashes in (equipment.glb ReturnNozzle, back middle): churned froth that fades out
    // a few cm away, only while the pumps run
    vec2 fd = (vWorld.xz - vec2(73.0, 2.0)) * vec2(1.0, 1.6);
    float fr = exp(-dot(fd, fd) / 40.0) * clamp(uFlowStrength, 0.0, 1.0);
    float foam = 0.0;
    if (fr > 0.02) foam = fr * smoothstep(0.04, 0.3, texture(uCaustic, vWorld.xz * 0.12 + uTime * vec2(0.3, 0.45)).r + 0.3 * fr);
    vec3 foamCol = lightTint() * (0.15 + 0.85 * lightIntensity()) + uAmbientB.rgb;
    vec3 col;
    float alpha;
    if (below) {
        vec3 Nd = -N; // facing the camera (down)
        float cosI = clamp(dot(-I, Nd), 0.0, 1.0);
        vec3 T = refract(I, Nd, ETA_WATER);
        vec3 R = reflect(I, Nd);
        // reflected underwater scene approximation: lit water colour + the fixtures' reflected glow
        vec3 refl = uFog.rgb * 1.1 + (uLightColor[0].rgb + uLightColor[1].rgb) * 0.04;
        refl += uAmbientB.rgb * 0.5;
        // the mirror shimmers like the real tank seen through the front glass: a crinkled net of bright ripple
        // facets catching the lamps, two chop-warped reads of the caustic tile drifting against each other
        vec2 cuv = vWorld.xz * 0.045 + N.xz * 0.5;
        float ca = texture(uCaustic, cuv + uTime * vec2(0.035, 0.021)).r;
        float cb = texture(uCaustic, cuv * 1.7 - N.xz * 0.3 - uTime * vec2(0.026, -0.031)).r;
        float crinkle = smoothstep(0.03, 0.4, ca + cb);
        refl = refl * (0.7 + 0.5 * crinkle) + lightTint() * lightIntensity() * crinkle * crinkle * 0.5 * uRipple;
        if (dot(T, T) < 1e-4) {
            col = refl; // total internal reflection
        } else {
            // transmitted: the room above + glow discs of the two fixtures
            vec3 trans = ROOM + toLinear(texture(uEnv, equirect(T)).rgb) * 0.08;
            for (int i = 0; i < 2; i++) {
                vec3 L = normalize(uLightPos[i].xyz - vWorld);
                float d = max(dot(T, L), 0.0);
                trans += uLightColor[i].rgb * (pow(d, 120.0) * 6.0 + pow(d, 12.0) * 0.25);
                // glitter: tiny sharp highlights where the rippled surface points straight at a fixture
                trans += uLightColor[i].rgb * pow(d, 900.0) * 14.0 * uRipple;
            }
            // Fresnel at the water side, cosT from Snell
            float F = fresnelSchlick(cosI, 0.02);
            float cosT = sqrt(max(1.0 - ETA_WATER * ETA_WATER * (1.0 - cosI * cosI), 0.0));
            F = mix(F, 1.0, smoothstep(0.15, 0.0, cosT));
            col = mix(trans, refl, F);
            col += lightTint() * lightIntensity() * crinkle * crinkle * 0.12 * uRipple; // the window ripples too
        }
        col += pool;
        col = mix(col, foamCol, foam * 0.7);
        col = applyWater(col, vWorld);
        alpha = 1.0;
    } else {
        float cosI = clamp(dot(-I, N), 0.0, 1.0);
        float F = fresnelSchlick(cosI, 0.02);
        vec3 R = reflect(I, N);
        vec3 env = toLinear(texture(uEnv, equirect(R)).rgb) * 0.25 + ROOM;
        // glitter (the real tank from above): the chop tilts countless tiny facets to the lamps, so short white
        // streaks flicker all over the lit surface, stretched along the current. Two warped reads of the caustic
        // tile, kept only where both lines cross a threshold, under a broad lobe toward each fixture. The steep facets
        // that make them reflect far more than the flat-surface Fresnel, so they add on top of it.
        vec2 gq = vWorld.xz + N.xz * 8.0;
        float g1 = texture(uCaustic, gq * vec2(0.035, 0.11) + uTime * vec2(0.06, -0.035)).r;
        float g2 = texture(uCaustic, gq * vec2(0.05, 0.08) - uTime * vec2(0.041, 0.067)).r;
        float glitter = smoothstep(0.06, 0.3, g1) * smoothstep(0.02, 0.12, g2) * uRipple;
        vec3 glint = vec3(0.0);
        vec3 sparkle = vec3(0.0);
        for (int i = 0; i < 2; i++) {
            vec3 L = normalize(uLightPos[i].xyz - vWorld);
            float rl = max(dot(R, L), 0.0);
            glint += uLightColor[i].rgb * (pow(rl, 300.0) * 4.0 + pow(rl, 1500.0) * 12.0 * uRipple);
            sparkle += uLightColor[i].rgb * (0.25 + rl * rl) * glitter;
        }
        float sp = min(dot(sparkle, vec3(0.3)), 0.6);
        alpha = clamp(F + 0.06 + dot(pool, vec3(0.3)) + sp, 0.0, 1.0);
        // the fixture glints reach the eye at their Fresnel weight once (straight alpha would scale them by F twice)
        col = env * F + glint * (F / alpha) + uFog.rgb * 0.05 + pool * 0.6 + sparkle * (1.5 / alpha);
        col = mix(col, foamCol, foam);
        alpha = max(alpha, foam * 0.85);
    }
    fragColor = vec4(tonemap(col), alpha);
}

assets/shaders/water.vert:
#version 300 es
#include "common.glsl"
// Water surface grid at the water level (TankDims.WATER_LEVEL_CM, 38.1), displaced by the simulated heightfield (SIMULATION §9.7).

layout(location = 0) in vec3 aPos;
layout(location = 1) in vec3 aNormal;
layout(location = 2) in vec2 aUv;
layout(location = 3) in vec4 aColor;

uniform mat4 uModel;

out vec3 vWorld;
out vec3 vNormal;
out vec2 vUv;
out vec4 vColor;

void main() {
    vec4 w = uModel * vec4(aPos, 1.0);
    w.y += surfaceHeight(w.xz) + swell(w.xz, 5).x;
    vWorld = w.xyz;
    vNormal = vec3(0.0, 1.0, 0.0);
    vUv = aUv;
    vColor = aColor;
    gl_Position = uViewProj * w;
}

